CancelCheck = Callable[[], bool]


def _worker_count(name: str, default: int) -> int:
    try:
        return max(1, int(os.getenv(name, str(default))))
    except ValueError:
        return default


DEFAULT_MATCH_WORKERS = _worker_count("CITATION_EXPLORER_MATCH_WORKERS", 16)
DEFAULT_CONTEXT_WORKERS = _worker_count("CITATION_EXPLORER_CONTEXT_WORKERS", 12)
