# Why a readable citing paper ended without a verified passage.
# Deterministic stage (nothing for the model to confirm):
#   no_entry            target not found in the paper at all
#   entry_no_marker     bibliography entry found, no in-text marker known
#   marker_no_sentence  marker known, no body sentence carries it
# Verifier stage (the model saw the paper):
#   model_not_found         model reports the target is absent
#   model_bibliography_only model reports a reference-list entry only
#   model_no_quote          model says in_text but gave no quote
#   model_quote_not_found   model quote not located in the paper text
#   passage_failed_validation  a deterministic passage failed the checks
#   no_model_answer         the verifier returned nothing for the paper
DROP_REASONS = (
    "no_entry",
    "entry_no_marker",
    "marker_no_sentence",
    "model_not_found",
    "model_bibliography_only",
    "model_no_quote",
    "model_quote_not_found",
    "passage_failed_validation",
    "no_model_answer",
)
# A dropped paper whose ``bibliography_only`` flag is set still proved that
# it cites the target in its reference list: a true drive-by citation. A
# dropped paper without that flag is "unlocated": the system could not place
# the citation, and it must not count as drive-by.
