@dataclass
class TargetPaper:
    """Resolved target paper metadata."""

    query: str
    doi: str | None = None
    paperclip_id: str | None = None
    title: str = ""
    pmid: str | None = None
    arxiv_id: str | None = None
    year: int | None = None
    authors: str = ""
    source: str = ""
    version_aliases: list[dict[str, Any]] = field(default_factory=list)
    # Short names citing papers use for this work (dataset/model names),
    # mined from their own citation sentences. Never from outside APIs.
    aliases: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class CitationContext:
    """One in-text use of the target inside a citing paper."""

    section: str = ""
    line: int | None = None
    text: str = ""
    citation_key: str = ""
    block_id: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class MatchedCitingPaper:
    """A citing work after Paperclip matching and optional context extraction."""

    title: str = ""
    doi: str | None = None
    pmid: str | None = None
    arxiv_id: str | None = None
    year: int | None = None
    providers: list[str] = field(default_factory=list)
    target_aliases: list[str] = field(default_factory=list)
    paperclip_id: str | None = None
    has_fulltext: bool = False
    bibliography_only: bool = False
    contexts: list[CitationContext] = field(default_factory=list)
    citation_lines: list[int] = field(default_factory=list)
    summary: str = ""
    impact_role: str = "unclassified"
    reuse_tags: list[str] = field(default_factory=list)
    limitation_signal: bool = False
    wrongly_interpreted: bool = False
    citation_stance: str = "none"
    analysis_status: str = "not_mapped"
    match_method: str | None = None
    # Marker the target carries in this paper's bibliography ("[16]",
    # "Ouyang et al. 2020") and the entry text. Kept even when no body
    # sentence was located, so the verifier can search for the marker.
    citation_marker: str = ""
    reference_entry: str = ""
    # Why a full-text paper ended without a verified passage. One of
    # DROP_REASONS; empty for papers that kept a passage.
    drop_reason: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            **{k: v for k, v in asdict(self).items() if k != "contexts"},
            "contexts": [c.to_dict() for c in self.contexts],
        }


@dataclass
class CitationHighlight:
    """One verified quotation selected for the scorecard."""

    paperclip_id: str = ""
    paper_title: str = ""
    paper_year: int | None = None
    role: str = "drive_by"
    text: str = ""
    line: int | None = None
    citation_key: str = ""

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class ImportanceScore:
    """How citing papers use the target, as a constrained label + short sentence.

    ``score`` is an ordinal for sorting/storage only:
    0=unscored, 1=marginal, 2=supporting, 3=foundational.
    ``rationale`` holds the one-sentence usage summary (API-compatible name).
    """

    score: int = 0
    label: str = "marginal"
    rationale: str = ""
    evidence: list[str] = field(default_factory=list)
    method: str = "none"  # agent | reduce | llm | heuristic | empty
    prompt: str = ""

    def to_dict(self) -> dict[str, Any]:
        payload = asdict(self)
        # Expose the sentence under both names for newer UIs.
        payload["summary"] = self.rationale
        return payload


@dataclass
class AnalysisResult:
    """Final typed result of a citation-explorer run."""

    target: TargetPaper
    counts: dict[str, int] = field(default_factory=dict)
    checks: dict[str, Any] = field(default_factory=dict)
    provider_edge_counts: dict[str, int] = field(default_factory=dict)
    provider_errors: dict[str, str] = field(default_factory=dict)
    citing_papers: list[MatchedCitingPaper] = field(default_factory=list)
    themes: str = ""
    importance: ImportanceScore | None = None
    candidates: list[dict[str, Any]] = field(default_factory=list)
    cancelled: bool = False
    error: str | None = None
    target_summary: str = ""
    category_counts: dict[str, int] = field(default_factory=dict)
    reach: dict[str, Any] = field(default_factory=dict)
    citation_momentum: dict[str, Any] = field(default_factory=dict)
    highlighted_quotes: list[CitationHighlight] = field(default_factory=list)
    timings_ms: dict[str, int] = field(default_factory=dict)
    work_counts: dict[str, int] = field(default_factory=dict)
    # Soft outcome for empty/partial runs (shown in UI, not a hard failure).
    notice: str | None = None
    # Machine-readable outcome for UI branching.
    # ok | unsupported_input | resolve_failed | providers_unavailable |
    # insufficient_citations | limited_fulltext | cancelled | error
    outcome: str = "ok"

    def to_dict(self) -> dict[str, Any]:
        return {
            "target": self.target.to_dict(),
            "counts": dict(self.counts),
            "checks": dict(self.checks),
            "provider_edge_counts": dict(self.provider_edge_counts),
            "provider_errors": dict(self.provider_errors),
            "citing_papers": [p.to_dict() for p in self.citing_papers],
            "themes": self.themes,
            "importance": self.importance.to_dict() if self.importance else None,
            "candidates": list(self.candidates),
            "cancelled": self.cancelled,
            "error": self.error,
            "target_summary": self.target_summary,
            "category_counts": dict(self.category_counts),
            "reach": dict(self.reach),
            "citation_momentum": dict(self.citation_momentum),
            "highlighted_quotes": [
                highlight.to_dict() for highlight in self.highlighted_quotes
            ],
            "timings_ms": dict(self.timings_ms),
            "work_counts": dict(self.work_counts),
            "notice": self.notice,
            "outcome": self.outcome,
        }


def target_paper_from_dict(payload: dict[str, Any]) -> TargetPaper:
    """Rebuild target metadata from a durable scorecard payload."""
    allowed = {
        "query",
        "doi",
        "paperclip_id",
        "title",
        "pmid",
        "arxiv_id",
        "year",
        "authors",
        "source",
        "version_aliases",
        "aliases",
    }
    values = {key: payload[key] for key in allowed if key in payload}
    values.setdefault("query", "")
    if not isinstance(values.get("aliases"), list):
        values.pop("aliases", None)
    return TargetPaper(**values)


def matched_paper_from_dict(payload: dict[str, Any]) -> MatchedCitingPaper:
    """Rebuild one citing paper from a durable scorecard payload."""
    contexts = [
        CitationContext(
            **{
                key: context[key]
                for key in {"section", "line", "text", "citation_key", "block_id"}
                if key in context
            }
        )
        for context in payload.get("contexts") or []
        if isinstance(context, dict)
    ]
    allowed = {
        "title",
        "doi",
        "pmid",
        "arxiv_id",
        "year",
        "providers",
        "target_aliases",
        "paperclip_id",
        "has_fulltext",
        "bibliography_only",
        "citation_lines",
        "summary",
        "impact_role",
        "reuse_tags",
        "limitation_signal",
        "wrongly_interpreted",
        "citation_stance",
        "analysis_status",
        "match_method",
        "citation_marker",
        "reference_entry",
        "drop_reason",
    }
    values = {key: payload[key] for key in allowed if key in payload}
    return MatchedCitingPaper(contexts=contexts, **values)


def _deduplicate_matched_papers(
    papers: list[MatchedCitingPaper],
) -> list[MatchedCitingPaper]:
    """Merge provider records that resolve to the same citing paper."""
    merged: dict[str, MatchedCitingPaper] = {}
    unkeyed = 0
    for paper in papers:
        if paper.paperclip_id:
            key = f"paperclip:{paper.paperclip_id.lower()}"
        elif paper.doi:
            key = f"doi:{paper.doi.lower()}"
        elif paper.pmid:
            key = f"pmid:{paper.pmid}"
        else:
            unkeyed += 1
            key = f"unkeyed:{unkeyed}"
        existing = merged.get(key)
        if existing is None:
            merged[key] = paper
            continue
        existing.providers = list(
            dict.fromkeys([*existing.providers, *paper.providers])
        )
        existing.target_aliases = list(
            dict.fromkeys([*existing.target_aliases, *paper.target_aliases])
        )
        existing.has_fulltext = existing.has_fulltext or paper.has_fulltext
        for field_name in (
            "title",
            "doi",
            "pmid",
            "arxiv_id",
            "year",
            "paperclip_id",
            "match_method",
        ):
            if not getattr(existing, field_name) and getattr(paper, field_name):
                setattr(existing, field_name, getattr(paper, field_name))
    return list(merged.values())


def _target_sampling_key(target: TargetPaper) -> str:
    """Return one stable key for all queries that resolve to the same paper."""
    for kind, value in (
        ("paperclip", target.paperclip_id),
        ("doi", normalize_doi(target.doi or "")),
        ("arxiv", target.arxiv_id),
        ("pmid", target.pmid),
        ("title", normalize_title(target.title or "")),
    ):
        normalized = str(value or "").strip().lower()
        if normalized:
            return f"{kind}:{normalized}"
    return f"query:{normalize_title(target.query or '')}"


def _matched_paper_sampling_key(paper: MatchedCitingPaper) -> str:
    """Return a stable identity for one citing-paper candidate."""
    return "|".join(
        (
            paper.paperclip_id or "",
            normalize_doi(paper.doi or "") or "",
            paper.arxiv_id or "",
            paper.pmid or "",
            normalize_title(paper.title or ""),
        )
    )


def _select_fulltext_sample(
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    limit: int = DEFAULT_MAP_LIMIT,
) -> list[MatchedCitingPaper]:
    """Select a reproducible random sample of readable citing papers."""
    readable = [
        paper for paper in papers if paper.has_fulltext and paper.paperclip_id
    ]
    if len(readable) <= limit:
        return readable

    seed_key = _target_sampling_key(target)
    ranked = sorted(
        readable,
        key=lambda paper: hashlib.sha256(
            f"{seed_key}|{_matched_paper_sampling_key(paper)}".encode()
        ).hexdigest(),
    )
    selected_ids = {id(paper) for paper in ranked[:limit]}
    return [paper for paper in readable if id(paper) in selected_ids]


def _ordered_match_candidates(
    records: list[CitingRecord],
    target: TargetPaper,
) -> list[CitingRecord]:
    """Balance exact years and citer-impact bands with deterministic reserves."""
    seed_key = _target_sampling_key(target)

    def sort_key(record: CitingRecord) -> tuple[int, str]:
        if record.paperclip_id:
            priority = 0
        elif record.arxiv_id or record.preprint_doi or record.pmid:
            priority = 1
        elif record.doi:
            priority = 2
        elif record.title:
            priority = 3
        else:
            priority = 4
        record_key = "|".join(
            (
                record.paperclip_id or "",
                record.arxiv_id or "",
                record.preprint_doi or "",
                record.pmid or "",
                record.doi or "",
                record.openalex_id or "",
                normalize_title(record.title or ""),
            )
        )
        tie_breaker = hashlib.sha256(
            f"{seed_key}|{record_key}".encode()
        ).hexdigest()
        return priority, tie_breaker

    def impact_band(record: CitingRecord) -> int:
        count = max(0, int(record.citation_count or 0))
        if count == 0:
            return 0
        if count < 10:
            return 1
        if count < 100:
            return 2
        return 3

    groups: dict[tuple[int | None, int], list[CitingRecord]] = {}
    for record in records:
        groups.setdefault((record.year, impact_band(record)), []).append(record)
    for group in groups.values():
        group.sort(key=sort_key)

    group_keys = sorted(
        groups,
        key=lambda key: (
            key[0] is None,
            key[0] if key[0] is not None else 0,
            key[1],
        ),
    )
    ordered: list[CitingRecord] = []
    offset = 0
    while True:
        added = False
        for key in group_keys:
            group = groups[key]
            if offset < len(group):
                ordered.append(group[offset])
                added = True
        if not added:
            return ordered
        offset += 1


def _match_until_readable_limit(
    client: Any,
    records: list[CitingRecord],
    target: TargetPaper,
    *,
    readable_limit: int = DEFAULT_MAP_LIMIT,
    attempt_limit: int = DEFAULT_MATCH_ATTEMPT_LIMIT,
    match_workers: int = DEFAULT_MATCH_WORKERS,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> tuple[list[MatchedCitingPaper], int]:
    """Match bounded batches and stop after enough unique readable papers."""
    ordered = _ordered_match_candidates(records, target)
    attempt_budget = min(len(ordered), max(readable_limit, attempt_limit))
    workers = max(1, match_workers)
    matched: list[MatchedCitingPaper] = []
    readable_ids: set[str] = set()
    attempted = 0
    completed = 0

    # Keep ``workers`` lookups in flight at all times instead of waiting for
    # each batch's slowest call. Stop submitting once enough readable papers
    # are found, so the overshoot stays below one batch.
    candidates = iter(ordered[:attempt_budget])
    with ThreadPoolExecutor(max_workers=workers) as pool:
        pending: dict[Any, CitingRecord] = {}

        def _submit_next() -> bool:
            nonlocal attempted
            record = next(candidates, None)
            if record is None:
                return False
            pending[pool.submit(match_citing_record, client, record)] = record
            attempted += 1
            return True

        for _ in range(workers):
            if not _submit_next():
                break
        while pending:
            done_futures, _ = wait(pending, return_when=FIRST_COMPLETED)
            for future in done_futures:
                record = pending.pop(future)
                if _cancelled(cancel) or len(readable_ids) >= readable_limit:
                    continue
                try:
                    paper = future.result()
                except Exception as exc:  # noqa: BLE001
                    paper = MatchedCitingPaper(
                        title=record.title,
                        doi=record.doi,
                        pmid=record.pmid,
                        arxiv_id=record.arxiv_id,
                        providers=list(record.providers),
                        target_aliases=list(record.target_aliases),
                    )
                    logger.debug("match failed: %s", exc)
                matched.append(paper)
                completed += 1
                if paper.has_fulltext and paper.paperclip_id:
                    readable_ids.add(paper.paperclip_id)
                emit_event(
                    on_event,
                    "match",
                    status="progress",
                    completed=completed,
                    total=attempt_budget,
                    readable=len(readable_ids),
                    current_item=(
                        record.title
                        or record.doi
                        or record.pmid
                        or "Citing paper"
                    ),
                )
            if _cancelled(cancel) or len(readable_ids) >= readable_limit:
                for future in pending:
                    future.cancel()
                break
            while len(pending) < workers and _submit_next():
                pass

    return _deduplicate_matched_papers(matched), attempted


def emit_event(
    callback: EventCallback | None,
    event_type: str,
    **payload: Any,
) -> dict[str, Any]:
    """Build and optionally deliver a progress event."""
    event = {"type": event_type, **payload}
    if callback is not None:
        callback(event)
    return event


def _cancelled(cancel: CancelCheck | None) -> bool:
    return bool(cancel and cancel())


def looks_like_pdf_query(query: str) -> bool:
    """Return True when the query looks like a PDF path or PDF URL."""
    text = (query or "").strip()
    if not text:
        return False
    lowered = text.lower()
    if lowered.endswith(".pdf"):
        return True
    parsed = urlparse(text)
    if parsed.scheme in ("http", "https") and parsed.path.lower().endswith(".pdf"):
        return True
    return False


def format_doi_resolve_error(err: str | None, *, query: str = "") -> str:
    """Return a user-facing message when DOI resolution fails."""
    if looks_like_pdf_query(query):
        return PDF_UNSUPPORTED_MESSAGE
    detail = (err or "").strip()
    if not detail:
        return DOI_UNRESOLVED_MESSAGE
    # Keep short validation errors; replace opaque/technical resolve failures.
    if detail in {"Query is empty"} or detail.startswith("Invalid select DOI:"):
        return detail
    if detail.startswith("No Paperclip papers matched"):
        return (
            f"{detail} "
            "If you have a DOI or publisher page URL, paste that instead."
        )
    if detail in {SCHOLAR_AUTHOR_PROFILE_MESSAGE, SCHOLAR_CITED_BY_MESSAGE}:
        return detail
    return DOI_UNRESOLVED_MESSAGE


def format_provider_fetch_error(exc: BaseException | str) -> str:
    """Return a user-facing message when citation API collection fails hard."""
    del exc
    return PROVIDERS_UNAVAILABLE_MESSAGE


def assess_empty_citation_outcome(
    *,
    provider_errors: dict[str, str],
    citing_count: int,
) -> tuple[str, str, str]:
    """Classify an empty citing-paper set.

    Returns ``(outcome, error_or_empty, notice_or_empty)``.
    """
    if citing_count > 0:
        return "ok", "", ""
    list_failed = [
        name for name in _LIST_CITATION_PROVIDERS if name in provider_errors
    ]
    list_ok = [
        name for name in _LIST_CITATION_PROVIDERS if name not in provider_errors
    ]
    if not list_ok and list_failed:
        return "providers_unavailable", PROVIDERS_UNAVAILABLE_MESSAGE, ""
    return "insufficient_citations", "", NOT_ENOUGH_CITATIONS_MESSAGE


def assess_fulltext_notice(
    *,
    citing_count: int,
    in_text_uses: int,
    readable_fulltext: int,
    provider_errors: dict[str, str],
) -> str | None:
    """Return a soft notice when results exist but passages are thin."""
    if citing_count <= 0:
        return None
    if in_text_uses <= 0 and readable_fulltext <= 0:
        return LIMITED_FULLTEXT_MESSAGE
    if provider_errors and any(
        name in provider_errors for name in _LIST_CITATION_PROVIDERS
    ):
        return PARTIAL_PROVIDERS_MESSAGE
    return None


def _empty_counts(
    *, unique_citing: int = 0, total_citations: int | None = None
) -> dict[str, int]:
    return {
        "provider_edges": 0,
        "unique_citing": unique_citing,
        "total_citations": (
            unique_citing if total_citations is None else total_citations
        ),
        "paperclip_matches": 0,
        "readable_fulltext": 0,
        "paperclip_fulltext": 0,
        "in_text_uses": 0,
        "bibliography_only": 0,
    }


def classify_query(query: str) -> tuple[str, str]:
    """Classify user input as DOI, corpus identifier, URL, or title.

    Returns ``(kind, normalized_value)``.
    """
    text = (query or "").strip()
    if not text:
        return "empty", ""

    pmc_match = re.fullmatch(r"(?i)(?:pmcid:\s*)?(PMC\d+)", text)
    if pmc_match:
        return "pmc", pmc_match.group(1).upper()

    pmid_match = re.fullmatch(r"(?i)(?:pmid:\s*)?(\d{6,9})", text)
    if pmid_match:
        return "pmid", pmid_match.group(1)

    doi = normalize_doi(text)
    if doi and (
        text.lower().startswith("10.")
        or "doi.org/" in text.lower()
        or text.lower().startswith("doi:")
    ):
        return "doi", doi

    arxiv = extract_arxiv_id(text)
    if arxiv and (
        "arxiv" in text.lower()
        or re.fullmatch(r"\d{4}\.\d{4,5}(?:v\d+)?", text.strip())
    ):
        return "arxiv", arxiv

    parsed = urlparse(text)
    if parsed.scheme in ("http", "https") and parsed.netloc:
        if doi:
            return "doi", doi
        if arxiv:
            return "arxiv", arxiv
        return "url", text

    if doi and " " not in text and "/" in text:
        return "doi", doi

    return "title", text


def _doi_from_json_ld(value: Any) -> str | None:
    """Read DOI-specific fields from JSON-LD without scanning article text."""
    if isinstance(value, list):
        for item in value:
            doi = _doi_from_json_ld(item)
            if doi:
                return doi
        return None
    if not isinstance(value, dict):
        return None

    for key in ("doi", "DOI"):
        doi = normalize_doi(value.get(key))
        if doi:
            return doi
    for key in ("sameAs", "@id"):
        raw = value.get(key)
        values = raw if isinstance(raw, list) else [raw]
        for item in values:
            if isinstance(item, str) and "doi.org/" in item.lower():
                doi = normalize_doi(item)
                if doi:
                    return doi
    identifier = value.get("identifier")
    identifiers = identifier if isinstance(identifier, list) else [identifier]
    for item in identifiers:
        if isinstance(item, dict):
            property_id = str(item.get("propertyID") or "").lower()
            if property_id == "doi":
                doi = normalize_doi(item.get("value"))
                if doi:
                    return doi
        elif isinstance(item, str) and (
            item.lower().startswith("doi:") or "doi.org/" in item.lower()
        ):
            doi = normalize_doi(item)
            if doi:
                return doi
    graph = value.get("@graph")
    return _doi_from_json_ld(graph) if graph is not None else None


def extract_doi_from_html(html: str) -> str | None:
    """Pull a DOI only from trusted page-identity metadata."""
    for pattern in (_HTML_DOI_META_RE, _HTML_DOI_META_RE_ALT):
        match = pattern.search(html)
        if match:
            return normalize_doi(match.group(1))
    for pattern in (_HTML_CANONICAL_DOI_RE, _HTML_CANONICAL_DOI_RE_ALT):
        match = pattern.search(html)
        if match:
            return normalize_doi(urllib_unquote(match.group(1)))
    for match in _JSON_LD_RE.finditer(html or ""):
        try:
            payload = json.loads(html_unescape(match.group(1)).strip())
        except (json.JSONDecodeError, TypeError):
            continue
        doi = _doi_from_json_ld(payload)
        if doi:
            return doi
    ieee_doi = _doi_from_ieee_html(html)
    if ieee_doi:
        return ieee_doi
    # Do not scan arbitrary page text. The first DOI there is often a
    # reference, not the DOI of the page itself.
    return None


# Elsevier/Cell PII. Publisher pages use both formatted values such as
# S2666-3899(23)00130-7 and compact values such as S2666389923001307.
_ELSEVIER_PII_RE = re.compile(
    r"(?i)(?<![A-Z0-9])"
    r"(S(?:\d{4}-\d{3,4}\(\d{2}\)\d{4,7}-\d|\d{16}))"
    r"(?![A-Z0-9])"
)
_NATURE_ARTICLE_RE = re.compile(
    r"(?i)nature\.com/articles/(s\d{4,}-\d{2,}-\d+)"
)
_PMC_URL_RE = re.compile(r"(?i)/pmc/articles/(PMC\d+)")
_PUBMED_URL_RE = re.compile(
    r"(?i)(?:pubmed\.ncbi\.nlm\.nih\.gov/|ncbi\.nlm\.nih\.gov/pubmed/)(\d+)"
)
_MDPI_ARTICLE_RE = re.compile(
    r"(?i)(?:www\.)?mdpi\.com/"
    r"(?P<issn>\d{4}-[\dX]{4})/"
    r"(?P<volume>\d+)/(?P<issue>\d+)/(?P<article>\d+)(?:/|$)"
)
_IEEE_ARTICLE_RE = re.compile(
    r"(?i)(?:ieeexplore\.ieee\.org/(?:abstract/)?document/|[?&]arnumber=)(\d{5,})"
)
_SCHOLAR_HOST_RE = re.compile(r"(?i)(?:^|\.)scholar\.google\.")
_SCHOLAR_DOI_LINK_RE = re.compile(
    r"""(?i)href=["']https?://(?:dx\.)?doi\.org/([^"'?#\s]+)"""
)
_SCHOLAR_RESULT_RE = re.compile(
    r"""(?is)<h3[^>]*class=["'][^"']*\bgs_rt\b[^"']*["'][^>]*>.*?<a[^>]+href=["']([^"']+)["'][^>]*>(.*?)</a>.*?</h3>"""
)
_SCHOLAR_CITATION_RE = re.compile(
    r"""(?is)<a[^>]*class=["'][^"']*\bgsc_oci_title_link\b[^"']*["'][^>]+href=["']([^"']+)["'][^>]*>(.*?)</a>"""
)
_SCHOLAR_ARXIV_RE = re.compile(
    r"""(?i)https?://(?:www\.)?arxiv\.org/(?:abs|pdf)/(\d{4}\.\d{4,5})(?:v\d+)?"""
)
_HTML_TITLE_META_RE = re.compile(
    r"""(?is)<meta[^>]+(?:name|property)=["'](?:citation_title|dc\.title|og:title)["'][^>]+content=["']([^"']+)["']"""
)
_HTML_TITLE_META_RE_ALT = re.compile(
    r"""(?is)<meta[^>]+content=["']([^"']+)["'][^>]+(?:name|property)=["'](?:citation_title|dc\.title|og:title)["']"""
)


def extract_publisher_ids_from_url(url: str) -> dict[str, str]:
    """Extract publisher-native identifiers from a paper URL path."""
    parsed = urlparse(url)
    path = urllib_unquote(parsed.path or "")
    ids: dict[str, str] = {}
    pii = _ELSEVIER_PII_RE.search(path) or _ELSEVIER_PII_RE.search(url)
    if pii:
        ids["pii"] = pii.group(1).upper().replace(" ", "")
    nature = _NATURE_ARTICLE_RE.search(url)
    if nature:
        ids["nature_id"] = nature.group(1).lower()
    pmc = _PMC_URL_RE.search(url)
    if pmc:
        ids["pmcid"] = pmc.group(1).upper()
    pubmed = _PUBMED_URL_RE.search(url)
    if pubmed:
        ids["pmid"] = pubmed.group(1)
    arxiv = extract_arxiv_id(url)
    if arxiv:
        ids["arxiv"] = arxiv
    ieee = _IEEE_ARTICLE_RE.search(url)
    if ieee:
        ids["ieee_article"] = ieee.group(1)
    return ids


def arxiv_doi_for_id(arxiv_id: str | None) -> str | None:
    """Return the canonical arXiv DOI (``10.48550/arxiv.<id>``) for an arXiv id."""
    aid = extract_arxiv_id(arxiv_id)
    if not aid:
        return None
    return f"10.48550/arxiv.{aid}"


def resolve_doi_via_openalex_arxiv(arxiv_id: str | None) -> str | None:
    """Resolve a DOI for an arXiv id via OpenAlex (published DOI preferred)."""
    aid = extract_arxiv_id(arxiv_id)
    if not aid:
        return None
    from .citation_providers import get_json

    urls = (
        f"https://api.openalex.org/works/https://arxiv.org/abs/{aid}",
        f"https://api.openalex.org/works/https://doi.org/10.48550/arxiv.{aid}",
    )
    for url in urls:
        try:
            payload = get_json(url)
        except Exception as exc:  # noqa: BLE001
            logger.debug("OpenAlex arXiv lookup failed for %s: %s", aid, exc)
            continue
        if not isinstance(payload, dict):
            continue
        doi = normalize_doi(payload.get("doi"))
        if doi:
            return doi
        ids = payload.get("ids") or {}
        doi = normalize_doi(ids.get("doi"))
        if doi:
            return doi
    return None


def resolve_doi_via_openalex_title(title: str) -> str | None:
    """Resolve a DOI from an exact-enough OpenAlex title search."""
    query = (title or "").strip()
    if len(query.split()) < 4:
        return None
    from .citation_providers import _query, get_json

    try:
        payload = get_json(
            _query(
                "https://api.openalex.org/works",
                {"search": query, "per-page": 5},
            )
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("OpenAlex title lookup failed: %s", exc)
        return None
    results = payload.get("results") if isinstance(payload, dict) else None
    if not results:
        return None
    query_title = normalize_title(query)
    best_doi: str | None = None
    best_score = 0.0
    for row in results:
        if not isinstance(row, dict):
            continue
        name = str(row.get("display_name") or row.get("title") or "")
        score = SequenceMatcher(
            None, query_title, normalize_title(name)
        ).ratio()
        doi = normalize_doi(row.get("doi"))
        if not doi:
            ids = row.get("ids") if isinstance(row.get("ids"), dict) else {}
            doi = normalize_doi((ids or {}).get("doi"))
        if doi and score > best_score:
            best_score = score
            best_doi = doi
    if best_score >= 0.92:
        return best_doi
    return None


def _search_openalex_title_works(title: str) -> list[dict[str, Any]]:
    """One-shot OpenAlex title search. Fail soft; do not retry."""
    from .citation_providers import _query

    try:
        request = Request(
            _query(
                "https://api.openalex.org/works",
                {"search": title, "per-page": 5},
            ),
            headers={"Accept": "application/json", "User-Agent": user_agent()},
        )
        with urlopen(request, timeout=8) as response:
            payload = json.load(response)
    except Exception as exc:  # noqa: BLE001
        logger.warning("OpenAlex version lookup failed: %s", exc)
        return []
    results = payload.get("results") if isinstance(payload, dict) else None
    if not results:
        return []
    return [row for row in results if isinstance(row, dict)]


def resolve_version_dois_via_openalex(
    title: str,
    *,
    year: int | None = None,
    current_doi: str | None = None,
) -> list[dict[str, Any]]:
    """Return preprint/published sibling DOIs from an OpenAlex title search."""
    query = (title or "").strip()
    if len(query.split()) < 4:
        return []
    results = _search_openalex_title_works(query)
    if not results:
        return []
    query_title = normalize_title(query)
    current = normalize_doi(current_doi)
    aliases: list[dict[str, Any]] = []
    for row in results:
        if not isinstance(row, dict):
            continue
        name = str(row.get("display_name") or row.get("title") or "")
        score = SequenceMatcher(None, query_title, normalize_title(name)).ratio()
        if score < 0.92:
            continue
        doi = normalize_doi(row.get("doi"))
        if not doi:
            ids = row.get("ids") if isinstance(row.get("ids"), dict) else {}
            doi = normalize_doi((ids or {}).get("doi"))
        if not doi or doi == current:
            continue
        if current and _is_preprint_doi(current) == _is_preprint_doi(doi):
            continue
        row_year: int | None
        try:
            row_year = int(row.get("publication_year") or row.get("year"))
        except (TypeError, ValueError):
            row_year = None
        if (
            year is not None
            and row_year is not None
            and abs(int(year) - row_year) > 3
        ):
            continue
        aliases.append({"doi": doi, "paperclip_id": None, "year": row_year})
    return aliases


def resolve_doi_via_ieee_article(article_number: str) -> str | None:
    """Resolve an IEEE Xplore article number to a DOI."""
    number = re.sub(r"\D", "", article_number or "")
    if len(number) < 5:
        return None
    from .citation_providers import get_json

    try:
        payload = get_json(
            f"https://ieeexplore.ieee.org/rest/document/{number}"
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug("IEEE REST lookup failed for %s: %s", number, exc)
        payload = None
    if isinstance(payload, dict):
        doi = normalize_doi(payload.get("doi") or payload.get("DOI"))
        if doi:
            return doi

    html = _fetch_unlocked_html(
        f"https://ieeexplore.ieee.org/document/{number}"
    )
    if html:
        doi = extract_doi_from_html(html) or _doi_from_ieee_html(html)
        if doi:
            return doi
    return None


def _fetch_unlocked_html(url: str) -> str:
    """Fetch HTML through Bright Data when the unlocker is configured."""
    key = os.environ.get("BRIGHTDATA_API_KEY", "").strip()
    zone = (
        os.environ.get("BRIGHTDATA_WEB_UNLOCKER_ZONE") or "gxl_unlocker"
    ).strip()
    if not key or not zone:
        return ""
    request = Request(
        "https://api.brightdata.com/request",
        data=json.dumps({"zone": zone, "url": url, "format": "raw"}).encode(
            "utf-8"
        ),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    with urlopen(request, timeout=45) as response:
        return response.read().decode("utf-8", errors="replace")


def _doi_from_ieee_html(html: str) -> str | None:
    """Read the DOI from IEEE Xplore page metadata JavaScript."""
    anchor = (html or "").find("xplGlobal.document.metadata")
    if anchor < 0:
        return None
    match = re.search(
        r'"doi"\s*:\s*"(10\.1109/[^"]+)"',
        html[anchor : anchor + 8000],
        re.I,
    )
    return normalize_doi(match.group(1)) if match else None


def resolve_doi_from_identifiers(
    *,
    doi: str | None = None,
    pmid: str | None = None,
    pmcid: str | None = None,
    arxiv_id: str | None = None,
    prefer_arxiv_doi: bool = True,
) -> str | None:
    """Resolve a DOI from common bibliographic identifiers.

    Order: explicit DOI → PMCID → PMID → OpenAlex arXiv → arXiv DOI.
    """
    direct = normalize_doi(doi)
    if direct:
        return direct

    if pmcid:
        pmc = pmcid.strip().upper()
        if not pmc.startswith("PMC"):
            pmc = f"PMC{pmc}"
        try:
            found = resolve_doi_via_europepmc(f"PMCID:{pmc}")
        except Exception as exc:  # noqa: BLE001
            logger.warning("Europe PMC PMCID lookup failed for %s: %s", pmc, exc)
            found = None
        if found:
            return found

    if pmid:
        try:
            found = resolve_doi_via_europepmc(f"EXT_ID:{str(pmid).strip()}")
        except Exception as exc:  # noqa: BLE001
            logger.warning("Europe PMC PMID lookup failed for %s: %s", pmid, exc)
            found = None
        if found:
            return found

    if arxiv_id:
        try:
            found = resolve_doi_via_openalex_arxiv(arxiv_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("OpenAlex arXiv DOI lookup failed for %s: %s", arxiv_id, exc)
            found = None
        if found:
            return found
        if prefer_arxiv_doi:
            return arxiv_doi_for_id(arxiv_id)
    return None


def resolve_doi_from_url_identifiers(url: str) -> str | None:
    """Resolve a DOI from identifiers embedded in a URL (no HTML fetch)."""
    ids = extract_publisher_ids_from_url(url)
    direct = normalize_doi(url)
    if direct and ("doi.org/" in url.lower() or url.lower().startswith("10.")):
        return direct
    # bioRxiv / medRxiv DOIs are often in the path as 10.1101/...
    path_doi = normalize_doi(urlparse(url).path or "")
    if path_doi and path_doi.startswith("10.1101/"):
        # Strip trailing version suffixes like v1 / v2 from preprint URLs.
        return re.sub(r"v\d+$", "", path_doi)
    pii = ids.get("pii")
    if pii:
        try:
            doi = resolve_doi_via_crossref_elsevier_pii(pii)
            if doi:
                return doi
            doi = resolve_doi_via_europepmc(pii)
            if doi:
                return doi
            return resolve_doi_via_crossref_query(pii)
        except Exception as exc:  # noqa: BLE001 - HTML remains a fallback
            logger.warning("DOI lookup for PII %s failed: %s", pii, exc)
    ieee_article = ids.get("ieee_article")
    if ieee_article:
        try:
            doi = resolve_doi_via_ieee_article(ieee_article)
            if doi:
                return doi
        except Exception as exc:  # noqa: BLE001 - HTML remains a fallback
            logger.warning(
                "DOI lookup for IEEE article %s failed: %s", ieee_article, exc
            )
    return resolve_doi_from_identifiers(
        pmcid=ids.get("pmcid"),
        pmid=ids.get("pmid"),
        arxiv_id=ids.get("arxiv"),
    )


def is_google_scholar_url(url: str) -> bool:
    """Return True for Google Scholar hosts in any country domain."""
    return bool(_SCHOLAR_HOST_RE.search((urlparse(url).hostname or "").lower()))


def google_scholar_non_paper_error(url: str) -> str | None:
    """Return a user-facing error for Scholar links that name no single paper.

    An author profile (``/citations?user=...`` without ``citation_for_view``)
    and a "Cited by" list (``/scholar?cites=...``) have no paper of their own.
    Their page titles are a person's name or a search heading, so the title
    fallback produced unrelated candidates and users picked wrong papers.
    """
    if not is_google_scholar_url(url):
        return None
    parsed = urlparse(url)
    path = (parsed.path or "").rstrip("/").lower()
    params = parse_qs(parsed.query)
    view_op = (params.get("view_op") or [""])[0].strip().lower()
    if path.endswith("/citations"):
        has_paper = bool((params.get("citation_for_view") or [""])[0].strip())
        if not has_paper and (view_op != "view_citation"):
            if (params.get("user") or [""])[0].strip():
                return SCHOLAR_AUTHOR_PROFILE_MESSAGE
    if path.endswith("/scholar") and (params.get("cites") or [""])[0].strip():
        return SCHOLAR_CITED_BY_MESSAGE
    return None


def extract_google_scholar_hints(
    url: str,
    html: str = "",
) -> dict[str, str]:
    """Extract a destination URL, DOI, or title from a Scholar paper URL."""
    parsed = urlparse(url)
    if not _SCHOLAR_HOST_RE.search((parsed.hostname or "").lower()):
        return {}

    hints: dict[str, str] = {}
    params = parse_qs(parsed.query)
    destination = (params.get("url") or [""])[0].strip()
    if destination:
        destination = urllib_unquote(destination)
        hints["destination_url"] = urljoin(url, destination)
        direct_doi = normalize_doi(destination)
        if direct_doi:
            hints["doi"] = direct_doi

    # A Scholar search-result URL can carry the exact title in q.
    scholar_query = (params.get("q") or [""])[0].strip()
    if scholar_query and len(scholar_query.split()) >= 3:
        hints["title"] = scholar_query.strip('"')

    if not html:
        return hints

    doi_link = _SCHOLAR_DOI_LINK_RE.search(html)
    if doi_link:
        doi = normalize_doi(urllib_unquote(doi_link.group(1)))
        if doi:
            hints["doi"] = doi

    for pattern in (_HTML_TITLE_META_RE, _HTML_TITLE_META_RE_ALT):
        title_match = pattern.search(html)
        if title_match:
            hints["title"] = html_unescape(title_match.group(1)).strip()
            break

    result_match = _SCHOLAR_CITATION_RE.search(html) or _SCHOLAR_RESULT_RE.search(html)
    if result_match:
        result_url, title_html = result_match.groups()
        result_url = html_unescape(result_url).strip()
        absolute_result_url = urljoin(url, result_url)
        if result_url and not is_google_scholar_url(absolute_result_url):
            hints.setdefault("destination_url", absolute_result_url)
        elif result_url:
            nested = extract_google_scholar_hints(absolute_result_url)
            if nested.get("destination_url"):
                hints.setdefault("destination_url", nested["destination_url"])
            if nested.get("doi"):
                hints.setdefault("doi", nested["doi"])
        title = re.sub(r"<[^>]+>", "", title_html)
        title = re.sub(r"^\s*\[[^\]]+\]\s*", "", html_unescape(title)).strip()
        if title:
            hints["title"] = title
    arxiv_match = _SCHOLAR_ARXIV_RE.search(html)
    if arxiv_match:
        arxiv_id = arxiv_match.group(1)
        hints.setdefault("destination_url", f"https://arxiv.org/abs/{arxiv_id}")
        arxiv_doi = arxiv_doi_for_id(arxiv_id)
        if arxiv_doi:
            hints.setdefault("doi", arxiv_doi)
    return hints


def fetch_google_scholar_hints_via_serpapi(
    url: str,
    *,
    api_key: str | None = None,
) -> dict[str, str]:
    """Resolve one Scholar author-publication URL through SerpApi.

    This is an optional fallback for Scholar HTTP 429 responses. It is used
    only when ``SERPAPI_API_KEY`` is configured.
    """
    key = (api_key or os.environ.get("SERPAPI_API_KEY") or "").strip()
    if not key or not is_google_scholar_url(url):
        return {}

    params = parse_qs(urlparse(url).query)
    author_id = (params.get("user") or [""])[0].strip()
    citation_id = (params.get("citation_for_view") or [""])[0].strip()
    if not author_id or not citation_id:
        return {}

    query = urlencode(
        {
            "engine": "google_scholar_author",
            "author_id": author_id,
            "view_op": "view_citation",
            "citation_id": citation_id,
            "hl": "en",
            "api_key": key,
        }
    )
    request = Request(
        f"https://serpapi.com/search.json?{query}",
        headers={"User-Agent": user_agent()},
    )
    with urlopen(request, timeout=30) as response:
        payload = json.loads(response.read().decode("utf-8"))

    if not isinstance(payload, dict):
        return {}
    if payload.get("error"):
        raise ValueError(str(payload["error"]))

    citation = payload.get("citation") or {}
    if not isinstance(citation, dict):
        return {}

    hints: dict[str, str] = {}
    title = str(citation.get("title") or "").strip()
    destination = str(citation.get("link") or "").strip()
    if title:
        hints["title"] = title
    if destination:
        hints["destination_url"] = destination
        doi = normalize_doi(destination)
        if doi:
            hints["doi"] = doi
    return hints


def _google_scholar_fetch_was_blocked(
    error: BaseException | None = None,
    *,
    html: str = "",
) -> bool:
    """Return True only for a clear Google Scholar anti-bot response."""
    if isinstance(error, HTTPError) and error.code in {403, 429}:
        return True
    evidence = f"{error or ''}\n{html}".lower()
    return any(
        cue in evidence
        for cue in (
            "http 403",
            "http 429",
            "captcha",
            "not a robot",
            "our systems have detected unusual traffic",
            "/sorry/",
        )
    )


def fetch_google_scholar_hints_via_brightdata(
    url: str,
    *,
    api_key: str | None = None,
    zone: str | None = None,
) -> dict[str, str]:
    """Fetch a blocked Scholar page through Bright Data Web Unlocker."""
    key = (api_key or os.environ.get("BRIGHTDATA_API_KEY") or "").strip()
    zone_name = (
        zone
        or os.environ.get("BRIGHTDATA_WEB_UNLOCKER_ZONE")
        or "gxl_unlocker"
    ).strip()
    if not key or not zone_name or not is_google_scholar_url(url):
        return {}

    request = Request(
        "https://api.brightdata.com/request",
        data=json.dumps(
            {"zone": zone_name, "url": url, "format": "raw"}
        ).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    with urlopen(request, timeout=45) as response:
        html = response.read().decode("utf-8", errors="replace")
    return extract_google_scholar_hints(url, html)


def _fetch_html_page(
    url: str,
    *,
    opener: Callable[[str], str] | None = None,
) -> str:
    if opener is not None:
        return opener(url)
    request = Request(
        url,
        headers={
            "User-Agent": (
                "Mozilla/5.0 (compatible; GXL-Citation-Explorer/0.1; "
                "+https://gxl.ai; mailto:dev@gxl.ai)"
            ),
            "Accept": "text/html,application/xhtml+xml",
        },
    )
    with urlopen(request, timeout=30) as response:
        charset = response.headers.get_content_charset() or "utf-8"
        return response.read(512_000).decode(charset, errors="replace")


def resolve_doi_via_europepmc(query: str) -> str | None:
    """Resolve a DOI through Europe PMC search (PII, PMCID, title fragment, etc.)."""
    from .citation_providers import _query, get_json

    payload = get_json(
        _query(
            "https://www.ebi.ac.uk/europepmc/webservices/rest/search",
            {"query": query, "format": "json", "pageSize": 5},
        )
    )
    rows = (payload.get("resultList") or {}).get("result") or []
    for row in rows:
        doi = normalize_doi(row.get("doi"))
        if doi:
            return doi
    return None


def resolve_doi_via_crossref_query(query: str) -> str | None:
    """Best-effort Crossref bibliographic lookup for a publisher id or title."""
    from .citation_providers import _query, get_json

    contact = __import__("os").getenv("CITATIONS_CONTACT_EMAIL", "dev@gxl.ai")
    payload = get_json(
        _query(
            "https://api.crossref.org/works",
            {
                "query.bibliographic": query,
                "rows": 5,
                "mailto": contact,
            },
        )
    )
    items = (payload.get("message") or {}).get("items") or []
    query_norm = query.lower().replace(" ", "")
    for item in items:
        doi = normalize_doi(item.get("DOI"))
        if not doi:
            continue
        # Prefer exact alternative-id / PII matches when present.
        alts = item.get("alternative-id") or []
        if any(str(a).lower().replace(" ", "") == query_norm for a in alts):
            return doi
    # Fall back to first result only when the query looks like a PII/id.
    if items and _ELSEVIER_PII_RE.search(query):
        # Crossref often fails to rank Elsevier PIIs first; skip weak matches.
        return None
    return normalize_doi(items[0].get("DOI")) if items else None


def resolve_doi_via_crossref_elsevier_pii(pii: str) -> str | None:
    """Resolve an Elsevier PII by checking its standard DOI form."""
    value = (pii or "").strip().upper()
    compact = re.fullmatch(
        r"S(\d{4})(\d{4})(\d{2})(\d{5})(\d)",
        value,
    )
    if compact:
        value = (
            f"S{compact.group(1)}-{compact.group(2)}"
            f"({compact.group(3)}){compact.group(4)}-{compact.group(5)}"
        )
    candidate = normalize_doi(f"10.1016/{value}")
    if not candidate:
        return None

    from .citation_providers import get_json

    endpoint = (
        "https://api.crossref.org/works/"
        f"{quote(candidate, safe='')}"
    )
    try:
        payload = get_json(endpoint)
    except Exception as exc:  # noqa: BLE001 - other PII resolvers remain
        logger.debug("Crossref direct PII lookup failed for %s: %s", pii, exc)
        return None
    message = payload.get("message") if isinstance(payload, dict) else None
    if not isinstance(message, dict):
        return None
    return normalize_doi(message.get("DOI"))


def resolve_doi_via_crossref_mdpi_url(url: str) -> str | None:
    """Resolve an MDPI article URL from its ISSN and issue coordinates."""
    match = _MDPI_ARTICLE_RE.search(url)
    if not match:
        return None

    from .citation_providers import _query, get_json

    coordinates = match.groupdict()
    endpoint = (
        "https://api.crossref.org/journals/"
        f"{coordinates['issn'].upper()}/works"
    )
    try:
        payload = get_json(
            _query(
                endpoint,
                {
                    "query.bibliographic": " ".join(
                        (
                            coordinates["volume"],
                            coordinates["issue"],
                            coordinates["article"],
                        )
                    ),
                    "rows": 20,
                },
            )
        )
    except Exception as exc:  # noqa: BLE001 - publisher HTML can still resolve it
        logger.warning("Crossref MDPI lookup failed for %s: %s", url, exc)
        return None
    items = (payload.get("message") or {}).get("items") or []
    for item in items:
        article_number = str(
            item.get("article-number") or item.get("page") or ""
        ).strip()
        if (
            str(item.get("volume") or "").strip() == coordinates["volume"]
            and str(item.get("issue") or "").strip() == coordinates["issue"]
            and article_number == coordinates["article"]
        ):
            doi = normalize_doi(item.get("DOI"))
            if doi:
                return doi
    return None


def fetch_doi_from_url(url: str, *, opener: Callable[[str], str] | None = None) -> str | None:
    """Resolve a publisher URL to a DOI.

    Order:
    1. Direct DOI / arXiv / PMC / PMID identifiers already in the URL
    2. HTML metadata from the page (when reachable)
    3. Publisher identifiers in the path (Elsevier PII, Nature id, ...) via Europe PMC
    """
    direct = normalize_doi(url)
    if direct and ("doi.org/" in url.lower() or url.lower().startswith("doi:")):
        return direct

    # Cheap identifier resolvers first — avoid blocked publisher HTML fetches.
    from_ids = resolve_doi_from_url_identifiers(url)
    if from_ids:
        return from_ids

    mdpi_doi = resolve_doi_via_crossref_mdpi_url(url)
    if mdpi_doi:
        return mdpi_doi

    html_error: Exception | None = None
    if opener is not None:
        try:
            html = opener(url)
            doi = extract_doi_from_html(html)
            if doi:
                return doi
        except Exception as exc:  # noqa: BLE001 - fall through to id lookup
            html_error = exc
    else:
        request = Request(
            url,
            headers={
                # Browser-like UA: some publishers (Cell/Elsevier) block library UAs.
                "User-Agent": (
                    "Mozilla/5.0 (compatible; GXL-Citation-Explorer/0.1; "
                    "+https://gxl.ai; mailto:dev@gxl.ai)"
                ),
                "Accept": "text/html,application/xhtml+xml",
            },
        )
        try:
            with urlopen(request, timeout=30) as response:
                charset = response.headers.get_content_charset() or "utf-8"
                html = response.read(512_000).decode(charset, errors="replace")
            doi = extract_doi_from_html(html)
            if doi:
                return doi
        except Exception as exc:  # noqa: BLE001
            html_error = exc

    ids = extract_publisher_ids_from_url(url)
    for key in ("pii", "pmcid", "pmid", "nature_id", "arxiv", "ieee_article"):
        value = ids.get(key)
        if not value:
            continue
        try:
            if key == "pmcid":
                doi = resolve_doi_from_identifiers(pmcid=value)
            elif key == "pmid":
                doi = resolve_doi_from_identifiers(pmid=value)
            elif key == "arxiv":
                doi = resolve_doi_from_identifiers(arxiv_id=value)
            elif key == "pii":
                doi = resolve_doi_via_europepmc(value) or resolve_doi_via_crossref_query(
                    value
                )
            elif key == "ieee_article":
                doi = resolve_doi_via_ieee_article(value)
            else:
                doi = resolve_doi_via_europepmc(value)
        except Exception as exc:  # noqa: BLE001
            logger.warning("DOI fallback via %s=%s failed: %s", key, value, exc)
            continue
        if doi:
            return doi

    if html_error is not None:
        raise html_error
    return None


def _paper_from_lookup_hit(hit: dict[str, Any]) -> dict[str, Any]:
    doc_id = (
        hit.get("document_id")
        or hit.get("id")
        or hit.get("pmc_id")
        or hit.get("paper_id")
        or ""
    )
    year = hit.get("pub_year") or hit.get("year")
    try:
        year_i = int(year) if year is not None else None
    except (TypeError, ValueError):
        year_i = None
    return {
        "paperclip_id": str(doc_id) if doc_id else None,
        "doi": normalize_doi(hit.get("doi")),
        "title": hit.get("title") or "",
        "pmid": str(hit["pmid"]) if hit.get("pmid") else None,
        "authors": hit.get("authors") or hit.get("first_author") or "",
        "year": year_i,
        "source": hit.get("source") or "",
        "arxiv_id": extract_arxiv_id(str(doc_id))
        if str(doc_id).startswith(("arx_", "arxiv"))
        else extract_arxiv_id(hit.get("doi")),
    }


def _hydrate_target_metadata(client: Any, target: TargetPaper) -> bool:
    """Load complete target metadata from its direct Paperclip path."""
    if not target.paperclip_id:
        return False
    metadata: dict[str, Any] = {}
    try:
        result = client.execute(
            "cat",
            [f"/papers/{target.paperclip_id}/meta.json"],
            timeout=60,
        )
        output = (getattr(result, "output", "") or "").lstrip()
        decoded, _end = json.JSONDecoder().raw_decode(output)
        if isinstance(decoded, dict):
            metadata = decoded
    except Exception as exc:  # noqa: BLE001
        logger.debug("Could not hydrate target authors: %s", exc)
    authors = metadata.get("authors")
    if isinstance(authors, list):
        authors = ", ".join(
            str(author.get("name") if isinstance(author, dict) else author)
            for author in authors
            if author
        )
    if isinstance(authors, str) and len(authors.strip()) > len(target.authors):
        target.authors = authors.strip()
    target.title = target.title or str(metadata.get("title") or "")
    target.pmid = target.pmid or (
        str(metadata["pmid"]) if metadata.get("pmid") else None
    )
    target.year = target.year or metadata.get("pub_year") or metadata.get("year")
    target.source = target.source or str(metadata.get("source") or "")
    if target.title:
        return True

    # Some arXiv slabs have readable full text but no meta.json. The first
    # content line is the paper title, so use it to unlock exact-title provider
    # alias discovery when metadata lookup is unavailable.
    if target.arxiv_id:
        try:
            content = _client_head(
                client,
                f"/papers/{target.paperclip_id}/content.lines",
                lines=3,
                timeout=30,
            )
            content_output = getattr(content, "output", "") or ""
            title_match = re.search(r"(?m)^\s*L?1\s*:\s*(.+?)\s*$", content_output)
            if title_match:
                target.title = title_match.group(1).strip()
                target.source = target.source or "arxiv"
        except Exception as exc:  # noqa: BLE001
            logger.debug("Could not hydrate arXiv target title: %s", exc)
    return bool(target.title)


_ANSI_RE = re.compile(r"\033\[[0-9;]*m")
# arXiv ids keep the dotted YYMM.NNNNN form (`arx_2310.00902`). bio/med short
# ids are hex-only. A hex-only arx_ group would cut `arx_2310.00902` at the
# first dot and look up the wrong paper in the citation graph.
_LOOKUP_BLOCK_RE = re.compile(
    r"(?m)^\s*\d+\.\s+(?P<title>.+?)\s*$"
    r"(?:\n\s+(?P<authors>.+?))?"
    r"\n\s+(?P<id>(?:PMC\d+|bio_[0-9a-f]+|med_[0-9a-f]+|"
    r"arx_[A-Za-z0-9._-]+|[0-9a-f-]{36}))"
    r"(?:\s*·\s*(?P<source>[^·\n]+))?"
    r"(?:\s*·\s*(?P<year>\d{4})(?:-\d{2}-\d{2})?)?",
)
_DOC_ID_LINE_RE = re.compile(
    r"(?m)^\s*((?:PMC\d+)|(?:bio_[0-9a-f]{8,})|(?:med_[0-9a-f]{8,})|"
    r"(?:arx_[A-Za-z0-9._-]{6,})|(?:[0-9a-f]{8}-[0-9a-f-]{27}))\b"
)


def _strip_ansi(text: str) -> str:
    return _ANSI_RE.sub("", text or "")


def _parse_lookup_text(output: str) -> list[dict[str, Any]]:
    """Parse Paperclip lookup CLI text into paper dicts."""
    text = _strip_ansi(output)
    papers: list[dict[str, Any]] = []
    for match in _LOOKUP_BLOCK_RE.finditer(text):
        year_raw = match.group("year")
        try:
            year = int(year_raw) if year_raw else None
        except ValueError:
            year = None
        source = (match.group("source") or "").strip()
        papers.append(
            {
                "paperclip_id": match.group("id"),
                "doi": None,
                "title": match.group("title").strip(),
                "pmid": None,
                "authors": (match.group("authors") or "").strip(),
                "year": year,
                "source": source,
                "arxiv_id": extract_arxiv_id(match.group("id")),
            }
        )
    if papers:
        return papers

    # Minimal fallback: collect bare document ids if formatting changes
    for match in _DOC_ID_LINE_RE.finditer(text):
        doc_id = match.group(1)
        papers.append(
            {
                "paperclip_id": doc_id,
                "doi": None,
                "title": "",
                "pmid": None,
                "authors": "",
                "year": None,
                "source": "",
                "arxiv_id": extract_arxiv_id(doc_id),
            }
        )
    return papers


def _lookup_papers(client: Any, field: str, value: str, *, limit: int = 5) -> list[dict[str, Any]]:
    """Run ``client.lookup`` and return normalized paper dicts."""
    try:
        # Prefer execute so we can request --json when the server supports it.
        result = client.execute(
            "lookup",
            [field, value, "-n", str(limit), "--json"],
            timeout=60,
        )
    except Exception:
        try:
            result = client.lookup(field, value, limit=limit)
        except Exception as exc:  # noqa: BLE001
            logger.warning("lookup %s %s failed: %s", field, value, exc)
            return []

    papers = list(getattr(result, "papers", None) or [])
    if papers:
        normalized = [_paper_from_lookup_hit(p) for p in papers if isinstance(p, dict)]
        if field == "doi":
            for item in normalized:
                item["doi"] = item.get("doi") or normalize_doi(value)
        return normalized

    output = getattr(result, "output", "") or ""
    if not output.strip():
        return []

    # Structured JSON body (rare today; keep for forward compatibility)
    stripped = _strip_ansi(output).strip()
    if stripped.startswith("{") or stripped.startswith("["):
        try:
            data = json.loads(stripped)
        except json.JSONDecodeError:
            data = None
        if isinstance(data, list):
            normalized = [_paper_from_lookup_hit(p) for p in data if isinstance(p, dict)]
        elif isinstance(data, dict):
            rows = data.get("papers") or data.get("results") or []
            normalized = [_paper_from_lookup_hit(p) for p in rows if isinstance(p, dict)]
        else:
            normalized = []
        if normalized:
            if field == "doi":
                for item in normalized:
                    item["doi"] = item.get("doi") or normalize_doi(value)
            return normalized

    parsed = _parse_lookup_text(output)
    if field == "doi":
        for item in parsed:
            item["doi"] = item.get("doi") or normalize_doi(value)
    if field == "pmid":
        for item in parsed:
            item["pmid"] = item.get("pmid") or value
    if field == "title" and len(parsed) == 1 and not parsed[0].get("title"):
        parsed[0]["title"] = value
    return parsed


def _metadata_title_key(value: Any) -> str:
    """Normalize typographic punctuation before exact title comparison."""
    normalized = normalize_title(
        str(value or "").translate(
            str.maketrans(
                {
                    "‘": "'",
                    "’": "'",
                    "“": '"',
                    "”": '"',
                    "‐": "-",
                    "‑": "-",
                    "–": "-",
                    "—": "-",
                }
            )
        )
    )
    return " ".join(normalized.split())


def _hydrate_target_from_exact_title(client: Any, target: TargetPaper) -> bool:
    """Fill missing target metadata from an exact Paperclip title match."""
    normalized_target = _metadata_title_key(target.title)
    if not normalized_target:
        return False
    hits = _lookup_papers(
        client,
        "title",
        target.title,
        limit=MAX_TITLE_CANDIDATES,
    )
    hit = next(
        (
            candidate
            for candidate in hits
            if _metadata_title_key(candidate.get("title")) == normalized_target
        ),
        None,
    )
    if hit is None:
        hit = next(
            (
                candidate
                for candidate in _search_papers(
                    client,
                    target.title,
                    limit=MAX_TITLE_CANDIDATES,
                )
                if _metadata_title_key(candidate.get("title")) == normalized_target
            ),
            None,
        )
    if hit is None:
        return False

    target.paperclip_id = target.paperclip_id or hit.get("paperclip_id")
    target.pmid = target.pmid or hit.get("pmid")
    target.authors = target.authors or hit.get("authors") or ""
    target.year = target.year or hit.get("year")
    target.source = target.source or hit.get("source") or ""
    target.arxiv_id = target.arxiv_id or hit.get("arxiv_id")
    _hydrate_target_metadata(client, target)
    return True


def _search_papers(client: Any, query: str, *, limit: int = 10) -> list[dict[str, Any]]:
    """Use Paperclip search when metadata lookup cannot resolve free text."""
    try:
        result = client.search(query, limit=limit, timeout=60)
    except Exception:
        try:
            result = client.execute(
                "search",
                [query, "-n", str(limit), "--json"],
                timeout=60,
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Paperclip search failed for %s: %s", query, exc)
            return []
    papers = list(getattr(result, "papers", None) or [])
    if papers:
        return [_paper_from_lookup_hit(paper) for paper in papers if isinstance(paper, dict)]
    output = getattr(result, "output", "") or ""
    stripped = _strip_ansi(output).strip()
    if stripped.startswith("{") or stripped.startswith("["):
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError:
            payload = None
        if isinstance(payload, dict):
            rows = payload.get("papers") or payload.get("results") or []
        elif isinstance(payload, list):
            rows = payload
        else:
            rows = []
        normalized = [
            _paper_from_lookup_hit(paper) for paper in rows if isinstance(paper, dict)
        ]
        if normalized:
            return normalized
    return _parse_lookup_text(output)


def _rank_resolution_candidates(
    query: str,
    candidates: list[dict[str, Any]],
) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    """Rank Paperclip matches and auto-select only a high-confidence title match."""
    query_title = normalize_title(query)
    scored: list[tuple[float, dict[str, Any]]] = []
    for candidate in candidates:
        candidate_title = normalize_title(candidate.get("title"))
        score = (
            SequenceMatcher(None, query_title, candidate_title).ratio()
            if query_title and candidate_title
            else 0.0
        )
        scored.append((score, candidate))
    scored.sort(
        key=lambda item: (
            item[0],
            int(item[1].get("year") or 0),
            bool(item[1].get("doi")),
        ),
        reverse=True,
    )
    ordered = [candidate for _, candidate in scored]
    exact = [
        candidate
        for score, candidate in scored
        if score == 1.0 and candidate.get("doi")
    ]
    if len(exact) == 1:
        return exact[0], ordered
    published = [
        candidate for candidate in exact if not _is_preprint_doi(candidate.get("doi"))
    ]
    preprints = [
        candidate for candidate in exact if _is_preprint_doi(candidate.get("doi"))
    ]
    if len(published) == 1 and preprints:
        return published[0], ordered
    if not scored or not scored[0][1].get("doi"):
        return None, ordered

    top_score = scored[0][0]
    next_score = scored[1][0] if len(scored) > 1 else 0.0
    # Require near-exact similarity and a clear margin. This prevents a search
    # result's rank from silently becoming an identity assertion.
    if top_score >= 0.92 and (top_score - next_score) >= 0.08:
        return scored[0][1], ordered
    return None, ordered


def _target_version_aliases(
    target: TargetPaper,
    candidates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return exact-title preprint or published versions of the target."""
    target_doi = normalize_doi(target.doi)
    target_title = normalize_title(target.title)
    if not target_doi or not target_title:
        return []

    aliases: list[dict[str, Any]] = []
    seen_dois = {target_doi}
    for candidate in candidates:
        candidate_doi = normalize_doi(candidate.get("doi"))
        if (
            not candidate_doi
            or candidate_doi in seen_dois
            or normalize_title(candidate.get("title")) != target_title
            or _is_preprint_doi(candidate_doi) == _is_preprint_doi(target_doi)
        ):
            continue
        target_year = target.year
        candidate_year = candidate.get("year")
        if (
            target_year is not None
            and candidate_year is not None
            and abs(int(target_year) - int(candidate_year)) > 3
        ):
            continue
        aliases.append(
            {
                "doi": candidate_doi,
                "paperclip_id": candidate.get("paperclip_id"),
                "year": candidate_year,
            }
        )
        seen_dois.add(candidate_doi)
    return aliases


def _merge_version_aliases(
    *groups: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Dedupe version aliases by DOI, keeping the first complete row."""
    merged: list[dict[str, Any]] = []
    seen: set[str] = set()
    for group in groups:
        for alias in group:
            doi = normalize_doi(alias.get("doi"))
            if not doi or doi in seen:
                continue
            seen.add(doi)
            merged.append({**alias, "doi": doi})
    return merged


def _client_head(client: Any, path: str, *, lines: int = 5, timeout: float = 30):
    """Call ``head`` via ``client.papers.head`` or ``client.execute``."""
    papers_api = getattr(client, "papers", None)
    if papers_api is not None and hasattr(papers_api, "head"):
        return papers_api.head(path, lines=lines, timeout=timeout)
    if hasattr(client, "head"):
        try:
            return client.head(path, lines=lines, timeout=timeout)
        except TypeError:
            return client.head(path, timeout=timeout)
    return client.execute("head", ["-n", str(lines), path], timeout=timeout)


def _has_readable_fulltext(client: Any, paperclip_id: str) -> bool:
    """True when ``/papers/<id>/content.lines`` returns readable content."""
    path = f"/papers/{paperclip_id}/content.lines"
    try:
        result = _client_head(client, path, lines=5, timeout=30)
    except Exception as exc:  # noqa: BLE001
        logger.debug("head %s failed: %s", path, exc)
        return False
    if getattr(result, "exit_code", 1) != 0:
        return False
    output = (getattr(result, "output", "") or "").strip()
    if not output:
        return False
    # Reject obvious missing-file messages
    lowered = output.lower()
    if "no such file" in lowered or "not found" in lowered or "error" in lowered[:40]:
        return False
    return True


def _prefer_arxiv_paperclip_id(
    paperclip_id: str | None,
    arxiv_id: str | None,
) -> str | None:
    """Keep a corpus arXiv id, restoring the dotted form when lookup truncated it.

    Lookup text used to match ``arx_`` plus hex only, so ``arx_2310.00902``
    became ``arx_2310``. The citation graph keys the full dotted id.
    """
    pid = (paperclip_id or "").strip() or None
    aid = (arxiv_id or "").strip() or None
    if not aid:
        return pid
    expected = f"arx_{aid}"
    if pid is None or pid == expected:
        return expected
    if pid.startswith("arx_") and expected.startswith(pid):
        return expected
    return pid


def resolve_target(
    client: Any,
    query: str,
    *,
    select_doi: str | None = None,
    url_opener: Callable[[str], str] | None = None,
    on_event: EventCallback | None = None,
) -> tuple[TargetPaper | None, list[dict[str, Any]], str | None]:
    """Resolve a user query to a single target paper.

    Returns ``(target, candidates, error)``. When multiple title matches exist
    and ``select_doi`` is not provided, ``target`` is None and ``candidates``
    is populated for the UI to choose from.
    """
    if select_doi:
        doi = normalize_doi(select_doi)
        if not doi:
            return None, [], f"Invalid select DOI: {select_doi}"
        hits = _lookup_papers(client, "doi", doi, limit=5)
        arxiv_id = extract_arxiv_id(doi)
        if not hits and arxiv_id:
            hits = _lookup_papers(client, "arxiv", arxiv_id, limit=5)
        target = TargetPaper(query=query, doi=doi, arxiv_id=arxiv_id)
        if hits:
            hit = hits[0]
            target.paperclip_id = _prefer_arxiv_paperclip_id(
                hit.get("paperclip_id"),
                hit.get("arxiv_id") or arxiv_id,
            )
            target.title = hit.get("title") or ""
            target.pmid = hit.get("pmid")
            target.authors = hit.get("authors") or ""
            target.year = hit.get("year")
            target.source = hit.get("source") or ""
            target.arxiv_id = hit.get("arxiv_id") or arxiv_id
        elif arxiv_id:
            target.paperclip_id = f"arx_{arxiv_id}"
        hydrated = _hydrate_target_metadata(client, target)
        if not hits and not hydrated:
            target.paperclip_id = None
        if target.title:
            title_hits = _lookup_papers(
                client,
                "title",
                target.title,
                limit=MAX_TITLE_CANDIDATES,
            )
            target.version_aliases = _merge_version_aliases(
                _target_version_aliases(target, title_hits),
                resolve_version_dois_via_openalex(
                    target.title,
                    year=target.year,
                    current_doi=target.doi,
                ),
            )
        emit_event(on_event, "resolve", status="ok", target=target.to_dict())
        return target, [], None

    if looks_like_pdf_query(query):
        return None, [], PDF_UNSUPPORTED_MESSAGE

    kind, value = classify_query(query)
    emit_event(on_event, "resolve", status="started", kind=kind, value=value)

    if kind == "empty":
        return None, [], "Query is empty"

    if kind in {"pmid", "pmc"}:
        lookup_field = "pmid" if kind == "pmid" else "pmc"
        hits = _lookup_papers(client, lookup_field, value, limit=3)
        hit = hits[0] if hits else {}
        doi = normalize_doi(hit.get("doi"))
        if not doi:
            europe_query = (
                f"EXT_ID:{value}" if kind == "pmid" else f"PMCID:{value}"
            )
            try:
                doi = resolve_doi_via_europepmc(europe_query)
            except Exception as exc:  # noqa: BLE001
                logger.warning("%s DOI lookup failed for %s: %s", kind, value, exc)
        if doi:
            return resolve_target(
                client,
                doi,
                select_doi=doi,
                on_event=on_event,
            )
        return None, [], f"No DOI found for {value}"

    if kind == "url":
        if is_google_scholar_url(value):
            non_paper_error = google_scholar_non_paper_error(value)
            if non_paper_error:
                emit_event(
                    on_event,
                    "resolve",
                    status="scholar_not_a_paper",
                    url=value,
                )
                return None, [], non_paper_error
            hints = extract_google_scholar_hints(value)
            scholar_blocked = False
            # Profile / view_citation links need the HTML page for title + publisher URL.
            # Redirect links may already carry a DOI or destination in the query string.
            if not hints.get("doi") and (
                not hints.get("destination_url") or not hints.get("title")
            ):
                try:
                    scholar_html = _fetch_html_page(value, opener=url_opener)
                    hints.update(extract_google_scholar_hints(value, scholar_html))
                    scholar_blocked = _google_scholar_fetch_was_blocked(
                        html=scholar_html
                    )
                except (HTTPError, URLError, TimeoutError, OSError, ValueError) as exc:
                    logger.warning("Google Scholar page fetch failed: %s", exc)
                    scholar_blocked = _google_scholar_fetch_was_blocked(exc)

            # Bright Data is a paid fallback. Use it only after a clear Scholar
            # anti-bot response, never for ordinary misses or network failures.
            if (
                scholar_blocked
                and os.environ.get("BRIGHTDATA_API_KEY")
                and not hints.get("doi")
                and (not hints.get("destination_url") or not hints.get("title"))
            ):
                try:
                    hints.update(fetch_google_scholar_hints_via_brightdata(value))
                    if hints:
                        emit_event(
                            on_event,
                            "resolve",
                            status="scholar_brightdata_fallback",
                            title=hints.get("title"),
                            destination=hints.get("destination_url"),
                        )
                except (HTTPError, URLError, TimeoutError, OSError, ValueError) as exc:
                    logger.warning("Bright Data Scholar lookup failed: %s", exc)

            # Scholar commonly returns HTTP 429 to server requests. SerpApi
            # supports this exact author-publication identifier and returns the
            # title plus publisher link. Keep it optional so local use does not
            # require a paid service.
            if (
                os.environ.get("SERPAPI_API_KEY")
                and not hints.get("doi")
                and (not hints.get("destination_url") or not hints.get("title"))
            ):
                try:
                    hints.update(fetch_google_scholar_hints_via_serpapi(value))
                    if hints:
                        emit_event(
                            on_event,
                            "resolve",
                            status="scholar_serpapi_fallback",
                            title=hints.get("title"),
                            destination=hints.get("destination_url"),
                        )
                except (HTTPError, URLError, TimeoutError, OSError, ValueError) as exc:
                    logger.warning("SerpApi Scholar lookup failed: %s", exc)

            if hints.get("doi"):
                doi = hints["doi"]
                emit_event(
                    on_event,
                    "resolve",
                    status="scholar_resolved",
                    doi=doi,
                    url=value,
                )
                return resolve_target(
                    client,
                    doi,
                    select_doi=doi,
                    on_event=on_event,
                )

            # Prefer the publisher landing page, but publishers often block bots
            # (HTTP 403). Recover DOI from URL identifiers, then title fallback.
            destination = hints.get("destination_url")
            title = hints.get("title")
            last_error: str | None = None
            if destination:
                id_doi = resolve_doi_from_url_identifiers(destination)
                if id_doi:
                    emit_event(
                        on_event,
                        "resolve",
                        status="scholar_id_doi",
                        doi=id_doi,
                        destination=destination,
                    )
                    return resolve_target(
                        client,
                        id_doi,
                        select_doi=id_doi,
                        on_event=on_event,
                    )
                target, candidates, err = resolve_target(
                    client,
                    destination,
                    url_opener=url_opener,
                    on_event=on_event,
                )
                if target is not None or candidates:
                    return target, candidates, err
                last_error = err
                logger.warning(
                    "Scholar destination resolve failed for %s: %s",
                    destination,
                    err,
                )
            if title:
                emit_event(
                    on_event,
                    "resolve",
                    status="scholar_title_fallback",
                    title=title,
                    destination=destination,
                    prior_error=last_error,
                )
                return resolve_target(
                    client,
                    title,
                    on_event=on_event,
                )
            return None, [], (
                last_error
                or (
                    "Could not resolve this Google Scholar URL. Use a Scholar paper "
                    "result link, a DOI, or the exact paper title."
                )
            )

        try:
            doi = fetch_doi_from_url(value, opener=url_opener)
        except (HTTPError, URLError, TimeoutError, OSError, ValueError) as exc:
            return None, [], (
                "Could not resolve DOI from URL "
                f"(page blocked or unknown publisher id): {exc}"
            )
        if not doi:
            return None, [], "No DOI found for this URL"
        emit_event(on_event, "resolve", status="url_resolved", doi=doi, url=value)
        return resolve_target(
            client,
            doi,
            select_doi=doi,
            on_event=on_event,
        )

    if kind == "doi":
        return resolve_target(
            client,
            value,
            select_doi=value,
            on_event=on_event,
        )

    if kind == "arxiv":
        hits = _lookup_papers(client, "arxiv", value, limit=5)
        hit = hits[0] if hits else {}
        doi = resolve_doi_from_identifiers(
            doi=hit.get("doi"),
            pmid=hit.get("pmid"),
            arxiv_id=value,
        )
        if doi:
            emit_event(
                on_event,
                "resolve",
                status="arxiv_doi",
                doi=doi,
                arxiv_id=value,
            )
            return resolve_target(
                client,
                doi,
                select_doi=doi,
                on_event=on_event,
            )
        if not hit:
            return None, [], f"No DOI found for arXiv:{value}"
        target = TargetPaper(
            query=query,
            doi=None,
            paperclip_id=hit.get("paperclip_id"),
            title=hit.get("title") or "",
            pmid=hit.get("pmid"),
            arxiv_id=value,
            year=hit.get("year"),
            authors=hit.get("authors") or "",
            source=hit.get("source") or "",
        )
        _hydrate_target_metadata(client, target)
        emit_event(on_event, "resolve", status="ok", target=target.to_dict())
        return target, [], None

    # title
    hits = _lookup_papers(client, "title", value, limit=MAX_TITLE_CANDIDATES)
    if not hits:
        hits = _search_papers(client, value, limit=MAX_TITLE_CANDIDATES)
    if not hits:
        doi = resolve_doi_via_openalex_title(value)
        if doi:
            emit_event(
                on_event,
                "resolve",
                status="openalex_title_doi",
                doi=doi,
                title=value,
            )
            return resolve_target(
                client,
                doi,
                select_doi=doi,
                on_event=on_event,
            )
        return None, [], f"No Paperclip papers matched input: {value}"

    # Attach DOIs from PMC / PMID / arXiv ids before ranking/selection.
    for hit in hits:
        if hit.get("doi"):
            continue
        paperclip_id = str(hit.get("paperclip_id") or "")
        pmcid = hit.get("pmcid")
        if not pmcid and paperclip_id.upper().startswith("PMC"):
            pmcid = paperclip_id
        arxiv_id = hit.get("arxiv_id")
        if not arxiv_id and paperclip_id.startswith("arx_"):
            arxiv_id = paperclip_id.removeprefix("arx_")
        enriched = resolve_doi_from_identifiers(
            pmid=hit.get("pmid"),
            pmcid=pmcid,
            arxiv_id=arxiv_id,
        )
        if enriched:
            hit["doi"] = enriched

    selected, ordered = _rank_resolution_candidates(value, hits)
    if selected and selected.get("doi"):
        emit_event(
            on_event,
            "resolve",
            status="rules_selected",
            doi=selected["doi"],
        )
        return resolve_target(
            client,
            selected["doi"],
            select_doi=selected["doi"],
            on_event=on_event,
        )

    if len(ordered) > 1 or (ordered and ordered[0].get("doi")):
        candidates = ordered[:MAX_TITLE_CANDIDATES]
        emit_event(
            on_event,
            "candidates",
            candidates=candidates,
            message="Multiple papers matched this title. Select one DOI to continue.",
        )
        return None, candidates, None

    hit = ordered[0]
    if hit.get("doi"):
        return resolve_target(
            client,
            hit["doi"],
            select_doi=hit["doi"],
            on_event=on_event,
        )

    target = TargetPaper(
        query=query,
        doi=None,
        paperclip_id=hit.get("paperclip_id"),
        title=hit.get("title") or "",
        pmid=hit.get("pmid"),
        arxiv_id=hit.get("arxiv_id"),
        year=hit.get("year"),
        authors=hit.get("authors") or "",
        source=hit.get("source") or "",
    )
    _hydrate_target_metadata(client, target)
    emit_event(on_event, "resolve", status="ok", target=target.to_dict())
    return target, [], None


def match_citing_record(
    client: Any,
    record: CitingRecord,
) -> MatchedCitingPaper:
    """Match one citer, preferring a direct GXL Paperclip identifier."""
    matched = MatchedCitingPaper(
        title=record.title,
        doi=record.doi,
        pmid=record.pmid,
        arxiv_id=record.arxiv_id,
        year=record.year,
        providers=list(record.providers),
        target_aliases=list(record.target_aliases),
    )

    if record.paperclip_id:
        matched.paperclip_id = record.paperclip_id
        matched.match_method = "gxl_direct"
        matched.has_fulltext = _has_readable_fulltext(client, record.paperclip_id)
        return matched

    attempts: list[tuple[str, str, str]] = []
    if record.doi:
        attempts.append(("doi", record.doi, "doi"))
    if record.pmid:
        attempts.append(("pmid", str(record.pmid), "pmid"))
    if record.arxiv_id:
        attempts.append(("arxiv", record.arxiv_id, "arxiv"))
    if record.preprint_doi:
        attempts.append(("doi", record.preprint_doi, "preprint_doi"))
    if record.title:
        attempts.append(("title", record.title, "title"))

    for field_name, value, method in attempts:
        hits = _lookup_papers(client, field_name, value, limit=3)
        if not hits:
            if method == "arxiv":
                direct_id = f"arx_{value}"
                if _has_readable_fulltext(client, direct_id):
                    matched.paperclip_id = direct_id
                    matched.match_method = "arxiv_direct"
                    matched.has_fulltext = True
                    break
            continue
        if method == "title":
            # Require exact normalized title to avoid false positives
            hits = [
                h
                for h in hits
                if normalize_title(h.get("title")) == normalize_title(value)
            ]
            if not hits:
                continue
        hit = hits[0]
        pid = hit.get("paperclip_id")
        if not pid:
            continue
        matched.paperclip_id = pid
        matched.match_method = method
        if not matched.title:
            matched.title = hit.get("title") or matched.title
        if not matched.doi:
            matched.doi = hit.get("doi")
        if not matched.pmid:
            matched.pmid = hit.get("pmid")
        matched.has_fulltext = _has_readable_fulltext(client, pid)
        break

    return matched


def parse_lookup_citation_output(output: str) -> tuple[str, list[CitationContext], bool]:
    """Parse ``lookup-citation`` text output.

    Returns ``(citation_key, contexts, bibliography_only)``.
    ``bibliography_only`` is True when a reference entry exists but no body uses.
    """
    text = output or ""
    key_match = _LOOKUP_CITATION_KEY_RE.search(text)
    citation_key = key_match.group(1) if key_match else ""

    if "no reference found matching" in text.lower():
        return citation_key, [], False

    if "no in-text mentions found" in text.lower():
        return citation_key, [], True

    contexts: list[CitationContext] = []
    current_section = ""
    current_lines: list[str] = []
    current_line_no: int | None = None
    current_block: str | None = None

    def _flush() -> None:
        nonlocal current_lines, current_line_no, current_block
        if current_lines:
            contexts.append(
                CitationContext(
                    section=current_section,
                    line=current_line_no,
                    text="\n".join(current_lines).strip(),
                    citation_key=citation_key,
                    block_id=current_block,
                )
            )
        current_lines = []
        current_line_no = None
        current_block = None

    for raw_line in text.splitlines():
        mention = _LOOKUP_MENTION_RE.match(raw_line.strip())
        if mention:
            _flush()
            current_section = mention.group(2).strip()
            continue
        line_match = _LOOKUP_LINE_RE.match(raw_line)
        if line_match:
            marker, block_id, content = line_match.groups()
            if marker.strip() == ">>>":
                try:
                    current_line_no = int(block_id)
                except ValueError:
                    current_line_no = None
                current_block = block_id
            current_lines.append(content)
            continue

    _flush()
    bibliography_only = bool(citation_key) and not contexts
    return citation_key, contexts, bibliography_only


_GREP_LINE_RE = re.compile(r"^L(\d+)(:|-)\s*(.*)$")
_REF_NUM_RE = re.compile(
    r"(?i)(?:^|\s)(?:\[(\d+)\]|(\d+)\.\s+[A-Z]|ref(?:erence)?\s*(\d+))"
)
# Springer-style run-on lists: "... (2018)5. Ouyang, D., ..." — the next
# entry number follows the previous entry's closing parenthesis or period.
_RUNON_REF_NUM_RE = re.compile(r"(?<=[)\].])(\d{1,4})\.\s+[A-Z]")
_NUMBERED_NOUN_RE = re.compile(
    r"(?i)\b(?:fig(?:ure|s)?|table|video|section|sec|supplementary|eq(?:uation)?|"
    r"chapter|step|phase|stage|grade|class|type|group|day|week|month|year|"
    r"level|model|version|patient|case|cohort|cluster|epoch|layer|block|"
    r"scenario|experiment|round|trial|arm|position|frame|slice|view|grid|"
    r"n|p|r|k|d|t|x|y|z)\s*[=:]?\s*$"
)


def _superscript_match(content: str, number: int) -> re.Match | None:
    """Superscript-shaped citation: glued to a word ("model16") or the PDF
    artifact "Dynamic 9 ." Never a numbered noun such as "Figure 3"."""
    pattern = re.compile(
        rf"(?:(?<=[A-Za-z\)\]\u00b9\u00b2\u00b3]){number}(?![\d.,:]\d)(?=[\s.,;:)\]]|$))"
        rf"|(?:(?<=[A-Za-z])\s{number}\s(?=[.,;]))"
    )
    for match in pattern.finditer(content or ""):
        spaced = match.group().startswith(" ")
        if spaced:
            before = content[max(0, match.start() - 24) : match.start() + 1]
            if _NUMBERED_NOUN_RE.search(before):
                continue
        return match
    return None
# PMC/NLM dumps often glue the number to the surname: "18Ouyang D ...".
_JAMMED_REF_NUM_RE = re.compile(r"(?:^|[\s;])(\d{1,3})(?=[A-Z][a-z]{2,})")
_BARE_REF_START_RE = re.compile(r"^\s*(\d+)\s+[A-Z][A-Za-z'’.-]+\s+[A-Z]")
# "[12] Ouyang D ..." / "[3] Smith, J. ..." — a bracketed entry start followed
# by an author-shaped name (surname then initial or another surname).
_BRACKET_ENTRY_START_RE = re.compile(
    r"(?:^|\s)\[\s*\d{1,4}\s*\]\s+[A-Z][A-Za-z'’-]+"
    r"(?:,|\.|\s+(?:et\s+al|and\b|[A-Z]\b|[A-Z]\.|[A-Z][a-z]+,))"
)
_REF_HEADING_RE = re.compile(
    r"(?i)^\s*(?:\d+\.?\s*)?(?:references?|bibliography|literature cited|"
    r"reference list|works cited)\s*[:.]?\s*$"
)
_TABLE_ROW_RE = re.compile(r"\|.*\|.*\|")
_MATH_ROW_RE = re.compile(r"\\(?:frac|sum|times|pm|alpha|beta|sigma|mathbf|begin\{)")
_ALIAS_STOPWORDS = {
    "table",
    "figure",
    "fig",
    "section",
    "ref",
    "refs",
    "nature",
    "study",
    "studies",
    "dataset",
    "data",
    "model",
    "method",
    "results",
    "supplementary",
    "appendix",
    "equation",
    "algorithm",
    "the",
    "this",
    "these",
    "however",
    "recently",
    "previous",
    "prior",
    "recent",
    "using",
    "since",
    "although",
    "while",
    "here",
    "in",
    "we",
    "our",
}


def _digit_ratio(text: str) -> float:
    letters = sum(ch.isalpha() for ch in text)
    digits = sum(ch.isdigit() for ch in text)
    return digits / max(1, letters + digits)


def _is_table_or_math_row(text: str) -> bool:
    """Table rows and equation dumps carry numbers that are not citations."""
    if _TABLE_ROW_RE.search(text or ""):
        return True
    if _MATH_ROW_RE.search(text or ""):
        return True
    return _digit_ratio(text or "") > 0.25


def _profile_reference_entry(entry: str) -> dict[str, str | None]:
    """Read first-author surname, year, and PMID from one bibliography entry."""
    text = re.sub(r"\s+", " ", entry or "").strip()
    out: dict[str, str | None] = {"surname": None, "year": None, "pmid": None}
    head = re.sub(r"^\s*(?:\[\d{1,4}\]|\d{1,4}[.)]?)\s*", "", text)
    name = re.match(
        r"([A-Z][A-Za-z'’-]{2,})\s*,?\s+(?:[A-Z]\b|[A-Z][a-z]+\b)",
        head,
    )
    if name:
        out["surname"] = name.group(1)
    doi = re.search(r"10\.\d{4,9}/\S+", text, re.IGNORECASE)
    tail = text[doi.end() :] if doi else text
    pmid = re.search(r"(?<!\d)(\d{7,8})(?!\d)", tail)
    if pmid:
        out["pmid"] = pmid.group(1)
    for year in re.findall(r"\b(?:19|20)\d{2}\b", text):
        position = text.find(year)
        if doi and doi.start() <= position <= doi.end():
            continue
        out["year"] = year
        break
    return out


def _profile_target_from_entries(
    target: TargetPaper,
    entries: list[str],
) -> dict[str, Any]:
    """Fill missing target metadata from the citers' own bibliography entries.

    Every citing paper describes the target the same way (first author, year,
    PMID), so a majority vote over a few entries is reliable and needs no
    outside API.
    """
    surnames: Counter[str] = Counter()
    years: Counter[str] = Counter()
    pmids: Counter[str] = Counter()
    for entry in entries:
        profile = _profile_reference_entry(entry)
        if profile["surname"]:
            surnames[profile["surname"]] += 1
        if profile["year"]:
            years[profile["year"]] += 1
        if profile["pmid"]:
            pmids[profile["pmid"]] += 1
    changed: dict[str, Any] = {}
    votes = max(1, len(entries))
    if not target.authors.strip() and surnames:
        surname, count = surnames.most_common(1)[0]
        if count >= 2 or votes == 1:
            target.authors = surname
            changed["authors"] = surname
    if not target.year and years:
        year, count = years.most_common(1)[0]
        if count >= 2 or votes == 1:
            target.year = int(year)
            changed["year"] = target.year
    if not target.pmid and pmids:
        pmid, count = pmids.most_common(1)[0]
        if count >= 2:
            target.pmid = pmid
            changed["pmid"] = pmid
    return changed


def _profile_target_from_citers(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    sample: int = 10,
) -> dict[str, Any]:
    """Grep a few citing bibliographies for the target entry and profile it."""
    if target.authors.strip() and target.year and target.pmid:
        return {}
    pattern = ""
    if target.doi:
        pattern = re.escape(target.doi)
    elif target.title:
        tokens = [t for t in re.split(r"\W+", target.title) if t]
        if len(tokens) >= 3:
            pattern = r"(?i)" + r"\W+".join(re.escape(t) for t in tokens[:8])
    if not pattern:
        return {}
    candidates = [p for p in papers if p.has_fulltext and p.paperclip_id]
    if not candidates:
        return {}
    step = max(1, len(candidates) // sample)
    entries: list[str] = []
    for paper in candidates[::step][:sample]:
        for _, text, is_match in _grep_content_lines(
            client, paper.paperclip_id or "", pattern
        ):
            if not is_match:
                continue
            try:
                anchor = re.search(pattern, text)
            except re.error:
                anchor = None
            column = anchor.start() if anchor else 0
            entries.append(text[max(0, column - 300) : column + 250])
            break
    return _profile_target_from_entries(target, entries)


def _reference_section_start(client: Any, paperclip_id: str) -> int | None:
    """Line number of the reference-section heading, when the paper has one."""
    if not paperclip_id:
        return None
    rows = _grep_content_lines(client, paperclip_id, _REF_HEADING_RE.pattern)
    lines = [
        line_no
        for line_no, text, is_match in rows
        if is_match and _REF_HEADING_RE.match(text or "")
    ]
    return min(lines) if lines else None


def _alias_candidates_in_text(text: str, citation_key: str) -> list[str]:
    """Capitalized names written directly before the marker: "EchoNet-Dynamic [16]"."""
    key = (citation_key or "").strip()
    number = re.fullmatch(r"[\[(]?\s*(\d+)\s*[\])]?", key)
    if not number:
        return []
    n = number.group(1)
    pattern = re.compile(
        r"([A-Z][A-Za-z0-9]*(?:-[A-Za-z0-9]+)*(?:\s[A-Z][A-Za-z0-9]*(?:-[A-Za-z0-9]+)*)?)"
        r"(?:\s+(?:dataset|model|database|benchmark|architecture|algorithm))?"
        rf"\s*[\[(]?\s*(?:[\d,;\s–-]*?(?<!\d){n}(?!\d))"
    )
    found: list[str] = []
    for match in pattern.finditer(text or ""):
        words = match.group(1).strip().split()
        # "The EchoNet-Dynamic dataset [4]": drop a leading sentence word.
        while words and words[0].lower() in _ALIAS_STOPWORDS:
            words.pop(0)
        if not words or any(word.lower() in _ALIAS_STOPWORDS for word in words):
            continue
        name = " ".join(words)
        if len(name) < 5 or not re.search(r"[a-z]", name):
            continue
        if not (re.search(r"[A-Z].*[A-Z]", name) or "-" in name):
            # Plain capitalized words ("Ultrasound") are sentence starts,
            # not names. Require CamelCase, a hyphen, or two capitals.
            continue
        if any(
            not re.match(r"[A-Z0-9]", part)
            for word in words
            for part in word.split("-")[1:]
        ):
            # "AI-generated", "LLM-based": an acronym plus a lowercase
            # adjective is a phrase, not a name. Names keep every hyphen
            # part capitalized ("EchoNet-Dynamic", "GPT-4", "U-Net").
            continue
        found.append(name)
    return found


def _mine_target_aliases(
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    limit: int = 3,
) -> list[str]:
    """Names citing papers use for the target, seen in at least two papers."""
    counts: Counter[str] = Counter()
    canonical: dict[str, str] = {}
    surname = ""
    first_author = re.split(r"[,;]", target.authors or "", maxsplit=1)[0].strip()
    if first_author:
        surname = first_author.split()[-1].lower()
    for paper in papers:
        seen: set[str] = set()
        for context in paper.contexts:
            for name in _alias_candidates_in_text(context.text, context.citation_key):
                key = re.sub(r"[\s-]+", "", name).lower()
                if key == surname or key in seen:
                    continue
                seen.add(key)
                canonical.setdefault(key, name)
        for key in seen:
            counts[key] += 1
    short_title = (target.title or "").split(":", 1)[0].strip()
    aliases: list[str] = []
    if re.fullmatch(r"[A-Za-z0-9-]{4,24}", short_title) and short_title.lower() not in {
        s.lower() for s in _ALIAS_STOPWORDS
    }:
        aliases.append(short_title)
    for key, count in counts.most_common():
        if count < 2:
            break
        name = canonical[key]
        if name.lower() not in {a.lower() for a in aliases}:
            aliases.append(name)
        if len(aliases) >= limit + 2:
            break
    # "EchoNet" is a family name shared by EchoNet-Dynamic, EchoNet-Labs and
    # EchoNet-LVH. Keep only the most specific mined name when one alias is a
    # prefix of another.
    keys = {alias: re.sub(r"[\s-]+", "", alias).lower() for alias in aliases}
    pruned = [
        alias
        for alias in aliases
        if not any(
            other != alias and keys[other].startswith(keys[alias])
            for other in aliases
        )
    ]
    return pruned[:limit]


def _alias_pattern(alias: str) -> str:
    body = re.escape(alias.strip()).replace(r"\-", r"[-\s]?").replace(r"\ ", r"[-\s]?")
    # Not followed by "-Labs": a hyphenated suffix names a different work.
    return rf"(?i)(?<![A-Za-z0-9]){body}(?![A-Za-z0-9]|-[A-Za-z])"


def _is_year_like_marker(value: str | int | None) -> bool:
    try:
        number = int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return False
    return 1900 <= number <= 2100


def _iter_reference_numbers(text: str):
    """Yield ``(number, style, start)`` markers from one bibliography window."""
    for match in _REF_NUM_RE.finditer(text):
        number = next((group for group in match.groups() if group), "")
        if not number or _is_year_like_marker(number):
            continue
        style = "bracket" if match.group(1) else "bare"
        yield number, style, match.start()
    for match in _JAMMED_REF_NUM_RE.finditer(text):
        number = match.group(1)
        if _is_year_like_marker(number):
            continue
        yield number, "bare", match.start()
    for match in _RUNON_REF_NUM_RE.finditer(text):
        number = match.group(1)
        if _is_year_like_marker(number):
            continue
        yield number, "bare", match.start()
_TITLE_STOPWORDS = {
    "about",
    "after",
    "analysis",
    "based",
    "from",
    "into",
    "paper",
    "study",
    "their",
    "these",
    "this",
    "using",
    "with",
}


def _alternation_pattern(patterns: list[str]) -> str:
    """Join per-line regexes into one grep pattern.

    A leading ``(?i)`` is rewritten as a scoped ``(?i:...)`` group, because a
    global flag is only legal at the very start of a pattern. Line anchors and
    lookarounds stay valid inside an alternative.
    """
    parts: list[str] = []
    for pattern in patterns:
        if not pattern:
            continue
        if pattern.startswith("(?i)"):
            parts.append(f"(?i:{pattern[4:]})")
        else:
            parts.append(f"(?:{pattern})")
    return "|".join(dict.fromkeys(parts))


def _pattern_hits(pattern: str, text: str) -> bool:
    """Re-test one original pattern against a row returned by a combined grep."""
    try:
        return re.search(pattern, text or "") is not None
    except re.error:
        return False


def _grep_content_lines(
    client: Any,
    paperclip_id: str,
    pattern: str,
    *,
    before: int = 0,
    after: int = 0,
) -> list[tuple[int, str, bool]]:
    """Run grep and return ``(line_no, text, is_match)`` rows."""
    path = f"/papers/{paperclip_id}/content.lines"
    args = [pattern, path]
    if before:
        args.extend(["-B", str(before)])
    if after:
        args.extend(["-A", str(after)])
    try:
        result = client.execute("grep", args, timeout=60)
    except Exception as exc:  # noqa: BLE001
        logger.debug("grep %s in %s failed: %s", pattern, paperclip_id, exc)
        return []
    output = _strip_ansi(getattr(result, "output", "") or "")
    if not output or "no matches" in output.lower():
        return []
    hits: list[tuple[int, str, bool]] = []
    for raw in output.splitlines():
        match = _GREP_LINE_RE.match(raw.strip())
        if not match:
            continue
        hits.append(
            (
                int(match.group(1)),
                match.group(3),
                match.group(2) == ":",
            )
        )
    return hits


def _looks_like_bibliography(line_no: int, text: str, max_line_hint: int | None) -> bool:
    """Heuristic: late lines or bibliography-shaped text are reference-list hits."""
    lowered = text.lower()
    compact = re.sub(r"\s+", " ", text).strip()
    if len(compact) > 1000 and (
        compact.lower().count("doi") >= 3
        or len(re.findall(r"10\.\d{4,9}/", compact, re.IGNORECASE)) >= 3
    ):
        return True
    bracket_markers = len(re.findall(r"\[\s*\d+\s*\]", compact))
    if bracket_markers >= 2:
        # A collapsed reference list: "[1] Smith, J. ... [2] Doe, A. ...".
        # A body paragraph also carries several brackets, so require the
        # brackets to start entries (followed by an author name) or the line
        # to carry reference metadata for more than one work.
        entry_starts = len(_BRACKET_ENTRY_START_RE.findall(compact))
        years = len(re.findall(r"\b(?:19|20)\d{2}\b", compact))
        dois = len(re.findall(r"10\.\d{4,9}/", compact, re.IGNORECASE))
        if entry_starts >= 2 or dois >= 2 or (years >= 3 and bracket_markers >= 3):
            return True
    if re.match(r"\s*\[\d{1,4}\]", compact) and _BRACKET_ENTRY_START_RE.search(
        compact
    ) and re.search(r"\b(?:19|20)\d{2}\b", compact):
        return True
    jammed_nums = list(_JAMMED_REF_NUM_RE.finditer(compact))
    if len(jammed_nums) >= 2:
        return True
    if jammed_nums and (
        "doi" in lowered
        or re.search(r"10\.\d{4,9}/", compact)
        or re.search(r"\b\d{7,8}\b", compact)
    ):
        return True
    if re.match(r"^\d+\.\s+[A-Z]", compact) and (
        "et al" in lowered or re.search(r"\(\d{4}\)", compact)
    ):
        return True
    if re.fullmatch(r"\d{6,9}", compact):
        return True
    # Compact citation metadata lines, e.g. "2023 ; 4 : 100779 . 37521038"
    if re.search(r"^\d{4}\s*;\s*\d+\s*:\s*\d+", compact):
        return True
    # "Nat. Commun. 16, 7633 (2025)."
    if re.search(r"\b\d{1,4}\s*,\s*\d{2,7}\s*\(\d{4}\)", compact):
        return True
    if re.search(r"\b\d{5,8}\b", compact) and re.search(r"\b20\d{2}\b", compact):
        if len(compact) < 80 and not re.search(r"\b(we|our|this study|these)\b", lowered):
            return True
    if "doi.org" in lowered:
        if re.search(r"\d+\s*,\s*\d+", text) or "et al" in lowered:
            return True
    # Journal metadata: "Nat. Commun. 16, 1 (2025)."
    if re.search(r"\(\d{4}\)", compact) and re.search(r"\d+\s*,\s*\d+", compact):
        return True
    # "Ouyang et al. (2020)" in a short prose sentence is an in-text cite.
    # Only treat et-al + year as a reference row when the line is metadata.
    if re.search(r"\(\d{4}\)", compact) and "et al" in lowered:
        prose = bool(
            re.search(
                r"\b(we|our|this|these|the|a|an|in|for|on|to|that|which)\b",
                lowered,
            )
        )
        jammed = (
            compact.lower().count("doi") >= 1
            or len(re.findall(r"\(\d{4}\)", compact)) >= 2
            or len(compact) > 500
        )
        if jammed or not prose:
            return True
    # Do not infer bibliography position from the largest matching line. The
    # largest *hit* is not the document length, so that rule misclassified the
    # final body citation as a reference-list entry.
    return False


def _citation_marker_pattern(citation_key: str) -> str:
    numeric = re.fullmatch(r"\s*[\[(]?\s*(\d+)\s*[\])]?\s*", citation_key or "")
    if numeric:
        number = re.escape(numeric.group(1))
        if "[" in citation_key:
            return rf"\[[^\]]*(?<!\d){number}(?!\d)[^\]]*\]"
        if "(" in citation_key:
            return rf"\([\d,;\s–-]*(?<!\d){number}(?!\d)[\d,;\s–-]*\)"
        return rf"(?<!\d){number}(?!\d)"
    return _alias_pattern(citation_key) if citation_key.strip() else ""


def _extract_mention_sentences(text: str, pattern: str) -> str:
    """Return the exact one or two sentences containing a verified mention."""
    source = (text or "").strip()
    if not source or not pattern:
        return ""
    try:
        mention_re = re.compile(pattern, re.IGNORECASE)
    except re.error:
        return ""
    if not mention_re.search(source):
        return ""

    protected = re.sub(r"\bet\s+al\.", "et al§", source, flags=re.IGNORECASE)
    boundaries = [0]
    for match in re.finditer(
        r"""[.!?]["”’]?\s+(?=[A-Z0-9“"'])""",
        protected,
    ):
        boundaries.append(match.end())
    boundaries.append(len(source))
    sentences = [
        source[boundaries[index] : boundaries[index + 1]].strip()
        for index in range(len(boundaries) - 1)
        if source[boundaries[index] : boundaries[index + 1]].strip()
    ]
    matched = [
        index for index, sentence in enumerate(sentences) if mention_re.search(sentence)
    ]
    if not matched:
        return ""
    first = matched[0]
    selected = [sentences[first]]
    if first > 0 and mention_re.match(selected[0]):
        selected.insert(0, sentences[first - 1])
    # Add one adjacent sentence only when the matching sentence is too short to
    # explain the claim. Never return more than two sentences.
    if len(selected[0]) < 45:
        if first + 1 < len(sentences):
            selected.append(sentences[first + 1])
        elif first > 0:
            selected.insert(0, sentences[first - 1])
    return " ".join(selected)


def _specific_context_text(
    context: CitationContext,
    target: TargetPaper,
) -> str:
    """Trim a context to a verified sentence-level target mention."""
    if context.citation_key:
        text = _extract_mention_sentences(
            context.text,
            _citation_marker_pattern(context.citation_key),
        )
        if text:
            return text
        return ""
    if target.doi:
        text = _extract_mention_sentences(context.text, re.escape(target.doi))
        if text:
            return text
    if target.title:
        tokens = [
            token
            for token in re.split(r"\W+", target.title)
            if len(token) >= 4 and token.lower() not in _TITLE_STOPWORDS
        ]
        if len(tokens) >= 3:
            return _extract_mention_sentences(
                context.text,
                r"\W+".join(re.escape(token) for token in tokens[:6]),
            )
    return ""


def _contains_target_title(text: str, target: TargetPaper) -> bool:
    """True when ``text`` carries the target title as an ordered phrase."""
    tokens = [t for t in re.split(r"\W+", target.title or "") if len(t) >= 2]
    if len(tokens) < 5:
        return False
    phrase = r"\W+".join(re.escape(token) for token in tokens[:8])
    return re.search(phrase, text or "", re.IGNORECASE) is not None


def _sanitize_contexts(
    contexts: list[CitationContext],
    target: TargetPaper,
) -> list[CitationContext]:
    cleaned: list[CitationContext] = []
    seen: set[str] = set()
    for context in contexts:
        if (context.citation_key or "").isdigit():
            marker_count = len(
                re.findall(
                    rf"(?<!\d){re.escape(context.citation_key)}(?!\d)",
                    context.text or "",
                )
            )
            if marker_count != 1:
                continue
        if _contains_target_title(context.text, target):
            # A row that spells out the target's title is its reference-list
            # entry, even when the reference section was not detected.
            continue
        text = _specific_context_text(context, target)
        key = re.sub(r"\s+", " ", text).strip().lower()
        if not text or key in seen:
            continue
        seen.add(key)
        context.text = text
        cleaned.append(context)
    return cleaned


def _extract_contexts_via_grep(
    client: Any,
    paper: MatchedCitingPaper,
    target: TargetPaper,
) -> MatchedCitingPaper:
    """Locate bibliography + body mentions with grep when lookup-citation cannot."""
    patterns: list[tuple[str, str]] = []
    if target.doi:
        patterns.append((re.escape(target.doi), "doi"))
        patterns.append((re.escape(target.doi.split("/", 1)[-1][:48]), "doi"))
    if target.pmid:
        patterns.append((re.escape(str(target.pmid)), "identifier"))
    if target.title:
        short_title = target.title.split(":", 1)[0].strip()
        if re.fullmatch(r"[A-Za-z0-9-]{4,20}", short_title):
            patterns.append((rf"(?i)\b{re.escape(short_title)}\b", "name"))
        title_tokens = [
            t
            for t in re.split(r"\W+", target.title)
            if t
        ]
        # Keep stopwords so the fingerprint remains an exact ordered title
        # phrase rather than accidentally requiring non-adjacent keywords to
        # be adjacent (for example, "Attention" and "Need").
        if len(title_tokens) >= 2:
            title_pattern = r"(?i)" + r"\W+".join(
                re.escape(token) for token in title_tokens[:10]
            )
            patterns.append((title_pattern, "title"))

    bibliography_windows: list[
        tuple[int, int, list[tuple[int, str, bool]]]
    ] = []
    direct_contexts: list[CitationContext] = []
    unique_patterns: list[tuple[str, str]] = []
    seen_patterns: set[str] = set()
    for pattern, kind in patterns:
        if pattern and pattern.lower() not in seen_patterns:
            seen_patterns.add(pattern.lower())
            unique_patterns.append((pattern, kind))

    # One round trip finds the reference heading and every anchor (DOI, PMID,
    # title, coined name). Each returned row is re-tested locally, so the
    # result equals one grep per pattern.
    rows = _grep_content_lines(
        client,
        paper.paperclip_id or "",
        _alternation_pattern(
            [_REF_HEADING_RE.pattern, *(pattern for pattern, _ in unique_patterns)]
        ),
        before=3,
        after=1,
    )
    heading_lines = [
        line_no
        for line_no, text, is_match in rows
        if is_match and _REF_HEADING_RE.match(text or "")
    ]
    reference_start = min(heading_lines) if heading_lines else None

    def _is_reference_row(line_no: int, text: str) -> bool:
        if reference_start is not None and line_no >= reference_start:
            return True
        return _looks_like_bibliography(line_no, text, None)

    for pattern, kind in unique_patterns:
        for line_no, text, is_match in rows:
            if not is_match or not _pattern_hits(pattern, text):
                continue
            bibliography = _is_reference_row(line_no, text) or (
                kind in {"title", "doi"}
                and (
                    _REF_NUM_RE.search(text) is not None
                    or _BARE_REF_START_RE.search(text) is not None
                    or _JAMMED_REF_NUM_RE.search(text) is not None
                )
            )
            if bibliography or kind == "identifier":
                window = [
                    row for row in rows if line_no - 3 <= row[0] <= line_no + 1
                ]
                try:
                    anchor_match = re.search(pattern, text)
                except re.error:
                    anchor_match = None
                anchor_column = anchor_match.start() if anchor_match else len(text)
                bibliography_windows.append((line_no, anchor_column, window))
                if not paper.reference_entry:
                    paper.reference_entry = text[
                        max(0, anchor_column - 300) : anchor_column + 250
                    ]
            elif kind in {"doi", "title", "name"}:
                direct_contexts.append(
                    CitationContext(
                        section="body",
                        line=line_no,
                        text=text,
                        citation_key=short_title if kind == "name" else "",
                    )
                )

    citation_keys: list[tuple[str, str]] = []
    for anchor_line, anchor_column, window in bibliography_windows:
        window_by_line = {ln: txt for ln, txt, _ in window}

        # A parser can place the complete bibliography on one line. Select the
        # last reference marker before the matched identifier or title. Using
        # the first marker on that line can attach the target to another entry.
        found_key: str | None = None
        found_style = "bracket"
        anchor_text = window_by_line.get(anchor_line, "")
        before_anchor = [
            (start, number, style)
            for number, style, start in _iter_reference_numbers(anchor_text)
            if start < anchor_column
        ]
        if before_anchor:
            _, found_key, found_style = max(before_anchor)

        # If the anchor line has no marker before the target, walk backward to
        # the nearest numbered reference on an earlier line.
        for check_line in range(anchor_line - 1, anchor_line - 12, -1):
            if found_key:
                break
            text = window_by_line.get(check_line)
            if text is None:
                continue
            numbered = list(_iter_reference_numbers(text))
            if numbered:
                found_key, found_style, _ = numbered[-1]
                if found_key:
                    break
            bare = _BARE_REF_START_RE.search(text)
            if bare:
                found_key = bare.group(1)
                found_style = "bare"
                break

        # If nothing before the anchor, infer from the next entry's number.
        if not found_key:
            for check_line in range(anchor_line + 1, anchor_line + 5):
                text = window_by_line.get(check_line)
                if text is None:
                    continue
                m = _REF_NUM_RE.search(text)
                if m:
                    next_key = next((g for g in m.groups() if g), "")
                    found_style = "bracket" if m.group(1) else "bare"
                    if next_key:
                        try:
                            found_key = str(int(next_key) - 1)
                        except ValueError:
                            pass
                        break
                bare = _BARE_REF_START_RE.search(text)
                if bare:
                    try:
                        found_key = str(int(bare.group(1)) - 1)
                        found_style = "bare"
                    except ValueError:
                        pass
                    break

        if found_key and _is_year_like_marker(found_key):
            found_key = None
        key_with_style = (found_key or "", found_style)
        if found_key and key_with_style not in citation_keys:
            citation_keys.append(key_with_style)

    marker_contexts: list[CitationContext] = []
    for citation_key, marker_style in citation_keys:
        if not paper.citation_marker:
            paper.citation_marker = f"[{citation_key}]"
        marker_contexts.extend(
            _locate_numeric_marker(
                client,
                paper,
                citation_key,
                marker_style,
                _is_reference_row,
            )
        )

    author_contexts: list[CitationContext] = []
    if bibliography_windows and target.authors and not marker_contexts:
        first_author = re.split(r"[,;]", target.authors, maxsplit=1)[0].strip()
        surname = first_author.split()[-1] if first_author else ""
        if len(surname) >= 2:
            year = str(target.year or "")
            # Numeric-marker papers write "Ouyang et al. [33]" without a
            # year. Author-year papers must carry the year, or another
            # author with the same surname ("Ouyang et al., 2024") matches.
            if citation_keys or not (year.isdigit() and len(year) == 4):
                author_patterns = [rf"(?i)\b{re.escape(surname)}\s+et\s+al\.?"]
            else:
                author_patterns = [
                    rf"(?i)\b{re.escape(surname)}\b.{{0,40}}\b{year}\b"
                ]
            seen_author_lines: set[int] = set()
            for author_pattern in author_patterns:
                for line_no, text, is_match in _grep_content_lines(
                    client,
                    paper.paperclip_id or "",
                    author_pattern,
                ):
                    if (
                        not is_match
                        or line_no in seen_author_lines
                        or _is_reference_row(line_no, text)
                        or _is_table_or_math_row(text)
                    ):
                        continue
                    seen_author_lines.add(line_no)
                    author_contexts.append(
                        CitationContext(
                            section="body",
                            line=line_no,
                            text=text,
                            citation_key=f"{surname} et al.",
                        )
                    )
            if author_contexts and not paper.citation_marker:
                paper.citation_marker = f"{surname} et al."

    paper.contexts = _sanitize_contexts(
        direct_contexts + marker_contexts + author_contexts,
        target,
    )[:12]
    paper.bibliography_only = bool(bibliography_windows) and not paper.contexts
    return paper


def _locate_numeric_marker(
    client: Any,
    paper: MatchedCitingPaper,
    citation_key: str,
    marker_style: str,
    is_reference_row: Callable[[int, str], bool],
) -> list[CitationContext]:
    """Find body sentences that cite numeric marker ``citation_key``.

    Styles are tried in precision order and the first style with hits wins:
    bracket groups ``[16]`` / ``[3, 16-18]``, parenthesised groups ``(16)``,
    then a superscript-shaped bare number glued to a word (``EchoNet16``,
    ``Dynamic 9 .``). A bare number in a table row, an equation, or a
    digit-dense line is never a citation.
    """
    number = re.escape(citation_key)
    styles: list[tuple[str, str, str]] = [
        (
            "bracket",
            rf"\[[^\]]*(?<!\d){number}(?!\d)[^\]]*\]",
            f"[{citation_key}]",
        ),
        (
            "paren",
            rf"\([\d,;\s–-]*(?<!\d){number}(?!\d)[\d,;\s–-]*\)",
            f"({citation_key})",
        ),
    ]
    if marker_style != "bracket":
        styles.append(
            (
                "superscript",
                rf"(?<=[A-Za-z\)\]])\s?{number}(?![\d.,:]\d)(?=[\s.,;:)\]]|$)",
                citation_key,
            )
        )
    # One grep for every style; rows are re-tested per style locally so the
    # precision order is unchanged.
    rows = _grep_content_lines(
        client,
        paper.paperclip_id or "",
        _alternation_pattern([pattern for _, pattern, _ in styles]),
    )
    for style, pattern, key in styles:
        found: list[CitationContext] = []
        for line_no, text, is_match in rows:
            if not is_match or not _pattern_hits(pattern, text):
                continue
            if is_reference_row(line_no, text):
                continue
            if _is_table_or_math_row(text):
                continue
            if style == "superscript" and (
                _digit_ratio(text) > 0.08
                or _superscript_match(text, int(citation_key)) is None
            ):
                continue
            if style == "paren" and not _paren_group_contains(text, int(citation_key)):
                continue
            if style == "bracket" and not _quote_contains_citation_key(text, key):
                continue
            found.append(
                CitationContext(
                    section="body",
                    line=line_no,
                    text=text,
                    citation_key=key,
                )
            )
        if found:
            return found
    return []


def _paren_group_contains(text: str, number: int) -> bool:
    """True when a parenthesised numeric group such as ``(9, 16-18)`` cites ``number``."""
    for group in re.findall(r"\(([\d,;\s–-]+)\)", text or ""):
        if _is_year_like_marker(group.strip()):
            continue
        for token in re.split(r"[,;]", group):
            token = token.strip().replace("–", "-")
            if token.isdigit() and int(token) == number:
                return True
            span = re.fullmatch(r"(\d+)\s*-\s*(\d+)", token)
            if span and int(span.group(1)) <= number <= int(span.group(2)):
                return True
    return False


def extract_contexts(
    client: Any,
    paper: MatchedCitingPaper,
    target: TargetPaper,
) -> MatchedCitingPaper:
    """Find bibliography entry + in-text uses of the target in one citing paper."""
    if not paper.paperclip_id or not paper.has_fulltext:
        return paper

    queries: list[str] = []
    if target.doi:
        queries.append(target.doi)
        queries.append(target.doi.split("/", 1)[-1][:40])
    if target.title:
        words = [w for w in re.split(r"\s+", target.title) if len(w) > 3][:6]
        if words:
            queries.append(" ".join(words[:4]))
        tokens = [t for t in re.split(r"\W+", target.title) if len(t) >= 4]
        if tokens:
            queries.append(tokens[0])
    if target.pmid:
        queries.append(str(target.pmid))
    if target.authors:
        first = target.authors.split(",")[0].split(";")[0].strip()
        if first:
            year = f" {target.year}" if target.year else ""
            queries.append(f"{first}{year}")

    # lookup-citation currently accepts UUID / bio_ / med_ ids, not PMC*.
    can_lookup_citation = bool(
        re.match(
            r"^(?:[0-9a-f]{8}-[0-9a-f-]+|(?:bio|med)_[0-9a-f]+)$",
            paper.paperclip_id,
            re.IGNORECASE,
        )
    )

    if can_lookup_citation:
        seen_queries: set[str] = set()
        for query in queries:
            q = query.strip()
            if not q or q.lower() in seen_queries:
                continue
            seen_queries.add(q.lower())
            try:
                result = client.execute(
                    "lookup-citation",
                    [paper.paperclip_id, q],
                    timeout=60,
                )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "lookup-citation failed for %s (%s): %s",
                    paper.paperclip_id,
                    q,
                    exc,
                )
                continue
            output = getattr(result, "output", "") or ""
            if "not in a paper directory" in output.lower():
                break
            key, contexts, bibliography_only = parse_lookup_citation_output(output)
            if contexts:
                cleaned = _sanitize_contexts(contexts, target)
                if cleaned:
                    paper.contexts = cleaned[:12]
                    paper.bibliography_only = False
                    return paper
            if bibliography_only or (key and not contexts):
                paper.bibliography_only = True
                if key and not paper.citation_marker:
                    paper.citation_marker = key.strip()

    return _extract_contexts_via_grep(client, paper, target)


def _mentions_target_hints(target: TargetPaper) -> dict[str, Any]:
    """Target fields the server may lack for an out-of-corpus target."""
    hints: dict[str, Any] = {}
    if target.authors.strip():
        hints["authors"] = target.authors.strip()
    if target.year:
        hints["year"] = str(target.year)
    if target.pmid:
        hints["pmid"] = str(target.pmid)
    if target.aliases:
        hints["aliases"] = list(target.aliases)[:5]
    if target.title:
        hints["title"] = target.title
    return hints


def _extract_selected_mentions(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
) -> tuple[dict[str, list[CitationContext]], dict[str, tuple[str, str]]]:
    """Extract high-precision contexts for the exact selected citing cohort.

    Returns ``(contexts_by_id, anchored_by_id)``. ``anchored_by_id`` maps a
    paper to ``(marker, bibliography entry)`` whenever the server located the
    target's reference entry, including papers with no body sentence.
    """
    target_id = target.paperclip_id or target.doi
    document_ids = [
        paper.paperclip_id
        for paper in papers
        if paper.has_fulltext and paper.paperclip_id
    ]
    if not target_id or not document_ids:
        return {}, {}

    base_args = [
        target_id,
        "--document-ids",
        ",".join(document_ids[:DEFAULT_MAP_LIMIT]),
        "--json",
    ]
    hints = _mentions_target_hints(target)
    attempts = [base_args]
    if hints:
        attempts.insert(
            0,
            [*base_args, "--target-json", json.dumps(hints, ensure_ascii=False)],
        )
    result = None
    for args in attempts:
        try:
            result = client.execute("mentions", args, timeout=300)
        except Exception as exc:  # noqa: BLE001
            logger.debug("selected mentions extraction failed: %s", exc)
            return {}, {}
        message = (
            getattr(result, "output", "") or getattr(result, "stderr", "") or ""
        )
        # The CLI execute API can report exit 0 while the tool wrote an
        # error body ("ERR: mentions: unknown argument ... [exit 1]").
        tool_failed = bool(
            re.match(r"\s*ERR\b", message)
            or re.search(r"\[exit\s+[1-9]\d*\]\s*$", message.strip())
        )
        if int(getattr(result, "exit_code", 0) or 0) == 0 and not tool_failed:
            break
        logger.debug("selected mentions extraction returned an error: %s", message)
        if "unknown argument" not in message.lower():
            return {}, {}
        # Older server without --target-json: retry without hints.
        result = None
    if result is None:
        return {}, {}

    output = (getattr(result, "output", "") or "").strip()
    try:
        payload = json.loads(output)
    except (json.JSONDecodeError, TypeError):
        start = output.find("{")
        if start < 0:
            return {}, {}
        try:
            payload, _ = json.JSONDecoder().raw_decode(output[start:])
        except json.JSONDecodeError:
            return {}, {}
    if not isinstance(payload, dict):
        return {}, {}

    contexts_by_id: dict[str, list[CitationContext]] = {}
    anchored_by_id: dict[str, tuple[str, str]] = {}
    for citing in payload.get("citing_papers") or []:
        path = str(citing.get("path") or "").strip().rstrip("/")
        paperclip_id = path.rsplit("/", 1)[-1] if path else ""
        marker = str(citing.get("marker") or "")
        if paperclip_id and (marker or citing.get("entry")):
            anchored_by_id[paperclip_id] = (marker, str(citing.get("entry") or ""))
        contexts = [
            CitationContext(
                section="body",
                line=(
                    int(mention.get("line"))
                    if str(mention.get("line") or "").isdigit()
                    else None
                ),
                text=str(mention.get("sentence") or "").strip(),
                citation_key=marker,
            )
            for mention in citing.get("mentions") or []
            if str(mention.get("sentence") or "").strip()
            and not _is_table_or_math_row(str(mention.get("sentence") or ""))
        ]
        cleaned = _sanitize_contexts(contexts, target)
        if paperclip_id and cleaned:
            contexts_by_id[paperclip_id] = cleaned[:12]
    for anchored in payload.get("anchored") or []:
        path = str(anchored.get("path") or "").strip().rstrip("/")
        paperclip_id = path.rsplit("/", 1)[-1] if path else ""
        if paperclip_id and paperclip_id not in anchored_by_id:
            anchored_by_id[paperclip_id] = (
                str(anchored.get("marker") or ""),
                str(anchored.get("entry") or ""),
            )
    return contexts_by_id, anchored_by_id


def _extract_contexts_for_sample(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> dict[int, MatchedCitingPaper]:
    """Locate the target in each citing paper, in four stages.

    1. Profile the target from the citers' bibliography entries when the
       corpus has no metadata for it (first author, year, PMID).
    2. Server-side ``mentions`` over the whole cohort (one call).
    3. The grep extractor for papers ``mentions`` did not resolve.
    4. Mine the names citers use for the target from the located sentences
       and search unresolved papers for those names.
    """
    stage_counts: dict[str, int] = {}
    profiled = _profile_target_from_citers(client, papers, target)
    if profiled:
        emit_event(
            on_event,
            "context",
            status="target_profiled",
            **{f"target_{key}": value for key, value in profiled.items()},
        )
    selected_mentions, anchored = _extract_selected_mentions(client, papers, target)
    stage_counts["mentions_anchored"] = len(anchored)
    done_map: dict[int, MatchedCitingPaper] = {}
    completed = 0
    unresolved: list[MatchedCitingPaper] = []

    for paper in papers:
        marker, entry = anchored.get(paper.paperclip_id or "", ("", ""))
        if marker and not paper.citation_marker:
            paper.citation_marker = marker
        if entry and not paper.reference_entry:
            paper.reference_entry = entry
        contexts = selected_mentions.get(paper.paperclip_id or "")
        if contexts:
            paper.contexts = contexts
            paper.bibliography_only = False
            done_map[id(paper)] = paper
            completed += 1
            stage_counts["located_mentions"] = stage_counts.get("located_mentions", 0) + 1
            emit_event(
                on_event,
                "context",
                status="progress",
                completed=completed,
                total=len(papers),
                current_item=paper.title or paper.paperclip_id or "Full-text paper",
            )
        else:
            unresolved.append(paper)

    with ThreadPoolExecutor(max_workers=DEFAULT_CONTEXT_WORKERS) as pool:
        futures = {
            pool.submit(extract_contexts, client, paper, target): paper
            for paper in unresolved
        }
        for future in as_completed(futures):
            if _cancelled(cancel):
                break
            original = futures[future]
            try:
                done_map[id(original)] = future.result()
            except Exception as exc:  # noqa: BLE001
                logger.debug("context extract failed: %s", exc)
                done_map[id(original)] = original
            if done_map[id(original)].contexts:
                stage_counts["located_grep"] = stage_counts.get("located_grep", 0) + 1
            completed += 1
            emit_event(
                on_event,
                "context",
                status="progress",
                completed=completed,
                total=len(papers),
                current_item=(
                    original.title
                    or original.doi
                    or original.paperclip_id
                    or "Full-text paper"
                ),
            )

    resolved = [done_map.get(id(paper), paper) for paper in papers]
    if not _cancelled(cancel):
        aliases = _mine_target_aliases(resolved, target)
        if aliases:
            target.aliases = aliases
            # Skip papers the rules already classify as a real mention from
            # their marker sentence: a named sentence cannot improve them.
            recovered = _locate_alias_mentions(
                client,
                [
                    p
                    for p in resolved
                    if p.has_fulltext
                    and p.paperclip_id
                    and not _rules_confirm_real_mention(p, target)
                ],
                target,
            )
            stage_counts["located_alias"] = recovered
    for paper in resolved:
        if not paper.has_fulltext or paper.contexts:
            paper.drop_reason = ""
            continue
        paper.drop_reason = _deterministic_drop_reason(paper)
        if paper.drop_reason != "no_entry":
            # An entry or marker proves the reference-list citation even when
            # no body sentence was found. Record that on the flag so every
            # later stage treats the paper as a true drive-by, not as lost.
            paper.bibliography_only = True
    stage_counts["unresolved"] = sum(
        1 for paper in resolved if paper.has_fulltext and not paper.contexts
    )
    stage_counts["anchored_no_sentence"] = sum(
        1
        for paper in resolved
        if paper.has_fulltext and not paper.contexts and paper.bibliography_only
    )
    stage_counts["no_entry"] = sum(
        1 for paper in resolved if paper.drop_reason == "no_entry"
    )
    emit_event(
        on_event,
        "context",
        status="stages",
        aliases=list(target.aliases),
        **stage_counts,
    )
    return done_map


def _deterministic_drop_reason(paper: MatchedCitingPaper) -> str:
    """Name the extraction stage that lost a paper with no located sentence."""
    if paper.citation_marker.strip():
        return "marker_no_sentence"
    if paper.reference_entry.strip() or paper.bibliography_only:
        return "entry_no_marker"
    return "no_entry"


def _rules_confirm_real_mention(paper: MatchedCitingPaper, target: TargetPaper) -> bool:
    """True when the best located sentence already reads as a real mention."""
    if not paper.contexts:
        return False
    best = _best_deterministic_context(paper.contexts, target)
    return best is not None and (
        _scorecard_context_role("drive_by", best, target) == "real_mention"
    )


def _locate_alias_mentions(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
) -> int:
    """Find prose mentions by the target's mined names.

    Papers with no located sentence gain their first contexts (counted as
    recovered). Papers that already have marker sentences gain the named
    sentences as extra passages, so the verifier sees "we use EchoNet" even
    when the numeric marker sits in a citation pile elsewhere.
    """
    if not target.aliases or not papers:
        return 0
    recovered = 0

    def _one(paper: MatchedCitingPaper) -> list[CitationContext]:
        # One grep returns the reference heading and every alias hit.
        alias_patterns = [_alias_pattern(alias) for alias in target.aliases]
        rows = _grep_content_lines(
            client,
            paper.paperclip_id or "",
            _alternation_pattern([_REF_HEADING_RE.pattern, *alias_patterns]),
        )
        heading_lines = [
            line_no
            for line_no, text, is_match in rows
            if is_match and _REF_HEADING_RE.match(text or "")
        ]
        reference_start = min(heading_lines) if heading_lines else None
        found: list[CitationContext] = []
        for alias, alias_pattern in zip(target.aliases, alias_patterns, strict=True):
            for line_no, text, is_match in rows:
                if not is_match or not _pattern_hits(alias_pattern, text):
                    continue
                if reference_start is not None and line_no >= reference_start:
                    continue
                if _looks_like_bibliography(line_no, text, None):
                    continue
                if _is_table_or_math_row(text):
                    continue
                found.append(
                    CitationContext(
                        section="body",
                        line=line_no,
                        text=text,
                        citation_key=alias,
                    )
                )
            if found:
                break
        return _sanitize_contexts(found, target)[:12]

    with ThreadPoolExecutor(max_workers=DEFAULT_CONTEXT_WORKERS) as pool:
        futures = {pool.submit(_one, paper): paper for paper in papers}
        for future in as_completed(futures):
            paper = futures[future]
            try:
                contexts = future.result()
            except Exception as exc:  # noqa: BLE001
                logger.debug("alias locate failed: %s", exc)
                continue
            if not contexts:
                continue
            if paper.contexts:
                known_lines = {c.line for c in paper.contexts if c.line}
                extra = [c for c in contexts if c.line not in known_lines]
                paper.contexts = (paper.contexts + extra)[:12]
                continue
            paper.contexts = contexts
            paper.bibliography_only = False
            if not paper.citation_marker:
                paper.citation_marker = contexts[0].citation_key
            recovered += 1
    return recovered


def _capture_citation_lines(papers: list[MatchedCitingPaper]) -> None:
    """Keep every extracted citation location before verification selects one."""
    for paper in papers:
        paper.citation_lines = sorted(
            {
                int(context.line)
                for context in paper.contexts
                if isinstance(context.line, int) and context.line > 0
            }
        )


def _fallback_passage_summary(paper: MatchedCitingPaper) -> str:
    """Deterministic one-line summary from the first extracted passage."""
    if not paper.contexts:
        return ""
    first = paper.contexts[0]
    summary = (first.text or "").strip()
    if len(summary) > 400:
        summary = summary[:397] + "..."
    section = first.section or "body"
    return f"({section}) {summary}"


def _parse_map_output_summaries(output: str) -> dict[str, str]:
    """Best-effort parse of map stdout into ``{paper_id: summary}``."""
    summaries: dict[str, str] = {}
    current_id: str | None = None
    buf: list[str] = []
    id_re = re.compile(
        r"\b((?:PMC\d+)|(?:(?:bio|med|arx)_[0-9a-f]{8,})|(?:[0-9a-f]{8}-[0-9a-f-]{27}))\b",
        re.IGNORECASE,
    )

    def _flush() -> None:
        nonlocal current_id, buf
        if current_id and buf:
            text = "\n".join(line.strip() for line in buf if line.strip())
            if text:
                summaries[current_id] = text[:600]
        current_id = None
        buf = []

    for line in (output or "").splitlines():
        match = id_re.search(line)
        if match and (
            line.strip().startswith(match.group(1))
            or "document" in line.lower()
            or "[success]" in line.lower()
            or "[failed]" in line.lower()
            or line.strip().startswith("#")
            or line.strip().startswith("##")
        ):
            _flush()
            current_id = match.group(1)
            remainder = line[match.end() :].strip(" :-#")
            buf = [remainder] if remainder else []
            continue
        if current_id:
            buf.append(line)
    _flush()
    return summaries


# Liberal stance rule: mixed support plus pushback counts as contradictory.
_STANCE_INSTRUCTIONS = (
    "Also assign exactly one STANCE, independent of ROLE. Use a liberal rule.\n"
    "- contradictory: the citing paper pushes back on the target in any of these "
    "ways, even if it also cites the target as related work or reuses its numbers: "
    "it disputes a result, method, mechanism, or interpretation; it says the target "
    "is incomplete, too narrow, outdated, not necessary, or does not account for a "
    "case; it offers a competing definition, framework, model, or mechanism as a "
    "contrast, counterpoint, or alternative path; or it restricts the target's claim "
    "to a narrower setting. If both support and pushback are present, choose "
    "contradictory. Do not require hostile language. A calm contrast is enough.\n"
    "- supporting: the citing paper uses the target as evidence, a method, a "
    "dataset, or a confirmed result, and does not push back on it.\n"
    "- none: the passage only names or locates the target, with no support and no "
    "pushback.\n"
    "Do not mark contradictory only because the target itself reports a limitation "
    "that the citing paper repeats as evidence.\n"
    "These passage shapes are contradictory. They come from labelled examples:\n"
    "1. A negative statement about what the target does: does not consider, does "
    "not contain, no control over, loses information, fails to capture, almost no "
    "ability, do not fully eliminate.\n"
    "2. The citing work is placed above the target or avoids its cost: our model "
    "outperforms it, our method does not require it, unlike the target, while our "
    "model does X instead.\n"
    "3. The target's claim is narrowed or called weak: they only show, the "
    "conclusion is somewhat weaker, it is limited to one setting.\n"
    "4. The shortcoming is stated about a list of methods that includes the "
    "target. The group form still counts, because the statement covers the "
    "target.\n"
    "5. The target is left out of a study or benchmark for a stated shortcoming.\n"
    "6. The target's assumption is called unrealistic, for example contrary to "
    "what holds in the real world.\n"
    "A baseline, related-work, or example label does not cancel any of these. "
    "Words such as but, however, although, unlike, in contrast, whereas, instead, "
    "and rather than usually carry the pushback.\n"
    "Example of contradictory: \"The closest approach concatenates the sources "
    "uniformly into a single decoder (Target 2020), but we argue knowledge "
    "selection is critically missing.\" The citing paper names a gap in the "
    "target, so STANCE is contradictory even though the target is a baseline.\n"
    "Example of contradictory in group form: \"The slack method [12], unbalanced "
    "penalization [14], and conditional penalization [15] add penalty terms that "
    "reduce infeasible solutions, but do not fully eliminate them.\" The limit "
    "covers the target, so STANCE is contradictory.\n"
    "Example of supporting: \"We follow the protocol of Target 2020 and confirm "
    "the reported gain.\" There is no pushback, so STANCE is supporting.\n"
)


def build_fulltext_map_question(
    target: TargetPaper,
    target_summary: str = "",
) -> str:
    """Map prompt: specificity and importance of how one paper cites the target."""
    target_label = target.title or target.doi or "the target paper"
    doi_bit = f" (doi:{target.doi})" if target.doi else ""
    author_bit = f"; authors: {target.authors}" if target.authors else ""
    summary_bit = (
        "\nTARGET PAPER SUMMARY (use this only to check interpretation accuracy):\n"
        f"{target_summary[:3000]}\n"
        if target_summary
        else (
            "\nTARGET PAPER SUMMARY: unavailable. Do not assign wrongly_interpreted "
            "without a reliable target summary.\n"
        )
    )
    return (
        "CUSTOM CITATION AUDIT INSTRUCTION\n"
        f"TARGET: '{target_label}'{doi_bit}{author_bit}\n"
        f"{summary_bit}"
        "First identify the exact target in this paper's reference list. Match by DOI "
        "when present, then by title and authors. Record its citation key or marker. "
        "Do not use a neighboring reference and do not treat the reference-list entry "
        "itself as an in-text mention.\n"
        "Next find every place in the paper body where that exact citation key appears. "
        "For each place, report the section, line number or range, and an exact quote "
        "and keep the in-text citation marker. If there is no body use, classify it as "
        "bibliography_only. If the target reference cannot be identified, use not_found.\n"
        "Assign exactly one primary ROLE:\n"
        "Apply these rules in order. Specificity takes priority over citation count:\n"
        "1. real_mention: the passage says something specific about the target's "
        "method, data, result, limitation, or argument. One specific sentence is "
        "enough, even when it appears only once or in a literature review.\n"
        "2. drive_by: the target is only named, supports a generic claim, or appears "
        "in an undifferentiated citation group. Use drive_by only when no passage "
        "describes the target specifically.\n"
        "- unclassified: there is not enough body evidence to decide.\n"
        f"{_STANCE_INSTRUCTIONS}"
        "Also assign zero or more REUSE_TAGS only when the citing paper actively uses "
        "the target in its own work:\n"
        "- dataset_reuse: uses data or a cohort released by the target.\n"
        "- method_adoption: implements or adapts the target's method or protocol.\n"
        "- benchmarking: uses the target as an evaluation baseline or benchmark.\n"
        "- result_validated: independently confirms, reproduces, or reports results "
        "that clearly validate a target result.\n"
        "- work_extended: extends the target's findings, framework, method, or analysis "
        "to a new question, dataset, population, or setting.\n"
        "Do not tag a citation that only mentions, summarizes, or compares the target.\n"
        "Start the answer with these exact fields, one per line:\n"
        "CITATION_STATUS: in_text | bibliography_only | not_found\n"
        "CITATION_KEY: <exact marker or none>\n"
        "REFERENCE_MATCH: <one exact bibliography line containing the target, or none>\n"
        "ROLE: drive_by | real_mention | unclassified\n"
        "STANCE: supporting | contradictory | none "
        "(pick contradictory when the quote contrasts with the target or names a "
        "gap in it)\n"
        "REUSE_TAGS: <comma-separated tags from the list above, or none>\n"
        "INTERPRETATION_CHECK: <correct, wrong with a short correction, or not_applicable>\n"
        "CENTRALITY: <0-10>\n"
        "Then write LOCATIONS with 1-2 strongest exact body passages. For each location, "
        "use exactly three lines: SECTION: <name>, LINES: <Lx-Ly>, and QUOTE: <exact text>. "
        "Finish with one RATIONALE line. "
        "Never invent a quote, citation marker, section, or line number."
    )


def build_citation_verification_question(
    target: TargetPaper,
    papers: list[MatchedCitingPaper],
    target_summary: str = "",
) -> str:
    """Build a second-pass prompt that verifies and cleans display candidates."""
    candidates = [
        {
            "paper_id": paper.paperclip_id,
            "title": paper.title,
        }
        for paper in papers
        if paper.paperclip_id
    ]
    return (
        "FINAL CITATION DISPLAY VERIFICATION\n"
        f"TARGET: {target.title or target.doi or 'the target paper'}\n"
        + (f"TARGET DOI: {target.doi}\n" if target.doi else "")
        + (
            f"TARGET SUMMARY: {target_summary[:3000]}\n"
            if target_summary
            else ""
        )
        + "The JSON list identifies full-text papers selected by citation providers. "
        "Independently audit the paper you are reading; do not rely on an earlier "
        "quote or classification.\n"
        f"PAPERS: {json.dumps(candidates, ensure_ascii=False)}\n"
        "Find the target's exact bibliography entry and citation marker in the full "
        "paper. Then find the strongest exact body passage that uses that marker. "
        "Drop the candidate only if the target is absent, the marker belongs to "
        "another reference, or no exact body passage contains the marker.\n"
        "Clean the passage for display by copying one or two complete source "
        "sentences. Keep the citation marker. Do not paraphrase, add notes, explain "
        "nearby context, use ellipses, or join non-adjacent text.\n"
        "Classify with these ordered rules:\n"
        "1. real_mention: the passage specifically describes, compares, uses, "
        "extends, validates, or criticizes the target's method, data, result, "
        "limitation, or argument. One specific sentence is enough.\n"
        "2. drive_by: the target only supports a generic claim, is only named, or "
        "appears in an undifferentiated citation group.\n"
        "A statement about a general technology is drive_by even when it resembles "
        "background in the target abstract. A passage that attributes a specific "
        "capability or use to the target is real_mention. Related-work placement alone "
        "does not make a citation drive_by. However, a general problem statement stays "
        "drive_by even when the target is its only citation. A list of named benchmarks "
        "or a citation group also stays drive_by unless the passage separately "
        "attributes a concrete method, result, limitation, comparison, or use to the "
        "target itself.\n"
        f"{_STANCE_INSTRUCTIONS}"
        "Start with these exact fields, one per line:\n"
        "VERDICT: keep | drop\n"
        "CITATION_STATUS: in_text | bibliography_only | not_found\n"
        "CITATION_KEY: <exact marker or none>\n"
        "REFERENCE_MATCH: <exact target bibliography line or none>\n"
        "ROLE: drive_by | real_mention | unclassified\n"
        "STANCE: supporting | contradictory | none "
        "(pick contradictory when the quote contrasts with the target or names a "
        "gap in it)\n"
        "REUSE_TAGS: <valid tags or none>\n"
        "INTERPRETATION_CHECK: <correct, wrong with correction, or not_applicable>\n"
        "CENTRALITY: <0-10>\n"
        "For a kept candidate, finish with exactly one SECTION, LINES, and QUOTE "
        "block followed by RATIONALE. The QUOTE must be exact source text and must "
        "contain the target citation marker."
    )


SCORECARD_VERIFIER_SCHEMA = {
    "type": "object",
    "required": [
        "verdict",
        "citation_status",
        "passage_id",
        "role",
        "stance",
        "reuse_tags",
        "interpretation_check",
        "centrality",
        "reason",
    ],
    "properties": {
        "verdict": {"enum": ["keep", "drop"]},
        "citation_status": {
            "enum": ["in_text", "bibliography_only", "not_found"]
        },
        "passage_id": {"type": "string"},
        "citation_key": {"type": "string"},
        "reference_match": {"type": "string"},
        "role": {"enum": ["drive_by", "real_mention", "unclassified"]},
        "stance": {"enum": ["supporting", "contradictory", "none"]},
        "reuse_tags": {
            "type": "array",
            "items": {"type": "string"},
        },
        "interpretation_check": {"type": "string"},
        "centrality": {"type": "integer", "minimum": 0, "maximum": 10},
        "section": {"type": "string"},
        "line": {"type": "integer", "minimum": 0},
        "quote": {"type": "string"},
        "reason": {"type": "string"},
    },
}


def _scorecard_passage_id(context: CitationContext) -> str:
    payload = "|".join(
        (
            context.section or "",
            str(context.line or 0),
            context.citation_key or "",
            _normalized_quote(context.text),
        )
    )
    return f"passage-{hashlib.sha256(payload.encode()).hexdigest()[:12]}"


def build_scorecard_verifier_query(
    target: TargetPaper,
    paper: MatchedCitingPaper,
    target_summary: str = "",
) -> str:
    """Build one compact, paper-specific verification query."""
    evidence = {
        "target": target.to_dict(),
        "target_summary": target_summary[:3000],
        "assigned_paper": {
            "paperclip_id": paper.paperclip_id,
            "title": paper.title,
            "path": f"/papers/{paper.paperclip_id}/content.lines",
        },
        "deterministic_extraction": {
            "bibliography_only": paper.bibliography_only,
            "citation_marker": paper.citation_marker,
            "reference_entry": paper.reference_entry[:300],
            "target_names": list(target.aliases),
            "contexts": [
                {
                    "passage_id": _scorecard_passage_id(context),
                    **context.to_dict(),
                }
                for context in paper.contexts[:8]
            ],
        },
    }
    search_instruction = ""
    if not paper.contexts:
        hints = []
        if paper.citation_marker:
            hints.append(f"the marker {paper.citation_marker}")
        for alias in target.aliases[:3]:
            hints.append(f'the name "{alias}"')
        surname = re.split(r"[,;]", target.authors or "", maxsplit=1)[0].strip()
        if surname:
            hints.append(f'"{surname.split()[-1]} et al"')
        search_instruction = (
            "No deterministic passage was located for this paper. Search the "
            "assigned paper with grep for "
            + (", ".join(hints) if hints else "the target's title words")
            + ". Return citation_status in_text with an exact body sentence as "
            "the quote, the marker or name it carries as citation_key, and the "
            "L-number of that sentence as line (grep prints it before each "
            "hit). Do not quote the reference list. If the body never cites "
            "the target, return bibliography_only. "
        )
    return (
        f"{json.dumps(evidence, ensure_ascii=False)}\n"
        f"{search_instruction}"
        "Verify citation identity and the exact quote first. Then classify semantic "
        "importance independently. Use real_mention only when the passage attributes "
        "a concrete method, data choice, result, limitation, comparison, benchmark use, "
        "or methodological influence to this target. A general problem statement stays "
        "drive_by even when the target is its only citation. A list of benchmarks or "
        "a citation group is drive_by unless the passage separately explains this "
        "target's contribution. Related-work placement alone does not decide the role. "
        "Assign STANCE independently with a liberal rule. Use contradictory when the "
        "citing paper pushes back on the target in any way: a disputed result or "
        "method, a claim that the target is incomplete, too narrow, outdated, or not "
        "necessary, a competing definition or alternative path, or a restricted scope. "
        "If the citing paper both uses and pushes back on the target, choose "
        "contradictory. A calm contrast is enough. Use supporting only when the citing "
        "paper uses the target as evidence and does not push back. Use none when there "
        "is no support and no pushback. Do not mark contradictory only because the "
        "citing paper repeats a limitation that the target already reported. "
        "Read the quote for a contrast aimed at the target: words such as but, "
        "however, unlike, in contrast, whereas, instead, rather than, fails to, is "
        "missing, lacks, does not account for, cannot, and is limited to usually "
        "mark pushback. A baseline or related-work label does not cancel it. For "
        "example, \"the closest approach concatenates the sources uniformly "
        "(Target 2020), but we argue knowledge selection is critically missing\" is "
        "contradictory. "
        "Evaluate every supplied deterministic passage before selecting one. Do not "
        "stop at the first valid passage. Select in this priority order: first, the "
        "strongest contradictory passage that directly criticizes, limits, disputes, "
        "or contrasts with the target; second, the strongest real_mention passage; "
        "third, a drive_by passage only when no substantive passage exists. A "
        "contradictory passage takes priority even when another passage supports or "
        "uses the target. If several contradictory passages exist, select the most "
        "direct and specific one. Do not treat the target's own reported limitation "
        "as criticism by the citing paper. "
        "When a supplied deterministic passage is valid, return its passage_id. "
        "The caller will retrieve exact source text from that identifier, so do not "
        "rewrite it. Use scoped Paperclip commands only when no supplied passage is "
        "valid. Return an empty passage_id only in that case, with an exact quote from "
        "the paper. Return the required JSON classification."
    )


_MAP_ROLES = {
    "drive_by",
    "real_mention",
    "brief_mention",
    "supporting",
    "foundational",
    "wrongly_interpreted",
    "unclassified",
}
_MAP_STATUSES = {"in_text", "bibliography_only", "not_found"}
_REUSE_TAGS = {
    "dataset_reuse",
    "method_adoption",
    "benchmarking",
    "result_validated",
    "work_extended",
}


def _parse_reuse_tags(text: str) -> list[str]:
    """Parse and constrain reuse tags from one map answer."""
    match = re.search(r"(?im)^\s*REUSE_TAGS\s*:\s*([^\n]+)", text or "")
    if not match:
        return []
    aliases = {
        "finding_extension": "work_extended",
        "framework_application": "work_extended",
        "replication": "result_validated",
    }
    tags = {
        value.strip().lower().replace("-", "_").replace(" ", "_")
        for value in match.group(1).split(",")
    }
    tags = {aliases.get(tag, tag) for tag in tags}
    return sorted(tags & _REUSE_TAGS)


def _parse_map_assessment(text: str) -> tuple[str, bool, str]:
    """Parse fixed citation-audit fields from one map answer."""
    role_match = re.search(
        r"(?i)\bROLE\s*:\s*(drive_by|real_mention|brief_mention|supporting|"
        r"foundational|wrongly_interpreted|unclassified|significant|critical|"
        r"cursory|substantive|peripheral|nominal)\b",
        text or "",
    )
    interpretation_match = re.search(
        r"(?i)\bINTERPRETATION_CHECK\s*:\s*([^\n]+)",
        text or "",
    )
    status_match = re.search(
        r"(?i)\bCITATION_STATUS\s*:\s*(in_text|bibliography_only|not_found)\b",
        text or "",
    )
    role = role_match.group(1).lower() if role_match else "unclassified"
    role = {
        "significant": "foundational",
        "substantive": "foundational",
        "critical": "supporting",
        "cursory": "brief_mention",
        "peripheral": "brief_mention",
        "nominal": "brief_mention",
    }.get(role, role)
    status = status_match.group(1).lower() if status_match else "map_unparsed"
    if role not in _MAP_ROLES:
        role = "unclassified"
    if status not in _MAP_STATUSES:
        status = "map_unparsed"
    wrongly_interpreted = bool(
        interpretation_match
        and interpretation_match.group(1).strip().lower().startswith("wrong")
    )
    if wrongly_interpreted:
        role = "wrongly_interpreted"
    if status == "bibliography_only":
        role = "brief_mention"
        wrongly_interpreted = False
    elif status == "not_found":
        role = "brief_mention"
        wrongly_interpreted = False
    return role, wrongly_interpreted, status


_STANCE_LABELS = {"supporting", "contradictory", "none"}


def _parse_citation_stance(text: str) -> str:
    """Parse supporting vs contradictory stance from a map or JSON answer."""
    payload = _scorecard_json_answer(text)
    raw = ""
    if payload:
        raw = str(payload.get("stance") or "").strip().lower()
    if not raw:
        match = re.search(
            r"(?i)\bSTANCE\s*:\s*(supporting|contradictory|none)\b",
            text or "",
        )
        raw = match.group(1).lower() if match else ""
    aliases = {
        "support": "supporting",
        "supports": "supporting",
        "positive": "supporting",
        "critical": "contradictory",
        "criticize": "contradictory",
        "criticises": "contradictory",
        "negative": "contradictory",
        "contradict": "contradictory",
        "neutral": "none",
        "unclassified": "none",
    }
    stance = aliases.get(raw, raw)
    return stance if stance in _STANCE_LABELS else "none"


def citation_category_counts(
    papers: list[MatchedCitingPaper],
) -> dict[str, int]:
    """Count one exclusive category for each readable Paperclip citation.

    A paper dropped without a verified passage counts as ``drive_by`` only
    when its reference-list citation was confirmed (``bibliography_only``).
    Otherwise the system failed to place the citation: it counts as
    ``unlocated`` and must not inflate drive-by.
    """
    counts = {category: 0 for category in CITATION_CATEGORIES}
    counts["supporting"] = 0
    counts["contradictory"] = 0
    counts["unlocated"] = 0
    aliases = {
        "brief_mention": "drive_by",
        "cursory": "drive_by",
        "peripheral": "drive_by",
        "nominal": "drive_by",
        "unclassified": "drive_by",
        "supporting": "real_mention",
        "foundational": "real_mention",
        "significant": "real_mention",
        "substantive": "real_mention",
        "critical": "real_mention",
        "wrongly_interpreted": "real_mention",
    }
    for paper in papers:
        if not paper.has_fulltext or paper.analysis_status == "not_analyzed":
            continue
        if paper.analysis_status in {
            "excluded_no_valid_passage",
            "verification_rejected",
        }:
            counts["drive_by" if paper.bibliography_only else "unlocated"] += 1
            continue
        role = aliases.get(paper.impact_role, paper.impact_role)
        if paper.wrongly_interpreted:
            role = "real_mention"
        if role not in CITATION_CATEGORIES:
            role = "drive_by"
        counts[role] += 1
        stance = _normalize_citation_stance(paper)
        if stance in {"supporting", "contradictory"}:
            counts[stance] += 1
    return counts


def _normalize_citation_stance(paper: MatchedCitingPaper) -> str:
    stance = (paper.citation_stance or "none").strip().lower()
    return stance if stance in {"supporting", "contradictory"} else "none"


def citation_momentum(
    counts_by_year: dict[int, int],
    *,
    current_year: int | None = None,
) -> dict[str, Any]:
    """Compare the two latest complete calendar years."""
    year = current_year or datetime.now(UTC).year
    latest_year = year - 1
    previous_year = year - 2
    if latest_year not in counts_by_year or previous_year not in counts_by_year:
        return {}
    latest_count = counts_by_year[latest_year]
    previous_count = counts_by_year[previous_year]
    growth_percent = (
        round((latest_count - previous_count) * 100 / previous_count)
        if previous_count
        else None
    )
    growth_streak_years = 0
    cursor_year = latest_year
    while (
        cursor_year in counts_by_year
        and cursor_year - 1 in counts_by_year
        and counts_by_year[cursor_year] > counts_by_year[cursor_year - 1]
    ):
        growth_streak_years += 1
        cursor_year -= 1
    return {
        "latest_year": latest_year,
        "latest_count": latest_count,
        "previous_year": previous_year,
        "previous_count": previous_count,
        "growth_percent": growth_percent,
        "growth_streak_years": growth_streak_years,
        "increased": latest_count > previous_count,
    }


def _full_map_outputs(client: Any, result_id: str | None) -> dict[str, str]:
    """Read complete per-paper outputs from a saved map result."""
    if not result_id:
        return {}
    getter = getattr(getattr(client, "results", None), "get", None)
    if not callable(getter):
        return {}
    try:
        result = getter(result_id, timeout=60)
    except Exception as exc:  # noqa: BLE001
        logger.debug("could not read full map result %s: %s", result_id, exc)
        return {}
    raw = getattr(result, "raw", None) or {}
    result_data = raw.get("result_data") or {}
    # Current map artifacts use ``results``. Older payloads used ``papers``.
    rows = result_data.get("results")
    if not isinstance(rows, list):
        rows = result_data.get("papers") or []
    outputs: dict[str, str] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        doc_id = str(row.get("document_id") or "").strip()
        output = str(row.get("output") or row.get("response") or "").strip()
        if doc_id and output:
            outputs[doc_id] = output
    return outputs


def _map_output_for_document(
    outputs: dict[str, str],
    document_id: str | None,
) -> str:
    """Match map outputs across UUID and corpus-prefixed document ID forms."""
    requested = (document_id or "").strip()
    if not requested:
        return ""
    if requested in outputs:
        return outputs[requested]
    compact = _compact_document_key(requested)
    if len(compact) < 12:
        return ""
    prefix = compact[:12]
    for result_id, output in outputs.items():
        if _compact_document_key(result_id).startswith(prefix):
            return output
    return ""


def _compact_document_key(document_id: str) -> str:
    """Hex digits of a document ID with any corpus prefix removed.

    The prefix must go before the hex filter: ``b``, ``e``, and ``d`` in
    ``bio_`` and ``med_`` are hex digits, so ``bio_fe4149da7cbf`` would
    otherwise compact to ``bfe4149da7cbf`` and never match the map row
    ``fe4149da-7cbf-1014-...`` for the same paper.
    """
    normalized = (document_id or "").strip().lower()
    if normalized.startswith(("bio_", "med_", "arx_")):
        normalized = normalized.split("_", 1)[1]
    return re.sub(r"[^0-9a-f]", "", normalized)


def _parse_map_contexts(text: str) -> list[CitationContext]:
    """Parse exact locations from one structured citation-audit answer."""
    key_match = re.search(r"(?i)\bCITATION_KEY\s*:\s*([^\n]+)", text or "")
    citation_key = (key_match.group(1).strip() if key_match else "")
    if citation_key.isdigit():
        citation_key = f"[{citation_key}]"
    contexts: list[CitationContext] = []
    section_re = re.compile(
        r"(?ims)^\s*(?:[-*]\s*)?\**Section\**\s*:\s*"
        r"(?P<section>[^\n|]+?)(?:\s*\|\s*|,\s*(?=\**Lines?\**\s*:)|\n)"
        r"\s*(?:[-*]\s*)?\**(?:Line range|Lines?)\**\s*:\s*"
        r"L?(?P<line>\d+)[^\n|]*(?:\s*\|\s*|\n)"
        r"\s*(?:[-*]\s*)?\**(?:Exact passage|Quote)\**\s*:\s*"
        r"(?P<quote>.*?)(?=\n\s*(?:[-*]\s*)?\**(?:Section|Rationale)\**\s*:|\Z)"
    )
    for match in section_re.finditer(text or ""):
        quote = match.group("quote").strip()
        if len(quote) >= 2 and quote[0] == quote[-1] == '"':
            quote = quote[1:-1].strip()
        if not quote:
            continue
        contexts.append(
            CitationContext(
                section=match.group("section").strip(),
                line=int(match.group("line")),
                text=quote,
                citation_key=citation_key,
            )
        )
    return contexts


def _reference_matches_target(reference: str, target: TargetPaper) -> bool:
    """Require strong target identity evidence in the copied bibliography line."""
    normalized = re.sub(r"\s+", " ", reference or "").lower()
    if not normalized or normalized == "none":
        return False
    if target.doi and target.doi.lower() in normalized:
        return True
    title_tokens = {
        token.lower()
        for token in re.split(r"\W+", target.title or "")
        if len(token) >= 4 and token.lower() not in _TITLE_STOPWORDS
    }
    if not title_tokens:
        return False
    matched = sum(token in normalized for token in title_tokens)
    required = min(len(title_tokens), min(4, max(2, (len(title_tokens) + 1) // 2)))
    return matched >= required


def _quote_contains_citation_key(quote: str, citation_key: str) -> bool:
    """Check that the reported body quote contains the reported marker."""
    text = re.sub(r"^\s*L\d+\s*:\s*", "", quote or "").strip()
    key = (citation_key or "").strip()
    if not text or not key:
        return False
    key_number = re.fullmatch(r"[\[(]?\s*(\d+)\s*[\])]?", key)
    if not key_number:
        return re.sub(r"\s+", " ", key).lower() in re.sub(r"\s+", " ", text).lower()
    number = int(key_number.group(1))
    if key.startswith("["):
        for group in re.findall(r"\[([^\]]+)\]", text):
            if not re.fullmatch(r"[\d,;\s–-]+", group):
                # "[48,637 participants]" is a label, not a citation group.
                continue
            for token in re.split(r"[,;]", group):
                token = token.strip()
                if token.isdigit() and int(token) == number:
                    return True
                range_match = re.fullmatch(r"(\d+)\s*[–-]\s*(\d+)", token)
                if (
                    range_match
                    and int(range_match.group(1))
                    <= number
                    <= int(range_match.group(2))
                ):
                    return True
        for start, end in re.findall(r"(\d+)\s*[–-]\s*(\d+)", text):
            if int(start) <= number <= int(end):
                return True
        return False
    if key.startswith("("):
        return _paren_group_contains(text, number)
    if re.search(rf"(?<!\d){number}(?!\d)", text):
        return True
    return False


def _validated_map_contexts(
    text: str,
    contexts: list[CitationContext],
    target: TargetPaper,
) -> list[CitationContext]:
    """Accept only body quotes tied to a copied target bibliography entry."""
    reference_match = re.search(
        r"(?ims)^\s*REFERENCE_MATCH\s*:\s*(.+?)"
        r"(?=\n\s*(?:ROLE|REUSE_TAGS|INTERPRETATION_CHECK|CENTRALITY|"
        r"LOCATIONS?|SECTION|RATIONALE|VERDICT)\s*:|\Z)",
        text or "",
    )
    reference = (
        re.sub(r"\s+", " ", reference_match.group(1)).strip()
        if reference_match
        else ""
    )
    if not _reference_matches_target(reference, target):
        return []
    validated: list[CitationContext] = []
    for context in contexts:
        section = (context.section or "").strip().lower()
        if "reference" in section or "bibliograph" in section:
            continue
        if not _quote_contains_citation_key(context.text, context.citation_key):
            continue
        context.text = re.sub(r"^\s*L\d+\s*:\s*", "", context.text).strip()
        validated.append(context)
    return validated


def _verification_verdict(text: str) -> str:
    """Parse the fail-closed verdict from one citation verification answer."""
    match = re.search(r"(?im)^\s*VERDICT\s*:\s*(keep|drop)\b", text or "")
    return match.group(1).lower() if match else "drop"


def _has_model_commentary(text: str) -> bool:
    """Reject explanatory text that a model appended to a claimed quotation."""
    return bool(
        re.search(
            r"(?i)(?:\(\s*note\s*:|reference\s+\[?\d+\]?\s+is\s+cited\s+nearby|"
            r"broader\s+paragraph\s+context)",
            text or "",
        )
    )


def _verify_citation_candidates(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    target_summary: str = "",
    *,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> list[MatchedCitingPaper]:
    """Run a second full-text map pass and keep only display-ready citations."""
    candidates = [
        paper
        for paper in papers
        if paper.paperclip_id
        and paper.has_fulltext
        and paper.analysis_status != "not_analyzed"
    ]
    if not candidates or _cancelled(cancel):
        return papers

    emit_event(
        on_event,
        "summary",
        status="verification_started",
        paper_count=len(candidates),
        message="Verifying and cleaning citation passages for display",
    )
    prompt = build_citation_verification_question(target, candidates, target_summary)
    doc_ids = [paper.paperclip_id for paper in candidates if paper.paperclip_id]
    outputs: dict[str, str] = {}
    result_id: str | None = None
    try:
        streamed_output = ""
        for event in client.stream(
            "map",
            ["--document-ids", ",".join(doc_ids), "-n", str(len(doc_ids)), prompt],
            timeout=900,
        ):
            if _cancelled(cancel):
                break
            result_id = getattr(event, "result_id", None) or result_id
            streamed_output = getattr(event, "output", "") or streamed_output
        outputs.update(_parse_map_output_summaries(streamed_output))
        outputs.update(_full_map_outputs(client, result_id))
    except Exception as exc:  # noqa: BLE001
        logger.warning("citation verification map failed: %s", exc)

    kept = 0
    for paper in candidates:
        answer = _map_output_for_document(outputs, paper.paperclip_id)
        if _verification_verdict(answer) != "keep":
            previous_status = paper.analysis_status
            _role, _wrong, rejected_status = _parse_map_assessment(answer)
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.citation_stance = "none"
            paper.analysis_status = (
                rejected_status
                if rejected_status in {"bibliography_only", "not_found"}
                else (
                    previous_status
                    if previous_status
                    in {"bibliography_only", "not_found", "extraction_only"}
                    else "verification_rejected"
                )
            )
            continue
        role, wrongly_interpreted, status = _parse_map_assessment(answer)
        contexts = _validated_map_contexts(
            answer,
            _parse_map_contexts(answer),
            target,
        )
        contexts = [
            context
            for context in contexts
            if not _has_model_commentary(context.text)
            and "…" not in context.text
            and "..." not in context.text
        ]
        if status != "in_text" or not contexts:
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.citation_stance = "none"
            paper.analysis_status = "verification_rejected"
            continue
        paper.contexts = contexts[:1]
        paper.impact_role = _scorecard_context_role(
            role,
            paper.contexts[0],
            target,
        )
        paper.wrongly_interpreted = wrongly_interpreted
        paper.citation_stance = _parse_citation_stance(answer)
        paper.reuse_tags = _parse_reuse_tags(answer)
        decision = (
            "specificity_adjudication"
            if paper.impact_role == "real_mention" and role != "real_mention"
            else "model"
        )
        paper.summary = (
            f"{answer.rstrip()}\n"
            f"MODEL_ROLE: {role}\n"
            f"FINAL_ROLE: {paper.impact_role}\n"
            f"ROLE_DECISION: {decision}"
        )
        if paper.impact_role == "drive_by":
            paper.reuse_tags = []
        paper.analysis_status = "in_text"
        paper.bibliography_only = False
        kept += 1

    emit_event(
        on_event,
        "summary",
        status="verification_ok",
        verified=kept,
        rejected=len(candidates) - kept,
    )
    return papers


def _scorecard_json_answer(text: str) -> dict[str, Any] | None:
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", text or "", re.DOTALL)
        if not match:
            return None
        try:
            value = json.loads(match.group())
        except json.JSONDecodeError:
            return None
    return value if isinstance(value, dict) else None


def _best_deterministic_context(
    contexts: list[CitationContext],
    target: TargetPaper | None = None,
) -> CitationContext | None:
    """Rank located passages: a solo marker in prose that names the target and
    describes what it did beats a citation pile, a table row, or a stray
    number every time."""
    names: list[str] = []
    if target is not None:
        names.extend(alias.lower() for alias in target.aliases)
        first_author = re.split(r"[,;]", target.authors or "", maxsplit=1)[0].strip()
        if first_author:
            names.append(f"{first_author.split()[-1].lower()} et al")
    candidates: list[tuple[int, int, CitationContext]] = []
    for context in contexts:
        if not _quote_contains_citation_key(context.text, context.citation_key):
            continue
        lowered = context.text.lower()
        score = 0
        if _is_table_or_math_row(context.text) or _looks_like_bibliography(
            context.line or 0, context.text, None
        ):
            score -= 100
        score += 30 if re.search(r"\b(?:we|our)\b", lowered) else 0
        score += 20 if re.search(
            r"\b(?:use|used|utili[sz]e|following|introduced|proposed|architecture|"
            r"transformer|attention heads|investigated|model|method|dataset|"
            r"trained|evaluate|benchmark|compare|similar to|based on)\b",
            lowered,
        ) else 0
        score += 30 if any(name in lowered for name in names) else 0
        score -= 50 if re.search(
            r"documentclass|end\{document\}|sigma|%\)|\d+\.\d+%",
            lowered,
        ) else 0
        score -= 40 if _is_grouped_citation(context) else 0
        words = len(re.findall(r"\b[\w'-]+\b", context.text))
        score -= 30 if words <= 6 else 0
        candidates.append((score, context.line or 0, context))
    if not candidates:
        return None
    candidates.sort(key=lambda item: (-item[0], item[1]))
    return candidates[0][2]


_ADOPTION_RE = re.compile(
    r"(?i)\b(?:following|based on|build(?:ing)? on|similar to|we\s+(?:use|used|"
    r"apply|applied|adopt|adopted|implement|implemented|feed|utili[sz]e|"
    r"employ|leverage|exploit|train(?:ed)?|evaluate|evaluated|benchmark|compare|"
    r"compared|initiali[sz]ed?|work with|fine-?tune)|initiali[sz]ed\s+with\s+weights|"
    r"weights\s+from|pre-?trained\s+on|trained\s+on|evaluated?\s+on|tested\s+on|"
    r"collected\s+by|(?:dataset|data)\s+(?:from|of|released\s+by)|"
    r"compar(?:ed|ing)\s+(?:\w+\s+){0,2}(?:against|with|to)|benchmarked\s+against|"
    r"(?:was|were)\s+used\s+as\s+(?:an?\s+)?(?:external\s+)?(?:test|validation|training))\b"
)


def _citation_group_size(context: CitationContext) -> int:
    """Distinct reference numbers cited in the passage's bracket/paren groups."""
    text = context.text or ""
    numbers: set[int] = set()
    for group in re.findall(r"[\[(]([\d,;\s–-]+)[\])]", text):
        if _is_year_like_marker(group.strip()):
            continue
        for token in re.split(r"[,;]", group):
            token = token.strip().replace("–", "-")
            span = re.fullmatch(r"(\d+)\s*-\s*(\d+)", token)
            if span:
                low, high = int(span.group(1)), int(span.group(2))
                if 0 < high - low < 100:
                    numbers.update(range(low, high + 1))
            elif token.isdigit():
                numbers.add(int(token))
    return len(numbers)


def _scorecard_context_role(
    model_role: str,
    context: CitationContext,
    target: TargetPaper,
) -> str:
    if len(re.findall(r"\b[\w'-]+\b", context.text or "")) <= 5:
        return "drive_by"
    quote = context.text
    adoption = _ADOPTION_RE.search(quote)
    if _is_grouped_citation(context):
        # "We evaluated on three public datasets [12][19][16]" uses each
        # work; a long pile ("[3-18]") does not.
        if adoption and _citation_group_size(context) <= 3:
            return "real_mention"
        return "drive_by"
    if _is_target_specific_description(context, target):
        return "real_mention"
    if _is_specific_citation_attribution(context):
        return "real_mention"
    if adoption and _quote_contains_citation_key(quote, context.citation_key):
        return "real_mention"
    generic = re.search(
        r"(?i)\b(?:such as|for example|several use cases|is a network "
        r"architecture|is an? (?:emerging|common|widely used) "
        r"(?:technology|method)|are (?:a |the )?(?:robust |standard )?"
        r"architecture|related work|background)\b",
        quote,
    )
    if generic:
        return "drive_by"
    if re.search(
        r"(?i)\bmay\s+(?:still\s+)?(?:suffer|fail|struggle|degrade|hurt)\b",
        quote,
    ):
        return "drive_by"
    if re.search(
        r"(?i)\bhallucinations?\b.{0,100}\bmitigated\b.{0,100}"
        r"\bretrieval[- ]augmented\s+generation\b",
        quote,
    ):
        return "drive_by"
    return "real_mention" if model_role == "real_mention" else "drive_by"


def _quote_exists_in_paper(
    client: Any,
    paper: MatchedCitingPaper,
    quote: str,
) -> bool:
    if not paper.paperclip_id or not quote:
        return False
    normalized_quote = _normalized_quote(quote)
    if any(
        normalized_quote in _normalized_quote(context.text)
        for context in paper.contexts
    ):
        return True

    anchor_words = normalized_quote.split()[:10]
    if anchor_words:
        anchor_pattern = r"\s+".join(re.escape(word) for word in anchor_words)
        hits = _grep_content_lines(
            client,
            paper.paperclip_id,
            anchor_pattern,
        )
        if any(
            normalized_quote in _normalized_quote(text)
            for _, text, is_match in hits
            if is_match
        ):
            return True

    # Preserve the full-source check as a rare fallback when an exact passage
    # spans content blocks or cannot be located by its opening words.
    try:
        result = client.execute(
            "cat",
            ["--full", f"/papers/{paper.paperclip_id}/content.lines"],
            timeout=120,
        )
    except Exception:  # noqa: BLE001
        return False
    source = _normalized_quote(getattr(result, "output", "") or "")
    return normalized_quote in source


def _valid_fallback_context(
    client: Any,
    paper: MatchedCitingPaper,
    context: CitationContext | None,
) -> bool:
    """Accept a backup passage only when exact source text contains its marker."""
    if context is None:
        return False
    section = (context.section or "").lower()
    quote = context.text or ""
    return (
        "reference" not in section
        and "bibliograph" not in section
        and bool((context.citation_key or "").strip())
        and _quote_contains_citation_key(quote, context.citation_key)
        and not _looks_like_bibliography(context.line or 0, quote, None)
        and not _is_table_or_math_row(quote)
        and _quote_exists_in_paper(client, paper, quote)
        and not _has_model_commentary(quote)
        and "…" not in quote
        and "..." not in quote
    )


def _target_name_patterns(target: TargetPaper) -> list[str]:
    """Regexes for the target's mined names and first-author citation form."""
    patterns = [_alias_pattern(alias) for alias in target.aliases if alias.strip()]
    first_author = re.split(r"[,;]", target.authors or "", maxsplit=1)[0].strip()
    surname = first_author.split()[-1] if first_author else ""
    if len(surname) >= 2:
        patterns.append(rf"(?i)\b{re.escape(surname)}\s+(?:et\s+al|and\s+\w+|&)")
    short_title = (target.title or "").split(":", 1)[0].strip()
    if re.fullmatch(r"[A-Za-z0-9-]{4,24}", short_title):
        patterns.append(_alias_pattern(short_title))
    return patterns


def _quote_names_target(
    quote: str,
    citation_key: str,
    paper: MatchedCitingPaper,
    target: TargetPaper,
) -> str:
    """Return the marker or name that ties ``quote`` to the target, or ""."""
    for key in (citation_key, paper.citation_marker):
        key = (key or "").strip()
        if key and _quote_contains_citation_key(quote, key):
            return key
    for pattern in _target_name_patterns(target):
        match = re.search(pattern, quote)
        if match:
            return match.group().strip()
    return ""


def _verifier_drop_reason(
    *,
    status: str,
    quote: str,
    had_deterministic_passage: bool,
) -> str:
    """Name why the verifier stage kept no passage for a paper."""
    if had_deterministic_passage:
        return "passage_failed_validation"
    if status == "bibliography_only":
        return "model_bibliography_only"
    if status != "in_text":
        return "model_not_found"
    if not quote:
        return "model_no_quote"
    return "model_quote_not_found"


MODEL_QUOTE_MIN_TOKEN_OVERLAP = 0.9
MODEL_QUOTE_LINE_WINDOW = 2


def _quote_tokens(text: str) -> list[str]:
    """Lower-case word tokens of at least two characters."""
    return [
        token
        for token in re.findall(r"[0-9a-z]+", _normalized_quote(text).lower())
        if len(token) >= 2
    ]


def _quote_token_overlap(quote: str, source: str) -> float:
    """Share of quote tokens present in ``source``, order-free, multiset-aware.

    PDF-derived text breaks words at line ends, drops ligatures, and turns
    hyphens into spaces. A verbatim substring check fails on every such
    quote, so the model's passage is judged by how many of its words the
    source window contains.
    """
    quote_tokens = _quote_tokens(quote)
    if not quote_tokens:
        return 0.0
    source_counts = Counter(_quote_tokens(source))
    found = 0
    for token in quote_tokens:
        if source_counts[token] > 0:
            source_counts[token] -= 1
            found += 1
    return found / len(quote_tokens)


def _content_lines_window(
    client: Any,
    paperclip_id: str,
    line_no: int,
    radius: int = MODEL_QUOTE_LINE_WINDOW,
) -> list[tuple[int, str]]:
    """Return ``(line_no, text)`` rows around ``line_no`` (``L<n>: text`` format)."""
    if not paperclip_id or line_no <= 0:
        return []
    start = max(1, line_no - radius)
    end = line_no + radius
    try:
        result = client.execute(
            "cat",
            ["--lines", f"{start}-{end}", f"/papers/{paperclip_id}/content.lines"],
            timeout=60,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug("cat lines %s-%s in %s failed: %s", start, end, paperclip_id, exc)
        return []
    output = _strip_ansi(getattr(result, "output", "") or "")
    rows: list[tuple[int, str]] = []
    for raw in output.splitlines():
        match = _GREP_LINE_RE.match(raw.strip())
        if match and start <= int(match.group(1)) <= end:
            rows.append((int(match.group(1)), match.group(3)))
    return rows


def _model_located_context(
    client: Any,
    paper: MatchedCitingPaper,
    target: TargetPaper,
    quote: str,
    citation_key: str,
    *,
    line_hint: int | None = None,
) -> CitationContext | None:
    """Turn a model-found quote into a context anchored on real body text.

    The verifier is told to search the paper when no deterministic passage
    exists. Its quote is accepted when (1) it is not a bibliography row,
    (2) it carries the target's marker, a mined name, or the first author,
    and (3) the body text at the reported line, or found by the quote's
    opening words, contains at least ``MODEL_QUOTE_MIN_TOKEN_OVERLAP`` of
    the quote's words and also carries the marker or name. The returned
    context holds the source text, not the model's rendering of it.
    """
    quote = _normalized_quote(quote)
    if len(quote) < 25 or _has_model_commentary(quote) or "…" in quote or "..." in quote:
        return None
    if _looks_like_bibliography(0, quote, None) or _is_table_or_math_row(quote):
        return None
    key = _quote_names_target(quote, citation_key, paper, target)
    if not key:
        return None
    paperclip_id = paper.paperclip_id or ""
    reference_start = _reference_section_start(client, paperclip_id)

    def _accept(line_no: int, source_text: str) -> CitationContext | None:
        if reference_start is not None and line_no >= reference_start:
            return None
        if _looks_like_bibliography(line_no, source_text, None):
            return None
        if _is_table_or_math_row(source_text):
            return None
        source_key = _quote_names_target(source_text, citation_key, paper, target)
        if not source_key:
            return None
        text = _normalized_quote(source_text)
        if len(text) > 600:
            focused = _extract_mention_sentences(
                text, _citation_marker_pattern(source_key)
            )
            if focused:
                text = _normalized_quote(focused)
        return CitationContext(
            section="body", line=line_no, text=text, citation_key=source_key
        )

    # 1. Exact match on a line found by the quote's opening words.
    anchor_words = quote.split()[:8]
    hits = _grep_content_lines(
        client,
        paperclip_id,
        r"\s+".join(re.escape(word) for word in anchor_words),
    )
    for line_no, text, is_match in hits:
        if is_match and quote in _normalized_quote(text):
            return _accept(line_no, text)

    # 2. The line the model reported: accept a close, not verbatim, match
    #    when the window there carries the marker or the target's name.
    if line_hint:
        window = _content_lines_window(client, paperclip_id, line_hint)
        if window:
            joined = " ".join(text for _, text in window)
            if _quote_token_overlap(quote, joined) >= MODEL_QUOTE_MIN_TOKEN_OVERLAP:
                best = max(
                    window,
                    key=lambda row: _quote_token_overlap(quote, row[1]),
                )
                context = _accept(best[0], best[1])
                if context is not None:
                    return context

    # 3. Close match on any line found by the opening words.
    for line_no, text, is_match in hits:
        if is_match and (
            _quote_token_overlap(quote, text) >= MODEL_QUOTE_MIN_TOKEN_OVERLAP
        ):
            context = _accept(line_no, text)
            if context is not None:
                return context

    # 4. Rare: the exact quote spans content blocks. Keep the model quote
    #    when the whole source contains it verbatim.
    if _quote_exists_in_paper(client, paper, quote):
        return CitationContext(section="body", line=None, text=quote, citation_key=key)
    return None


def _is_fast_verifier_candidate(paper: MatchedCitingPaper) -> bool:
    """Use the no-tool lane only for exact deterministic body evidence."""
    if paper.bibliography_only or not paper.contexts:
        return False
    context = _best_deterministic_context(paper.contexts)
    return bool(
        context
        and context.citation_key
        and len(_normalized_quote(context.text)) >= 40
        and _quote_contains_citation_key(context.text, context.citation_key)
    )


def _verify_scorecard_candidates(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    target_summary: str = "",
    *,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> tuple[list[MatchedCitingPaper], bool]:
    candidates = [
        paper
        for paper in papers
        if paper.paperclip_id
        and paper.has_fulltext
        and paper.analysis_status != "not_analyzed"
    ]
    if not candidates or _cancelled(cancel):
        return papers, True
    emit_event(
        on_event,
        "summary",
        status="verification_started",
        paper_count=len(candidates),
        message="Verifying deterministic citation evidence with Paperclip tools",
    )
    outputs: dict[str, str] = {}
    result_ids: list[str] = []
    fast_candidates = [
        paper for paper in candidates if _is_fast_verifier_candidate(paper)
    ]
    fast_ids = {id(paper) for paper in fast_candidates}
    audit_candidates = [
        paper for paper in candidates if id(paper) not in fast_ids
    ]
    lane_progress: dict[str, int] = {}
    progress_lock = threading.Lock()

    def _run_lane(
        lane: list[MatchedCitingPaper], worker: str
    ) -> tuple[dict[str, str], str | None]:
        if not lane:
            return {}, None
        doc_ids = [str(paper.paperclip_id) for paper in lane]
        task_queries = {
            str(paper.paperclip_id): build_scorecard_verifier_query(
                target,
                paper,
                target_summary,
            )
            for paper in lane
        }
        streamed_output = ""
        lane_result_id: str | None = None
        args = [
            "--worker",
            worker,
            "--output-schema",
            json.dumps(SCORECARD_VERIFIER_SCHEMA, separators=(",", ":")),
            "--task-queries-json",
            json.dumps(task_queries, separators=(",", ":"), ensure_ascii=False),
            "--document-ids",
            ",".join(doc_ids),
            "-n",
            str(len(doc_ids)),
            "Verify the assigned scorecard citation.",
        ]
        for event in client.stream("map", args, timeout=1800):
            if _cancelled(cancel):
                break
            lane_result_id = (
                getattr(event, "result_id", None) or lane_result_id
            )
            streamed_output = getattr(event, "output", "") or streamed_output
            completed = getattr(event, "completed", None)
            if isinstance(completed, int):
                lane_completed = min(len(lane), max(0, completed))
                with progress_lock:
                    lane_progress[worker] = lane_completed
                    total_completed = sum(lane_progress.values())
                current_paper = lane[
                    min(max(lane_completed - 1, 0), len(lane) - 1)
                ]
                emit_event(
                    on_event,
                    "summary",
                    status="progress",
                    completed=total_completed,
                    total=len(candidates),
                    current_item=(
                        getattr(event, "title", None)
                        or getattr(event, "document_title", None)
                        or getattr(event, "document_id", None)
                        or current_paper.title
                        or "Citing paper"
                    ),
                )
        lane_outputs = _parse_map_output_summaries(streamed_output)
        lane_outputs.update(_full_map_outputs(client, lane_result_id))
        if not lane_outputs:
            logger.warning(
                "%s returned no scorecard outputs (papers=%d, result_id=%s, "
                "streamed_chars=%d)",
                worker,
                len(lane),
                lane_result_id or "-",
                len(streamed_output),
            )
        return lane_outputs, lane_result_id

    def _run_lane_with_retry(
        lane: list[MatchedCitingPaper], worker: str
    ) -> tuple[dict[str, str], str | None]:
        """Retry an empty lane once before the whole shard is failed.

        One empty map response is usually a transient provider miss. A retry
        here is far cheaper than failing the shard, which discards the other
        lane's outputs and re-runs both lanes on the next attempt.
        """
        lane_outputs, lane_result_id = _run_lane(lane, worker)
        if lane_outputs or not lane or _cancelled(cancel):
            return lane_outputs, lane_result_id
        logger.warning("%s retrying once after an empty response", worker)
        return _run_lane(lane, worker)

    lanes = [
        (fast_candidates, "scorecard-verifier-fast"),
        (audit_candidates, "scorecard-verifier"),
    ]
    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = {
            pool.submit(_run_lane_with_retry, lane, worker): (lane, worker)
            for lane, worker in lanes
            if lane
        }
        for future in as_completed(futures):
            lane, worker = futures[future]
            try:
                lane_outputs, lane_result_id = future.result()
            except Exception as exc:  # noqa: BLE001
                logger.warning("%s map failed: %s", worker, exc)
                return papers, False
            if not lane_outputs and lane:
                logger.warning(
                    "%s returned no scorecard outputs after a retry", worker
                )
                return papers, False
            outputs.update(lane_outputs)
            if lane_result_id:
                result_ids.append(lane_result_id)
    if not outputs:
        return papers, False

    kept = 0
    for paper in candidates:
        answer = _scorecard_json_answer(
            _map_output_for_document(outputs, paper.paperclip_id)
        )
        had_deterministic_passage = bool(paper.contexts)
        if not answer:
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.citation_stance = "none"
            paper.analysis_status = "verification_rejected"
            paper.drop_reason = "no_model_answer"
            continue
        status = str(answer.get("citation_status") or "not_found")
        model_role = str(answer.get("role") or "drive_by")
        passage_id = str(answer.get("passage_id") or "").strip()
        quote = str(answer.get("quote") or "").strip()
        citation_key = str(answer.get("citation_key") or "").strip()
        line_hint = answer.get("line")
        line_hint = int(line_hint) if isinstance(line_hint, int) and line_hint > 0 else None
        source_contexts = {
            _scorecard_passage_id(candidate): candidate
            for candidate in paper.contexts[:8]
        }
        context = source_contexts.get(passage_id)
        if context is None and quote and citation_key:
            normalized_quote = _normalized_quote(quote)
            context = next(
                (
                    candidate
                    for candidate in paper.contexts[:8]
                    if _normalized_quote(candidate.text) == normalized_quote
                    and candidate.citation_key.strip() == citation_key
                ),
                None,
            )
        model_located = False
        if context is None and status == "in_text" and quote:
            # No supplied passage matched. The model searched the paper
            # itself; accept its quote when the body text at the reported
            # line (or found by its opening words) matches it closely and
            # carries the target's marker, name, or author.
            context = _model_located_context(
                client, paper, target, quote, citation_key, line_hint=line_hint
            )
            model_located = context is not None
        selected_source_passage = context is not None
        if context is not None:
            answer.update(
                {
                    "quote": context.text,
                    "citation_key": context.citation_key,
                    "line": context.line or 0,
                    "section": context.section or "body",
                }
            )
        valid = (
            status == "in_text"
            and selected_source_passage
            and (model_located or _valid_fallback_context(client, paper, context))
        )
        used_fallback = False
        if not valid:
            fallback = _best_deterministic_context(paper.contexts, target)
            if _valid_fallback_context(client, paper, fallback):
                context = fallback
                valid = True
                used_fallback = True
        if model_located:
            answer["passage_source"] = "model_located"
        if not valid:
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.citation_stance = "none"
            paper.analysis_status = "excluded_no_valid_passage"
            paper.drop_reason = _verifier_drop_reason(
                status=status,
                quote=quote,
                had_deterministic_passage=had_deterministic_passage,
            )
            if (
                had_deterministic_passage
                or paper.citation_marker.strip()
                or status == "bibliography_only"
            ):
                # The citation itself is proven: a marker or reference-list
                # entry exists, or the model confirmed the entry. Only the
                # body passage is missing, so the paper stays a drive-by.
                paper.bibliography_only = True
            continue
        paper.drop_reason = ""
        paper.contexts = [context]
        if used_fallback:
            # The model classified another passage. Apply only deterministic,
            # conservative rules to this verified backup passage.
            model_role = "drive_by"
            answer.update(
                {
                    "quote": context.text,
                    "citation_key": context.citation_key,
                    "line": context.line or 0,
                    "section": context.section or "body",
                    "role": model_role,
                    "stance": "none",
                    "reason": "Used a strictly validated deterministic passage.",
                }
            )
        paper.impact_role = _scorecard_context_role(model_role, context, target)
        decision = (
            "specificity_adjudication"
            if paper.impact_role == "real_mention" and model_role != "real_mention"
            else "model"
        )
        tags = answer.get("reuse_tags") or []
        paper.reuse_tags = sorted(
            {
                str(tag).strip().lower()
                for tag in tags
                if str(tag).strip().lower() in _REUSE_TAGS
            }
        )
        if paper.impact_role == "drive_by":
            paper.reuse_tags = []
        paper.wrongly_interpreted = str(
            answer.get("interpretation_check") or ""
        ).lower().startswith("wrong")
        paper.citation_stance = (
            "none"
            if used_fallback
            else _parse_citation_stance(json.dumps(answer, ensure_ascii=False))
        )
        answer["model_role"] = model_role
        answer["final_role"] = paper.impact_role
        answer["role_decision"] = decision
        paper.summary = json.dumps(answer, ensure_ascii=False)
        paper.analysis_status = "in_text"
        paper.bibliography_only = False
        kept += 1
    _recheck_citation_stance(
        client,
        candidates,
        target,
        on_event=on_event,
        cancel=cancel,
    )
    emit_event(
        on_event,
        "summary",
        status="verification_ok",
        verified=kept,
        rejected=len(candidates) - kept,
        map_result_id=",".join(result_ids) or None,
        fast_lane=len(fast_candidates),
        audit_lane=len(audit_candidates),
    )
    return papers, True


_PUSHBACK_CUES = re.compile(
    r"\b(but|however|nevertheless|although|whereas|unlike|in contrast|instead"
    r"|rather than|yet)\b"
    r"|\b(do(es)? not|did not|cannot|fail(s|ed|ing)?|lack(s|ing)?|miss(ing|es)?"
    r"|no ability|no control|unable|neglect(s|ed)?|ignor(e|es|ed|ing)|loses"
    r"|not (require|consider|account|include|contain|capture|address|handle"
    r"|eliminate|guarantee|scale))\b"
    r"|\b(outperform(s|ed)?|better than|worse|weaker|superior|inferior"
    r"|only show(s)?|expensive|jeopardiz|adversely|contrary to|limited to"
    r"|too narrow|outdated)\b"
    r"|\b(while|whereas|in comparison|by contrast)\s+(our|we|this (work|paper))\b",
    re.IGNORECASE,
)

# The map worker allow-list is enforced by the CLI and by the papers server, so
# the re-check rides an approved worker instead of adding a new name.
STANCE_RECHECK_WORKER = "scorecard-verifier-fast"

STANCE_RECHECK_SCHEMA = {
    "type": "object",
    "required": ["stance", "reason"],
    "properties": {
        "stance": {"type": "string"},
        "reason": {"type": "string"},
    },
    "additionalProperties": True,
}


def stance_recheck_enabled() -> bool:
    """Whether a quote carrying pushback words gets a second stance question."""
    raw = os.getenv("SCORECARD_STANCE_RECHECK", "true").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def quote_has_pushback_cue(text: str) -> bool:
    """Match the cue set measured on labelled contradictory passages."""
    return bool(_PUSHBACK_CUES.search(text or ""))


def _needs_stance_recheck(paper: MatchedCitingPaper) -> bool:
    if paper.analysis_status != "in_text":
        return False
    if (paper.citation_stance or "none") == "contradictory":
        return False
    quote = paper.contexts[0].text if paper.contexts else ""
    return quote_has_pushback_cue(quote)


def build_stance_recheck_query(
    target: TargetPaper,
    paper: MatchedCitingPaper,
) -> str:
    """Ask only about stance, on one quote, so the decision is not diluted."""
    quote = paper.contexts[0].text if paper.contexts else ""
    target_label = target.title or target.doi or "the target paper"
    return (
        "Decide the STANCE of this one passage toward the target paper. "
        "Answer about stance only.\n\n"
        f"TARGET: {target_label}\n"
        f"CITING PAPER: {paper.title or paper.paperclip_id or 'citing paper'}\n"
        f"PASSAGE: {quote}\n\n"
        f"{_STANCE_INSTRUCTIONS}"
        "Return JSON with stance and a short reason. Do not read the paper again; "
        "judge the passage as given."
    )


def _recheck_citation_stance(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> int:
    """Re-ask stance for kept quotes that carry pushback words.

    The full verifier prompt decides role, quote, tags, and stance at once, and it
    tends to read a contrast as neutral. One narrow question per flagged quote
    recovers those cases.
    """
    if not stance_recheck_enabled() or _cancelled(cancel):
        return 0
    flagged = [
        paper
        for paper in papers
        if paper.paperclip_id and _needs_stance_recheck(paper)
    ]
    if not flagged:
        return 0
    task_queries = {
        str(paper.paperclip_id): build_stance_recheck_query(target, paper)
        for paper in flagged
    }
    doc_ids = [str(paper.paperclip_id) for paper in flagged]
    args = [
        "--worker",
        STANCE_RECHECK_WORKER,
        "--output-schema",
        json.dumps(STANCE_RECHECK_SCHEMA, separators=(",", ":")),
        "--task-queries-json",
        json.dumps(task_queries, separators=(",", ":"), ensure_ascii=False),
        "--document-ids",
        ",".join(doc_ids),
        "-n",
        str(len(doc_ids)),
        "Decide citation stance for the assigned passage.",
    ]
    streamed_output = ""
    result_id: str | None = None
    try:
        for event in client.stream("map", args, timeout=600):
            if _cancelled(cancel):
                return 0
            result_id = getattr(event, "result_id", None) or result_id
            streamed_output = getattr(event, "output", "") or streamed_output
    except Exception as exc:  # noqa: BLE001
        logger.warning("stance recheck failed: %s", exc)
        return 0
    outputs = _parse_map_output_summaries(streamed_output)
    outputs.update(_full_map_outputs(client, result_id))
    if not outputs:
        return 0
    changed = 0
    for paper in flagged:
        answer = _scorecard_json_answer(
            _map_output_for_document(outputs, paper.paperclip_id)
        )
        if not answer:
            continue
        stance = _parse_citation_stance(json.dumps(answer, ensure_ascii=False))
        if stance != "contradictory":
            continue
        paper.citation_stance = "contradictory"
        changed += 1
        try:
            summary = json.loads(paper.summary) if paper.summary else {}
        except json.JSONDecodeError:
            summary = {}
        if isinstance(summary, dict):
            summary["stance"] = "contradictory"
            summary["stance_recheck"] = {
                "reason": str(answer.get("reason") or "")[:240],
            }
            paper.summary = json.dumps(summary, ensure_ascii=False)
    emit_event(
        on_event,
        "summary",
        status="stance_recheck",
        checked=len(flagged),
        changed=changed,
        map_result_id=result_id,
    )
    return changed


def _is_grouped_citation(context: CitationContext) -> bool:
    """Return true when a numeric target marker is one item in a citation group."""
    text = context.text or ""
    author_match = re.search(
        r"(?i)\b([a-z][a-z'-]+)\s+et\s+al",
        context.citation_key or "",
    )
    if author_match:
        author = author_match.group(1)
        groups: list[str] = []
        depth = 0
        start = 0
        for index, character in enumerate(text):
            if character == "(":
                if depth == 0:
                    start = index + 1
                depth += 1
            elif character == ")" and depth:
                depth -= 1
                if depth == 0:
                    groups.append(text[start:index])
        for group in groups:
            if re.search(rf"(?i)\b{re.escape(author)}\s+et\s+al", group) and len(
                re.findall(r"(?i)\bet\s+al\b", group)
            ) > 1:
                return True
        citation_list = re.search(
            r"(?i)\bet\s+al\.?\s*[\[(][^\])]*[\])]\s*"
            r"(?:,\s*(?:and\s+)?|\s+and\s+)"
            r"(?:\w+\s+et\s+al\.?\s*[\[(][^\])]*[\])]\s*,\s*)*"
            r"\w+\s+et\s+al",
            text,
        )
        if citation_list and re.search(
            rf"(?i)\b{re.escape(author)}\s+et\s+al",
            citation_list.group(),
        ):
            return True
        if re.search(
            rf"(?i)\b{re.escape(author)}\s+et\s+al\.?\s*"
            r"[\[(][^\])]*[\])]\s+and\s+\w+\s+et\s+al",
            text,
        ):
            return True
    key_number = re.search(r"\d+", context.citation_key or "")
    if not key_number:
        return False
    target_number = int(key_number.group())
    # A standalone marker attributes its local clause to the target. Other
    # citations elsewhere in the same passage do not make it an undifferentiated
    # group.
    standalone = re.search(
        rf"[\[(]\s*{target_number}\s*[\])]",
        text,
    )
    if standalone:
        outer_group = re.search(
            rf"\([^()]*;[^()]*[\[(]\s*{target_number}\s*[\])][^()]*\)",
            text,
        )
        if outer_group:
            return True
        # Adjacent bracket lists: "[21],[22],[23]" or "[25]–[27]" are one
        # citation pile even though each number has its own brackets.
        adjacent = re.search(
            rf"(?:[\])]\s*[,;–-]\s*)[\[(]\s*{target_number}\s*[\])]"
            rf"|[\[(]\s*{target_number}\s*[\])]\s*[,;–-]\s*[\[(]\s*\d",
            text,
        )
        if adjacent:
            return True
        for start, end in re.findall(r"\[(\d{1,3})\]\s*[–-]\s*\[(\d{1,3})\]", text):
            if int(start) <= target_number <= int(end):
                return True
        return False
    for start, end in re.findall(r"(\d{1,3})\s*[–-]\s*(\d{1,3})", text):
        if int(start) <= target_number <= int(end) and start != end:
            return True
    group_pattern = re.compile(
        r"(?<!\d)\d{1,3}(?:\s*(?:,|;|\band\b)\s*\d{1,3})+\b",
        re.IGNORECASE,
    )
    for match in group_pattern.finditer(text):
        numbers = [int(value) for value in re.findall(r"\d{1,3}", match.group())]
        if target_number in numbers and len(numbers) > 1:
            return True
    return False


def _is_specific_citation_attribution(context: CitationContext) -> bool:
    """Conservatively promote a concrete claim tied to the verified marker."""
    text = context.text or ""
    if not _quote_contains_citation_key(text, context.citation_key):
        return False
    return bool(
        re.search(
            r"(?i)\b(?:"
            r"following.{0,60}\bmethod(?:ology)?|"
            r"inspir(?:e|ed|es|ing)\b|"
            r"(?:sampled|modified|perturbed|highlighted|found|showed|"
            r"shown|demonstrated|reported|illustrate|illustrates|illustrated)\b|"
            r"(?:do|does|did)\s+not\s+reliably\s+adhere|"
            r"prior\s+stud(?:y|ies).{0,80}\b(?:only|irrelevant|corrupted|"
            r"limitation)|"
            r"(?:only|irrelevant|corrupted|limitation).{0,80}\bprior\s+"
            r"stud(?:y|ies)|"
            r"focused\s+on\s+(?:developing|building|creating|evaluating)"
            r")",
            text,
        )
    )


def _is_target_specific_description(
    context: CitationContext,
    target: TargetPaper,
) -> bool:
    """Identify a named target plus a concrete description of its work."""
    text = re.sub(r"\s+", " ", context.text or "").strip().lower()
    if not text:
        return False
    names: list[str] = []
    short_title = (target.title or "").split(":", 1)[0].strip().lower()
    if short_title and len(short_title) >= 4:
        names.append(short_title)
    for alias in target.aliases:
        alias_text = alias.strip().lower()
        if len(alias_text) >= 4:
            names.append(alias_text)
            names.append(alias_text.replace("-", " "))
            names.append(alias_text.replace("-", ""))
    first_author = re.split(r"[,;]", target.authors or "", maxsplit=1)[0].strip()
    if first_author:
        surname = first_author.split()[-1].lower()
        if len(surname) >= 2:
            names.append(f"{surname} et al")
    named = any(name in text for name in names)
    if not named:
        return False
    # A name in a "such as X, Y and Z" list is an example, not a description.
    # "such as ROSIE, built on a ConvNeXt architecture" or "for instance, a
    # recent paper presented ROSIE, an AI model that ..." describes the work
    # and stays a candidate.
    for match in re.finditer(
        r"\b(?:such as|for example|for instance|e\.g\.|an example is|examples include|"
        r"includ(?:e|es|ing))\b",
        text,
    ):
        tail = text[match.end() : match.end() + 120]
        for name in names:
            at = tail.find(name)
            if at < 0:
                continue
            # "compared against approaches including ROSIE and GigaTIME"
            # still uses the work; an adoption verb keeps the candidate.
            if not _name_is_described(tail[at + len(name) :]) and not (
                _ADOPTION_RE.search(text)
            ):
                return False
    described = bool(
        re.search(
            r"\b(?:developed|proposed|introduced|presented|used|applied|implemented|"
            r"adapted|compared|benchmarked|found|showed|demonstrated|enabled|"
            r"sampled|modified|measured|highlighted|focused|inspired|"
            r"generated|generating|generates|predict(?:ed|s|ing)?|framework|method|"
            r"model|dataset|result|limitation|tested|trained|evaluated|"
            r"surpass(?:es|ed)?|outperform(?:s|ed)?|achiev(?:es|ed)|estimat(?:es|ed|ing)|"
            r"segment(?:s|ed|ing|ation)|calculat(?:es|ed)|quantif(?:y|ies|ied)|"
            r"utili[sz]ed?|leverag(?:es|ed)|initiali[sz]ed|algorithm|network|"
            r"architecture|weights|accuracy|performance|approach|pipeline|"
            r"combin(?:es|ed|ing)|infer(?:s|red|ring|ence)?|translat(?:es|ed|ion)|"
            r"reconstruct(?:s|ed|ion)?|enabl(?:es|ing))\b",
            text,
        )
    )
    return described


def _name_is_described(after_name: str) -> bool:
    """True when the text right after a target name starts a description.

    ``, an AI model that ...``, ``, built on ...``, ``[10], which predict ...``
    describe the named work. ``, DeepLIIF, HEMIT, and ...`` continues a list.
    """
    rest = re.sub(
        r"^[\s,]*(?:\[[\d,;\s–-]+\]|\([\d,;\s–-]+\)|\d{1,3})?", "", after_name
    ).lstrip(" ,;:(")
    return bool(
        re.match(
            r"(?:an?|the|which|that|built|based|trained|developed|designed|"
            r"is|was|uses|used|predicts?|generat\w*|combin\w*|infer\w*|"
            r"perform\w*|achiev\w*|provid\w*|enabl\w*|leverag\w*|employ\w*|"
            r"introduc\w*|propos\w*)\b",
            rest,
        )
    )


def _is_generic_attribution(context: CitationContext) -> bool:
    """Identify generic statements attributed only to unspecified studies."""
    return bool(
        re.search(
            r"(?i)\b(?:as\s+)?(?:suggested|reported|described|shown)\s+by\s+"
            r"(?:recent|prior|previous|other)?\s*(?:studies|work|research)"
            r"(?=\d|\W|$)",
            context.text or "",
        )
    )


def build_fulltext_reduce_question(target: TargetPaper) -> str:
    """Reduce prompt over all per-paper map answers."""
    target_label = target.title or target.doi or "the target paper"
    return (
        f"Synthesize how citing papers refer to '{target_label}'"
        + (f" (doi:{target.doi})" if target.doi else "")
        + " across ALL map answers. Count the exclusive primary roles: drive_by, "
        "real_mention, and unclassified. Identify up to 50 substantial "
        "exact quotations. List real mentions first and drive-by citations second. "
        "Within each group, prefer passages that discuss the target specifically and "
        "de-emphasize undifferentiated citation groups. Select at most one quotation "
        "per citing paper. Keep every claim and quotation grounded in the map answers. "
        'Return ONLY JSON in this form: {"summary":"one short synthesis",'
        '"highlights":[{"paper_id":"exact Paperclip document id",'
        '"role":"real_mention or drive_by","quote":"exact mapped quotation"}]}.'
    )


def _normalized_quote(text: str) -> str:
    """Normalize spacing only, so model-selected quotes remain exact."""
    return re.sub(r"\s+", " ", text or "").strip().strip('"')


def _fallback_highlights(
    papers: list[MatchedCitingPaper],
    *,
    limit: int = 50,
) -> list[CitationHighlight]:
    """List verified citations with real mentions first."""
    candidates: list[CitationHighlight] = []
    for paper in papers:
        if (
            not paper.paperclip_id
            or not paper.contexts
            or paper.analysis_status != "in_text"
        ):
            continue
        role = "real_mention" if paper.impact_role == "real_mention" else "drive_by"
        context = paper.contexts[0]
        if not _normalized_quote(context.text):
            continue
        candidates.append(
            CitationHighlight(
                paperclip_id=paper.paperclip_id,
                paper_title=paper.title,
                paper_year=paper.year,
                role=role,
                text=_normalized_quote(context.text),
                line=context.line,
                citation_key=context.citation_key,
            )
        )
    candidates.sort(key=lambda highlight: highlight.role != "real_mention")
    return candidates[:limit]


def _parse_reduce_highlights(
    output: str,
    papers: list[MatchedCitingPaper],
    *,
    limit: int = 50,
) -> tuple[str, list[CitationHighlight]]:
    """Parse reduce JSON and accept only quotes found in mapped contexts."""
    payload: dict[str, Any] | None = None
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\{", output or ""):
        try:
            candidate, _ = decoder.raw_decode((output or "")[match.start() :])
        except json.JSONDecodeError:
            continue
        if isinstance(candidate, dict) and isinstance(candidate.get("highlights"), list):
            payload = candidate
            break
    if payload is None:
        return (output or "").strip(), []

    by_id = {paper.paperclip_id: paper for paper in papers if paper.paperclip_id}
    selected: list[CitationHighlight] = []
    seen_papers: set[str] = set()
    for item in payload.get("highlights", []):
        if not isinstance(item, dict):
            continue
        paper_id = str(item.get("paper_id") or "").strip()
        paper = by_id.get(paper_id)
        if paper is None or paper_id in seen_papers:
            continue
        requested = _normalized_quote(str(item.get("quote") or ""))
        context = next(
            (
                candidate
                for candidate in paper.contexts
                if _normalized_quote(candidate.text) == requested
            ),
            None,
        )
        if context is None:
            continue
        role = "real_mention" if paper.impact_role == "real_mention" else "drive_by"
        selected.append(
            CitationHighlight(
                paperclip_id=paper_id,
                paper_title=paper.title,
                paper_year=paper.year,
                role=role,
                text=requested,
                line=context.line,
                citation_key=context.citation_key,
            )
        )
        seen_papers.add(paper_id)
        if len(selected) >= limit:
            break

    summary = str(payload.get("summary") or "").strip()
    return summary, selected


DETERMINISTIC_VERIFIER_NAME = "deterministic-rules"


def deterministic_verifier_enabled() -> bool:
    """``SCORECARD_VERIFIER=deterministic`` classifies without a model call."""
    raw = os.getenv("SCORECARD_VERIFIER", "").strip().lower()
    return raw in {"deterministic", "rules", "det"}


def _verify_scorecard_candidates_deterministic(
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    *,
    on_event: EventCallback | None = None,
) -> tuple[list[MatchedCitingPaper], bool]:
    """Classify each located passage with the deterministic role rules only.

    This is the no-model path measured by the offline harness: the best
    deterministic passage per paper and ``_scorecard_context_role``. Papers
    with no located passage count as drive-by. Stance is not assessed.
    """
    candidates = [
        paper
        for paper in papers
        if paper.paperclip_id
        and paper.has_fulltext
        and paper.analysis_status != "not_analyzed"
    ]
    if not candidates:
        return papers, True
    emit_event(
        on_event,
        "summary",
        status="verification_started",
        paper_count=len(candidates),
        verifier=DETERMINISTIC_VERIFIER_NAME,
        message="Classifying deterministic citation evidence with rules",
    )
    kept = 0
    for paper in candidates:
        best = (
            _best_deterministic_context(paper.contexts, target)
            if paper.contexts
            else None
        )
        if best is None or not (best.citation_key or "").strip():
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.citation_stance = "none"
            paper.wrongly_interpreted = False
            paper.analysis_status = (
                "bibliography_only"
                if paper.bibliography_only
                else "excluded_no_valid_passage"
            )
            continue
        paper.contexts = [best]
        paper.impact_role = _scorecard_context_role("drive_by", best, target)
        paper.reuse_tags = []
        paper.wrongly_interpreted = False
        paper.citation_stance = "none"
        answer = {
            "verdict": "keep",
            "citation_status": "in_text",
            "passage_id": _scorecard_passage_id(best),
            "quote": best.text,
            "citation_key": best.citation_key,
            "line": best.line or 0,
            "section": best.section or "body",
            "role": paper.impact_role,
            "stance": "none",
            "reuse_tags": [],
            "interpretation_check": "not_applicable",
            "centrality": 0,
            "reason": "Classified by deterministic passage rules; no model call.",
            "model_role": "",
            "final_role": paper.impact_role,
            "role_decision": DETERMINISTIC_VERIFIER_NAME,
            "verifier": DETERMINISTIC_VERIFIER_NAME,
        }
        paper.summary = json.dumps(answer, ensure_ascii=False)
        paper.analysis_status = "in_text"
        paper.bibliography_only = False
        kept += 1
    emit_event(
        on_event,
        "summary",
        status="verification_ok",
        verified=kept,
        rejected=len(candidates) - kept,
        verifier=DETERMINISTIC_VERIFIER_NAME,
    )
    return papers, True


def _summarize_with_scorecard_verifier(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    target_summary: str = "",
    *,
    limit: int,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> tuple[list[MatchedCitingPaper], str, str | None, list[CitationHighlight]]:
    """Verify deterministic candidates with one tool-enabled model pass."""
    usable = [
        paper
        for paper in papers
        if (
            paper.paperclip_id
            and paper.has_fulltext
            and paper.analysis_status != "not_analyzed"
        )
    ][:limit]
    usable_ids = {paper.paperclip_id for paper in usable}
    if not usable:
        return papers, "", None, []
    for paper in papers:
        if not paper.has_fulltext:
            continue
        if paper.paperclip_id not in usable_ids:
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.analysis_status = "not_analyzed"
            continue
        paper.summary = _fallback_passage_summary(paper)
        paper.impact_role = "drive_by"
        paper.reuse_tags = []
        paper.analysis_status = "verification_pending"
    if deterministic_verifier_enabled():
        papers, verified = _verify_scorecard_candidates_deterministic(
            papers, target, on_event=on_event
        )
    else:
        papers, verified = _verify_scorecard_candidates(
            client,
            papers,
            target,
            target_summary,
            on_event=on_event,
            cancel=cancel,
        )
    if not verified:
        if os.getenv("SCORECARD_REQUIRE_ONE_PASS", "").strip() == "1":
            # The shard scheduler retries this shard; a real fallback would
            # silently produce lower-quality labels.
            raise RuntimeError(
                "scorecard-verifier returned no outputs for this shard after a "
                "retry; the shard will be retried (legacy fallback disabled)"
            )
        logger.warning(
            "scorecard-verifier returned no outputs; using legacy two-pass verifier"
        )
        return _summarize_with_map_reduce(
            client,
            papers,
            target,
            target_summary,
            limit=limit,
            on_event=on_event,
            cancel=cancel,
        )
    target_label = target.title or target.doi or "the target paper"
    analyzed = [
        paper
        for paper in papers
        if paper.has_fulltext and paper.analysis_status != "not_analyzed"
    ]
    themes = (
        f"Verified {len(analyzed)} Paperclip full-text citing papers for how "
        f"they refer to '{target_label}'."
    )
    highlights = _fallback_highlights(papers, limit=50)
    emit_event(
        on_event,
        "summary",
        status="ok",
        summarized=len(analyzed),
        themes=themes,
    )
    return papers, themes, None, highlights


def _summarize_with_map_reduce(
    client: Any,
    papers: list[MatchedCitingPaper],
    target: TargetPaper,
    target_summary: str = "",
    *,
    limit: int,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> tuple[list[MatchedCitingPaper], str, str | None, list[CitationHighlight]]:
    """Map every Paperclip full-text citing paper, then reduce the set."""
    usable = [
        p
        for p in papers
        if (
            p.paperclip_id
            and p.has_fulltext
            and p.analysis_status != "not_analyzed"
        )
    ][:limit]
    usable_ids = {paper.paperclip_id for paper in usable}
    if not usable:
        return papers, "", None, []

    target_label = target.title or target.doi or "the target paper"
    emit_event(
        on_event,
        "summary",
        status="started",
        paper_count=len(usable),
        message=(
            "Mapping Paperclip full-text citing papers for citation "
            "specificity and importance"
        ),
    )

    summaries: dict[str, str] = {}
    themes = ""
    highlights: list[CitationHighlight] = []
    doc_ids = [p.paperclip_id for p in usable if p.paperclip_id]
    map_question = build_fulltext_map_question(target, target_summary)

    map_result_id: str | None = None
    if not _cancelled(cancel):
        try:
            # Prefer streaming map; fall back to execute.
            try:
                events = client.stream(
                    "map",
                    ["--document-ids", ",".join(doc_ids), "-n", str(len(doc_ids)), map_question],
                    timeout=900,
                )
                output = ""
                for event in events:
                    if _cancelled(cancel):
                        break
                    if hasattr(event, "result_id"):
                        map_result_id = getattr(event, "result_id", None) or map_result_id
                        output = getattr(event, "output", "") or output
                    elif hasattr(event, "completed"):
                        emit_event(
                            on_event,
                            "summary",
                            status="progress",
                            completed=getattr(event, "completed", 0),
                            total=getattr(event, "total", 0),
                            current_item=(
                                getattr(event, "title", None)
                                or getattr(event, "document_title", None)
                                or getattr(event, "document_id", None)
                                or "Full-text paper"
                            ),
                        )
                summaries.update(_parse_map_output_summaries(output))
            except (ValueError, TypeError, AttributeError):
                result = client.execute(
                    "map",
                    [
                        "--document-ids",
                        ",".join(doc_ids),
                        "-n",
                        str(len(doc_ids)),
                        map_question,
                    ],
                    timeout=900,
                )
                map_result_id = getattr(result, "result_id", None)
                summaries.update(
                    _parse_map_output_summaries(getattr(result, "output", "") or "")
                )
        except Exception as exc:  # noqa: BLE001
            logger.warning("map summary failed; using passage fallback: %s", exc)

    # The streamed map output contains short previews. Read the saved result to
    # retain complete per-paper fields, locations, and exact quotations.
    summaries.update(_full_map_outputs(client, map_result_id))
    mapped_answers = {
        paper.paperclip_id or "": _map_output_for_document(
            summaries,
            paper.paperclip_id,
        )
        for paper in usable
    }
    # Passage fallback for any paper the map did not cover.
    for paper in usable:
        pid = paper.paperclip_id or ""
        if mapped_answers.get(pid):
            summaries[pid] = mapped_answers[pid]
        elif pid:
            summaries[pid] = _fallback_passage_summary(paper)

    for paper in papers:
        pid = paper.paperclip_id or ""
        if paper.has_fulltext and pid not in usable_ids:
            paper.contexts = []
            paper.impact_role = "drive_by"
            paper.reuse_tags = []
            paper.analysis_status = "not_analyzed"
            continue
        mapped_answer = mapped_answers.get(pid, "")
        if pid in summaries:
            paper.summary = summaries[pid]
        if mapped_answer:
            paper.summary = mapped_answer
            (
                paper.impact_role,
                paper.wrongly_interpreted,
                paper.analysis_status,
            ) = _parse_map_assessment(paper.summary)
            paper.reuse_tags = (
                _parse_reuse_tags(paper.summary)
                if paper.analysis_status == "in_text"
                else []
            )
            paper.citation_stance = (
                _parse_citation_stance(paper.summary)
                if paper.analysis_status == "in_text"
                else "none"
            )
            paper.limitation_signal = False
            if paper.analysis_status == "in_text":
                parsed_contexts = _parse_map_contexts(paper.summary)
                if parsed_contexts and all(
                    "reference" in (context.section or "").lower()
                    or "bibliograph" in (context.section or "").lower()
                    for context in parsed_contexts
                ):
                    paper.contexts = []
                    paper.impact_role = "drive_by"
                    paper.analysis_status = "bibliography_only"
                    paper.reuse_tags = []
                    paper.citation_stance = "none"
                    paper.bibliography_only = True
                    continue
                mapped_contexts = _validated_map_contexts(
                    paper.summary,
                    parsed_contexts,
                    target,
                )
                if mapped_contexts:
                    paper.contexts = mapped_contexts
                    paper.bibliography_only = False
                    if paper.impact_role == "real_mention" and all(
                        _is_grouped_citation(context) for context in mapped_contexts
                    ):
                        paper.impact_role = "drive_by"
                        paper.reuse_tags = []
                else:
                    # Preserve provisional output for the independent full-text
                    # verifier, which can repair missing markers or references.
                    paper.contexts = parsed_contexts[:2]
                    paper.impact_role = "drive_by"
                    paper.analysis_status = "verification_pending"
            elif paper.analysis_status == "bibliography_only":
                paper.contexts = []
                paper.bibliography_only = True
        elif paper.has_fulltext:
            if paper.bibliography_only:
                paper.impact_role = "drive_by"
                paper.analysis_status = "bibliography_only"
            elif paper.contexts:
                # Deterministic extraction is only a candidate locator. Do not
                # present an unverified context as a real mention.
                paper.impact_role = "drive_by"
                paper.analysis_status = "extraction_only"
            else:
                paper.impact_role = "drive_by"
                paper.analysis_status = "not_found"

    papers = _verify_citation_candidates(
        client,
        papers,
        target,
        target_summary,
        on_event=on_event,
        cancel=cancel,
    )

    if not themes:
        theme_bits = [p.summary for p in papers if p.summary]
        if theme_bits:
            themes = (
                f"Mapped {len(theme_bits)} Paperclip full-text citing papers for "
                f"how they refer to '{target_label}'. "
                "See per-paper summaries for specificity and importance."
            )

    fallback = _fallback_highlights(papers)
    selected_ids = {highlight.paperclip_id for highlight in highlights}
    highlights.extend(
        highlight
        for highlight in fallback
        if highlight.paperclip_id not in selected_ids
    )
    highlights.sort(key=lambda highlight: highlight.role != "real_mention")
    highlights = highlights[:50]

    emit_event(
        on_event,
        "summary",
        status="ok",
        summarized=len([s for s in summaries.values() if s]),
        themes=themes,
        map_result_id=map_result_id,
    )
    return papers, themes, map_result_id, highlights


_USAGE_JSON_RE = re.compile(
    r"\{[^{}]*\"label\"\s*:\s*\"(?:marginal|supporting|foundational|unscored)\"[^{}]*\}",
    re.DOTALL | re.IGNORECASE,
)


def _collect_usage_quotations(
    papers: list[MatchedCitingPaper],
    *,
    limit: int = 24,
) -> list[str]:
    """Collect short quotation lines for the usage-summary prompt."""
    quotes: list[str] = []
    for paper in papers:
        title = (paper.title or paper.doi or paper.paperclip_id or "Citing paper").strip()
        year = f" ({paper.year})" if paper.year else ""
        for context in paper.contexts:
            text = (context.text or "").strip()
            if not text:
                continue
            if len(text) > 320:
                text = text[:317] + "..."
            key = (context.citation_key or "").strip()
            key_bit = f" {key}" if key else ""
            quotes.append(f'- "{text}"{key_bit} — {title}{year}')
            if len(quotes) >= limit:
                return quotes
    return quotes


def build_importance_prompt(
    target: TargetPaper,
    papers: list[MatchedCitingPaper],
    *,
    counts: dict[str, int],
    themes: str = "",
) -> str:
    """Build the Agent prompt for a constrained usage summary from quotations."""
    target_label = target.title or target.doi or "the target paper"
    quotes = _collect_usage_quotations(papers)
    quotes_block = "\n".join(quotes) if quotes else "(no direct quotation passages found)"
    reduce_block = (themes or "").strip()
    reduce_section = (
        f"\nOPTIONAL BACKGROUND (do not invent quotes from this):\n{reduce_block}\n"
        if reduce_block
        else ""
    )
    return f"""Summarize how verified real mentions talk about TARGET.

TARGET PAPER
- title: {target_label}
- doi: {target.doi or "n/a"}
- paperclip id: {target.paperclip_id or "n/a"}

PIPELINE COVERAGE
- unique citing works found: {counts.get("unique_citing", 0)}
- Paperclip full text mapped: {counts.get("readable_fulltext", 0)}
- citing works with in-text uses: {counts.get("in_text_uses", 0)}
- bibliography-only in sample: {counts.get("bibliography_only", 0)}

VERIFIED REAL-MENTION EVIDENCE (one entry per paper; use only these)
{quotes_block}
{reduce_section}
Choose EXACTLY one label:

1) marginal
   Use when the target is not discussed directly, or appears only in passing /
   related-work lists with no load-bearing claim or method reuse.

2) supporting
   Use when at least some papers cite the target directly to support a claim,
   comparison, fact, method detail, or discussion point — but it is not the
   main basis of their premise or experiments.

3) foundational
   Use when one or more papers treat the target as a significant basis for their
   premise, framing, methods, or experiments.

RULES
- Prefer the strongest well-supported label that the quotations justify.
- If quotations are only bibliographic / related-work, choose marginal.
- Write for the target paper's authors.
- One short sentence only (10-28 words).
- Be as specific as possible.
- Synthesize the dominant pattern across all entries, not one isolated quote.
- Name the concrete method, dataset, result, capability, limitation, or
  comparison when the quotations support it.
- Do not use generic citation-summary language such as "later papers cite
  this work", "support specific claims or comparisons", "treat this work as",
  or "significant basis".
- Good: "Detector evaluations now treat non-native English bias as a required
  failure mode, not a side note."
- Bad: "Later papers cite this work directly to support specific claims or
  comparisons."
- Do not invent quotations or papers.
- Do not output a numeric score.

Return ONLY compact JSON with this exact shape:
{{
  "label": "<marginal|supporting|foundational>",
  "summary": "<one short sentence>",
  "evidence": ["<short quote copied from the passages above>", "..."]
}}
"""


def _normalize_usage_label(raw: str | None) -> str | None:
    label = (raw or "").strip().lower()
    aliases = {
        "nominal": "marginal",
        "peripheral": "marginal",
        "cursory": "marginal",
        "bibliography_only": "marginal",
        "substantive": "foundational",
        "significant": "foundational",
        "critical": "supporting",
    }
    label = aliases.get(label, label)
    if label in USAGE_LABELS or label == "unscored":
        return label
    return None


def _parse_importance_payload(text: str) -> ImportanceScore | None:
    """Parse a usage-summary JSON object from LLM output."""
    raw = _strip_ansi(text or "").strip()
    if not raw:
        return None
    candidates = [raw]
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", raw, re.DOTALL)
    if fenced:
        candidates.insert(0, fenced.group(1))
    match = _USAGE_JSON_RE.search(raw)
    if match:
        candidates.insert(0, match.group(0))
    # Also accept older payloads that still include a numeric score.
    brace = re.search(r"\{.*\}", raw, re.DOTALL)
    if brace:
        candidates.append(brace.group(0))

    for candidate in candidates:
        try:
            data = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if not isinstance(data, dict):
            continue
        label = _normalize_usage_label(str(data.get("label") or ""))
        summary = str(
            data.get("summary") or data.get("rationale") or ""
        ).strip()
        if label is None or not summary:
            continue
        if label == "unscored":
            return ImportanceScore(
                score=0,
                label="unscored",
                rationale=summary,
                method="llm",
            )
        evidence_raw = data.get("evidence") or []
        evidence = [str(item).strip() for item in evidence_raw if str(item).strip()][:6]
        # Keep a single short sentence.
        summary = re.sub(r"\s+", " ", summary).strip()
        if len(summary) > 220:
            summary = summary[:217].rstrip() + "..."
        return ImportanceScore(
            score=USAGE_SCORE[label],
            label=label,
            rationale=summary,
            evidence=evidence,
            method="llm",
        )
    return None


def _heuristic_focus_label(target: TargetPaper | None) -> str:
    title = (target.title if target else "") or ""
    if ":" in title:
        title = title.split(":", 1)[0].strip()
    title = re.sub(r"\s+", " ", title).strip()
    if title:
        return title
    if target and target.doi:
        return target.doi
    return "This method"


def _heuristic_importance_score(
    papers: list[MatchedCitingPaper],
    counts: dict[str, int],
    target: TargetPaper | None = None,
) -> ImportanceScore:
    """Deterministic fallback when the LLM usage summary is unavailable."""
    total = max(0, int(counts.get("unique_citing") or 0))
    in_text = max(0, int(counts.get("in_text_uses") or 0))
    if total == 0:
        return ImportanceScore(
            score=0,
            label="unscored",
            rationale="No citing works were found, so usage cannot be summarized.",
            method="empty",
        )

    roles = {
        (paper.impact_role or "").strip().lower()
        for paper in papers
        if paper.impact_role
    }
    evidence: list[str] = []
    for paper in papers:
        for context in paper.contexts[:1]:
            quote = (context.text or "").strip()
            if quote:
                evidence.append(quote[:180])
            if len(evidence) >= 3:
                break
        if len(evidence) >= 3:
            break

    focus = _heuristic_focus_label(target)
    foundational_roles = {"significant", "foundational", "substantive"}
    supporting_roles = {"supporting", "critical", "real_mention"}
    if roles & foundational_roles:
        label = "foundational"
        summary = f"{focus} now anchors later methods or experiments."
    elif in_text > 0 or roles & supporting_roles:
        label = "supporting"
        summary = f"{focus} is used to support later claims, methods, or comparisons."
    else:
        label = "marginal"
        summary = f"{focus} appears mainly as background or related work."
    return ImportanceScore(
        score=USAGE_SCORE[label],
        label=label,
        rationale=summary,
        evidence=evidence[:4],
        method="heuristic",
    )


def _score_with_chat_agent(prompt: str) -> ImportanceScore | None:
    """Final score via the Paperclip chat Agent harness (inference Agent)."""
    if os.environ.get("CITATION_EXPLORER_USE_AGENT", "1").strip() in {
        "0",
        "false",
        "no",
    }:
        return None
    try:
        from gxl_inference_client import Agent
    except ImportError:
        logger.info("gxl_inference_client not installed; skip chat Agent scorer")
        return None

    session_id = f"citation-explorer-{uuid.uuid4().hex}"
    try:
        agent = Agent(
            model=SCORE_AGENT_MODEL,
            system_prompt=SCORE_AGENT_SYSTEM_PROMPT,
            session_id=session_id,
            agent_id="citation-explorer-scorer",
            max_iterations=1,
            timeout=180.0,
        )
        # No MCP tools: this is a pure synthesis/scoring turn.
        agent.tool_list = []
        text = agent(prompt)
        parsed = _parse_importance_payload(text)
        if parsed is not None:
            parsed.method = "agent"
        return parsed
    except Exception as exc:  # noqa: BLE001
        logger.warning("Paperclip chat Agent scoring failed: %s", exc)
        return None


def _score_with_reduce_extract(
    client: Any,
    *,
    map_result_id: str,
    prompt: str,
) -> ImportanceScore | None:
    """Fallback: ask Paperclip reduce/extract for the score JSON."""
    try:
        reduced = client.reduce(
            prompt,
            from_map=map_result_id,
            strategy="extract",
            timeout=300,
        )
        parsed = _parse_importance_payload(getattr(reduced, "output", "") or "")
        if parsed is not None:
            parsed.method = "reduce"
        return parsed
    except Exception as exc:  # noqa: BLE001
        logger.warning("reduce extract scoring failed: %s", exc)
        return None


def score_citation_importance(
    client: Any,
    target: TargetPaper,
    papers: list[MatchedCitingPaper],
    *,
    counts: dict[str, int],
    themes: str = "",
    map_result_id: str | None = None,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
) -> ImportanceScore:
    """Summarize how citing papers use the target, from quotation passages."""
    prompt = build_importance_prompt(
        target, papers, counts=counts, themes=themes
    )
    quotes = _collect_usage_quotations(papers)
    emit_event(
        on_event,
        "score",
        status="started",
        message="Summarizing how citing papers use the target from quotations",
        current_item=target.title or target.doi or "Target paper",
        prompt_chars=len(prompt),
        quotation_count=len(quotes),
        has_reduce_synthesis=bool(themes.strip()),
        map_result_id=map_result_id,
    )

    if not quotes and not (themes or "").strip():
        score = _heuristic_importance_score(papers, counts, target)
        score.prompt = prompt
        emit_event(
            on_event,
            "score",
            status="ok",
            score=score.score,
            label=score.label,
            method=score.method,
            summary=score.rationale,
        )
        return score

    if _cancelled(cancel):
        score = _heuristic_importance_score(papers, counts, target)
        score.prompt = prompt
        return score

    parsed = _score_with_chat_agent(prompt)
    if parsed is None and map_result_id and not _cancelled(cancel):
        parsed = _score_with_reduce_extract(
            client, map_result_id=map_result_id, prompt=prompt
        )

    if parsed is None:
        parsed = _heuristic_importance_score(papers, counts, target)
    parsed.prompt = prompt
    emit_event(
        on_event,
        "score",
        status="ok",
        score=parsed.score,
        label=parsed.label,
        method=parsed.method,
        summary=parsed.rationale,
        rationale=parsed.rationale,
    )
    return parsed


def run_analysis(
    client: Any,
    query: str,
    *,
    select_doi: str | None = None,
    limit: int = 200,
    skip_summary: bool = False,
    match_workers: int = DEFAULT_MATCH_WORKERS,
    on_event: EventCallback | None = None,
    cancel: CancelCheck | None = None,
    url_opener: Callable[[str], str] | None = None,
    provider_fetchers: dict[str, Callable[..., dict[str, Any]]] | None = None,
    collect_fn: Callable[..., ProviderBundle] | None = None,
) -> AnalysisResult:
    """Run the full citation-explorer pipeline and emit progress events."""
    run_started = time.perf_counter()
    timings_ms: dict[str, int] = {}
    work_counts: dict[str, int] = {}
    stage_started = time.perf_counter()
    target, candidates, err = resolve_target(
        client,
        query,
        select_doi=select_doi,
        url_opener=url_opener,
        on_event=on_event,
    )
    timings_ms["resolve"] = round((time.perf_counter() - stage_started) * 1000)
    if candidates:
        result = AnalysisResult(
            target=TargetPaper(query=query),
            candidates=candidates,
            outcome="ok",
        )
        emit_event(on_event, "done", result=result.to_dict())
        return result
    if err or target is None:
        message = format_doi_resolve_error(err, query=query)
        if message == PDF_UNSUPPORTED_MESSAGE:
            result = AnalysisResult(
                target=TargetPaper(query=query),
                notice=message,
                outcome="unsupported_input",
            )
            emit_event(on_event, "done", result=result.to_dict())
            return result
        result = AnalysisResult(
            target=TargetPaper(query=query),
            error=message,
            outcome="resolve_failed",
        )
        emit_event(on_event, "error", message=result.error)
        emit_event(on_event, "done", result=result.to_dict())
        return result

    if _cancelled(cancel):
        result = AnalysisResult(
            target=target,
            cancelled=True,
            notice=ANALYSIS_CANCELLED_MESSAGE,
            outcome="cancelled",
        )
        emit_event(on_event, "done", result=result.to_dict())
        return result

    if not target.doi and not target.paperclip_id:
        message = format_doi_resolve_error(
            "Resolved paper has no DOI or Paperclip ID",
            query=query,
        )
        result = AnalysisResult(
            target=target,
            error=message,
            outcome="resolve_failed",
        )
        emit_event(on_event, "error", message=result.error)
        emit_event(on_event, "done", result=result.to_dict())
        return result

    emit_event(
        on_event,
        "providers",
        status="started",
        doi=target.doi,
    )
    stage_started = time.perf_counter()
    collector = collect_fn or collect_providers
    try:
        if collect_fn:
            bundle = collector(
                target.doi or "",
                list_limit=limit,
                fetchers=provider_fetchers,
            )
        else:
            bundle = collector(
                target.doi or "",
                list_limit=limit,
                fetchers=provider_fetchers,
                target_title=target.title,
                paperclip_id=target.paperclip_id,
                target_year=target.year,
                target_versions=target.version_aliases,
                client=client,
            )
    except Exception as exc:  # noqa: BLE001
        message = format_provider_fetch_error(exc)
        result = AnalysisResult(
            target=target,
            error=message,
            outcome="providers_unavailable",
        )
        emit_event(on_event, "error", message=result.error)
        emit_event(on_event, "done", result=result.to_dict())
        return result

    if bundle.target_title and not target.title:
        target.title = bundle.target_title
    if bundle.target_pmid and not target.pmid:
        target.pmid = bundle.target_pmid
    if target.title and not target.authors:
        _hydrate_target_from_exact_title(client, target)

    # Drop self-edges (same DOI / PMID / Paperclip id as the target).
    target_dois = {
        value
        for value in [
            (target.doi or "").lower(),
            *[
                str(alias.get("doi") or "").lower()
                for alias in target.version_aliases
            ],
        ]
        if value
    }
    target_pmid = str(target.pmid or "")
    target_paperclip_ids = {
        value
        for value in [
            (target.paperclip_id or "").lower(),
            *[
                str(alias.get("paperclip_id") or "").lower()
                for alias in target.version_aliases
            ],
        ]
        if value
    }

    def _is_target_record(record: CitingRecord) -> bool:
        return bool(
            (record.doi and record.doi.lower() in target_dois)
            or (
                record.pmid
                and target_pmid
                and str(record.pmid) == target_pmid
            )
            or (
                record.paperclip_id
                and record.paperclip_id.lower() in target_paperclip_ids
            )
        )

    bundle.citing = [
        rec
        for rec in bundle.citing
        if not _is_target_record(rec)
    ]
    total_citations = bundle.checks.gxl_citation_count
    if total_citations is None:
        total_citations = len(bundle.citing)
    else:
        total_citations = max(total_citations, len(bundle.citing))

    timings_ms["providers"] = round((time.perf_counter() - stage_started) * 1000)
    emit_event(
        on_event,
        "providers",
        status="ok",
        provider_edge_counts=bundle.provider_edge_counts,
        unique_citing=len(bundle.citing),
        checks=bundle.checks.to_dict(),
        errors=bundle.errors,
        elapsed_ms=timings_ms["providers"],
    )

    if _cancelled(cancel):
        result = AnalysisResult(
            target=target,
            checks=bundle.checks.to_dict(),
            provider_edge_counts=bundle.provider_edge_counts,
            provider_errors=bundle.errors,
            cancelled=True,
            notice=ANALYSIS_CANCELLED_MESSAGE,
            outcome="cancelled",
        )
        emit_event(on_event, "done", result=result.to_dict())
        return result

    emit_event(
        on_event,
        "match",
        status="started",
        total=min(len(bundle.citing), DEFAULT_MATCH_ATTEMPT_LIMIT),
        available=len(bundle.citing),
        readable_target=DEFAULT_MAP_LIMIT,
        message="Matching citing works until 100 readable papers are found",
    )

    stage_started = time.perf_counter()
    matched, match_attempts = _match_until_readable_limit(
        client,
        bundle.citing,
        target,
        readable_limit=DEFAULT_MAP_LIMIT,
        attempt_limit=DEFAULT_MATCH_ATTEMPT_LIMIT,
        match_workers=match_workers,
        on_event=on_event,
        cancel=cancel,
    )

    total_citations = bundle.checks.gxl_citation_count
    if total_citations is None:
        total_citations = len(bundle.citing)

    empty_outcome, empty_error, empty_notice = assess_empty_citation_outcome(
        provider_errors=bundle.errors,
        citing_count=len(bundle.citing),
    )
    if empty_outcome != "ok":
        importance = ImportanceScore(
            score=0,
            label="unscored",
            rationale=empty_error or empty_notice or NOT_ENOUGH_CITATIONS_MESSAGE,
            method="empty",
        )
        result = AnalysisResult(
            target=target,
            counts=_empty_counts(total_citations=total_citations),
            checks=bundle.checks.to_dict(),
            provider_edge_counts=bundle.provider_edge_counts,
            provider_errors=bundle.errors,
            importance=importance,
            error=empty_error or None,
            notice=empty_notice or None,
            outcome=empty_outcome,
        )
        if result.error:
            emit_event(on_event, "error", message=result.error)
        emit_event(on_event, "done", result=result.to_dict())
        return result

    if target.paperclip_id:
        matched = [
            paper
            for paper in matched
            if paper.paperclip_id != target.paperclip_id
        ]

    # Stable order: fulltext first, then matched, then by year desc
    matched.sort(
        key=lambda p: (
            0 if p.has_fulltext else 1 if p.paperclip_id else 2,
            -(p.year or 0),
            (p.title or "").lower(),
        )
    )

    timings_ms["matching"] = round((time.perf_counter() - stage_started) * 1000)
    work_counts["match_attempts"] = match_attempts
    paperclip_matches = sum(1 for p in matched if p.paperclip_id)
    fulltext_matches = sum(1 for p in matched if p.has_fulltext)
    emit_event(
        on_event,
        "match",
        status="ok",
        paperclip_matches=paperclip_matches,
        fulltext_matches=fulltext_matches,
        match_attempts=match_attempts,
        available=len(bundle.citing),
        total=len(matched),
        elapsed_ms=timings_ms["matching"],
    )

    if _cancelled(cancel):
        result = AnalysisResult(
            target=target,
            checks=bundle.checks.to_dict(),
            provider_edge_counts=bundle.provider_edge_counts,
            provider_errors=bundle.errors,
            citing_papers=matched,
            cancelled=True,
            notice=ANALYSIS_CANCELLED_MESSAGE,
            outcome="cancelled",
            counts={
                "provider_edges": sum(bundle.provider_edge_counts.values()),
                "unique_citing": len(bundle.citing),
                "total_citations": total_citations,
                "match_attempts": match_attempts,
                "paperclip_matches": paperclip_matches,
                "readable_fulltext": fulltext_matches,
                "in_text_uses": 0,
            },
        )
        emit_event(on_event, "done", result=result.to_dict())
        return result

    analysis_limit = min(DEFAULT_MAP_LIMIT, limit)
    analysis_papers = _select_fulltext_sample(
        matched,
        target,
        limit=analysis_limit,
    )
    selected_ids = {id(paper) for paper in analysis_papers}
    for paper in matched:
        if paper.has_fulltext and id(paper) not in selected_ids:
            paper.analysis_status = "not_analyzed"

    emit_event(
        on_event,
        "context",
        status="started",
        total=len(analysis_papers),
        available_fulltext=fulltext_matches,
        random_sampled=fulltext_matches > analysis_limit,
        message="Extracting bibliography entries and in-text uses",
    )

    stage_started = time.perf_counter()
    context_stages: dict[str, int] = {}

    def _capture_stages(event: dict[str, Any]) -> None:
        if event.get("type") == "context" and event.get("status") == "stages":
            context_stages.update(
                {
                    key: int(value)
                    for key, value in event.items()
                    if isinstance(value, int) and not isinstance(value, bool)
                }
            )
        if on_event is not None:
            on_event(event)

    done_map = _extract_contexts_for_sample(
        client,
        analysis_papers,
        target,
        on_event=_capture_stages,
        cancel=cancel,
    )

    matched = [done_map.get(id(p), p) for p in matched]
    _capture_citation_lines(matched)
    timings_ms["contexts"] = round((time.perf_counter() - stage_started) * 1000)
    work_counts["context_papers"] = len(analysis_papers)
    # Keep the extraction stage counts with the run so the dashboard can show
    # which stage lost each cohort's papers instead of only the final tally.
    work_counts.update({f"context_{key}": value for key, value in context_stages.items()})
    in_text = sum(1 for p in matched if p.contexts)
    bibliography_only = sum(1 for p in matched if p.bibliography_only and not p.contexts)
    emit_event(
        on_event,
        "context",
        status="ok",
        in_text_uses=in_text,
        bibliography_only=bibliography_only,
        elapsed_ms=timings_ms["contexts"],
    )

    themes = ""
    map_result_id: str | None = None
    highlighted_quotes: list[CitationHighlight] = []
    if not skip_summary and not _cancelled(cancel):
        stage_started = time.perf_counter()
        matched, themes, map_result_id, highlighted_quotes = (
            _summarize_with_scorecard_verifier(
            client,
            matched,
            target,
            target_summary=bundle.target_summary,
            limit=analysis_limit,
            on_event=on_event,
            cancel=cancel,
        )
        )
        timings_ms["verifier"] = round((time.perf_counter() - stage_started) * 1000)
        work_counts["verifier_papers"] = len(analysis_papers)

    counts = {
        "provider_edges": sum(bundle.provider_edge_counts.values()),
        "unique_citing": len(bundle.citing),
        "total_citations": total_citations,
        "match_attempts": match_attempts,
        "paperclip_matches": sum(1 for p in matched if p.paperclip_id),
        "readable_fulltext": sum(1 for p in matched if p.has_fulltext),
        "paperclip_fulltext": sum(1 for p in matched if p.has_fulltext),
        "analyzed_fulltext": sum(
            1
            for paper in matched
            if paper.has_fulltext and paper.analysis_status != "not_analyzed"
        ),
        "in_text_uses": sum(1 for p in matched if p.contexts),
        "bibliography_only": sum(
            1 for p in matched if p.bibliography_only and not p.contexts
        ),
    }

    importance: ImportanceScore | None = None

    cancelled = _cancelled(cancel)
    notice = None
    outcome = "ok"
    if cancelled:
        notice = ANALYSIS_CANCELLED_MESSAGE
        outcome = "cancelled"
    else:
        notice = assess_fulltext_notice(
            citing_count=int(counts.get("unique_citing") or 0),
            in_text_uses=int(counts.get("in_text_uses") or 0),
            readable_fulltext=int(counts.get("readable_fulltext") or 0),
            provider_errors=bundle.errors,
        )
        if notice == LIMITED_FULLTEXT_MESSAGE:
            outcome = "limited_fulltext"
            if importance is None or (importance.label or "") == "unscored":
                importance = ImportanceScore(
                    score=0,
                    label="unscored",
                    rationale=LIMITED_FULLTEXT_MESSAGE,
                    method="empty",
                )
        elif notice == PARTIAL_PROVIDERS_MESSAGE:
            outcome = "ok"

    timings_ms["total"] = round((time.perf_counter() - run_started) * 1000)
    work_counts["provider_edges"] = sum(bundle.provider_edge_counts.values())
    work_counts["unique_citing"] = len(bundle.citing)
    result = AnalysisResult(
        target=target,
        counts=counts,
        checks=bundle.checks.to_dict(),
        provider_edge_counts=bundle.provider_edge_counts,
        provider_errors=bundle.errors,
        citing_papers=matched,
        themes=themes,
        importance=importance,
        cancelled=cancelled,
        target_summary=bundle.target_summary,
        category_counts=citation_category_counts(matched),
        reach={
            "institution_count": bundle.institution_count,
            "discipline_count": bundle.discipline_count,
            "top_disciplines": bundle.top_disciplines,
            "complete": bundle.reach_complete,
        },
        citation_momentum=citation_momentum(bundle.citation_counts_by_year),
        highlighted_quotes=highlighted_quotes,
        timings_ms=timings_ms,
        work_counts=work_counts,
        notice=notice,
        outcome=outcome,
    )
    emit_event(on_event, "done", result=result.to_dict())
    return result


def iter_ndjson_events(
    client: Any,
    query: str,
    **kwargs: Any,
) -> Iterator[str]:
    """Run analysis and yield NDJSON event lines (including the final done event)."""
    queue: list[dict[str, Any]] = []
    lock = threading.Lock()

    def _on_event(event: dict[str, Any]) -> None:
        with lock:
            queue.append(event)

    result = run_analysis(client, query, on_event=_on_event, **kwargs)
    del result
    with lock:
        events = list(queue)
    for event in events:
        yield json.dumps(event, ensure_ascii=False)


def verify_scorecard_shard(
    client: Any,
    payload: dict[str, Any],
    *,
    on_event: EventCallback | None = None,
) -> dict[str, Any]:
    """Verify one durable group without repeating provider or matching work."""
    target_data = payload.get("target")
    paper_data = payload.get("papers")
    if not isinstance(target_data, dict) or not isinstance(paper_data, list):
        raise ValueError("scorecard shard requires target and papers")
    target = target_paper_from_dict(target_data)
    papers = [
        matched_paper_from_dict(paper)
        for paper in paper_data
        if isinstance(paper, dict)
    ]
    if not papers:
        raise ValueError("scorecard shard has no papers")
    papers, themes, map_result_id, highlights = (
        _summarize_with_scorecard_verifier(
            client,
            papers,
            target,
            target_summary=str(payload.get("target_summary") or ""),
            limit=len(papers),
            on_event=on_event,
        )
    )
    return {
        "papers": [paper.to_dict() for paper in papers],
        "themes": themes,
        "map_result_id": map_result_id,
        "highlighted_quotes": [
            highlight.to_dict() for highlight in highlights
        ],
    }


def register_cli(main_group: Any) -> None:
    """Register the ``citation-explorer`` Click command on the Paperclip group."""
    import click

    @main_group.command("citation-explorer-verify-shard", hidden=True)
    @click.argument(
        "payload_path",
        type=click.Path(exists=True, dir_okay=False, path_type=str),
    )
    def citation_explorer_verify_shard_cmd(payload_path: str) -> None:
        """Run one internal, durable scorecard verifier group."""
        from .app import _get_client

        with open(payload_path, encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict):
            raise click.ClickException("scorecard shard payload must be an object")

        def _print_event(event: dict[str, Any]) -> None:
            click.echo(json.dumps(event, ensure_ascii=False))

        try:
            result = verify_scorecard_shard(
                _get_client(),
                payload,
                on_event=_print_event,
            )
        except (OSError, ValueError) as exc:
            raise click.ClickException(str(exc)) from exc
        _print_event({"type": "done", "result": result})

    @main_group.command("citation-explorer")
    @click.argument("query", nargs=-1, required=True)
    @click.option(
        "--limit",
        default=200,
        show_default=True,
        type=int,
        help="Max citing works to fetch/match per provider.",
    )
    @click.option(
        "--select-doi",
        default=None,
        help="Disambiguate a title query by choosing this DOI.",
    )
    @click.option(
        "--skip-summary",
        is_flag=True,
        help="Skip per-paper summary synthesis.",
    )
    @click.option(
        "--events/--no-events",
        default=True,
        help="Emit newline-delimited JSON progress events (default: on).",
    )
    @click.pass_context
    def citation_explorer_cmd(
        ctx: Any,
        query: tuple[str, ...],
        limit: int,
        select_doi: str | None,
        skip_summary: bool,
        events: bool,
    ) -> None:
        """Resolve a paper, find citing works, and summarize Paperclip full-text uses.

        \b
        Examples:
            paperclip citation-explorer 10.1038/s41467-025-62346-0
            paperclip citation-explorer "https://www.nature.com/articles/s41586-019-1799-6"
            paperclip citation-explorer "ROSIE antibody design" --select-doi 10.1038/...
        """
        from .app import _get_client

        q = " ".join(query).strip()
        client = _get_client()

        def _print_event(event: dict[str, Any]) -> None:
            if events:
                click.echo(json.dumps(event, ensure_ascii=False))
            else:
                et = event.get("type")
                if et == "error":
                    click.echo(f"error: {event.get('message')}", err=True)
                elif et == "candidates":
                    click.echo("Multiple title matches:")
                    for c in event.get("candidates") or []:
                        click.echo(
                            f"  - {c.get('doi') or '(no doi)'}  {c.get('title', '')[:80]}"
                        )
                    click.echo("Re-run with --select-doi <DOI>")
                elif et == "done":
                    result = event.get("result") or {}
                    counts = result.get("counts") or {}
                    click.echo(
                        "done: "
                        + ", ".join(f"{k}={v}" for k, v in counts.items())
                    )
                    if not events:
                        click.echo(json.dumps(result, ensure_ascii=False, indent=2))

        result = run_analysis(
            client,
            q,
            select_doi=select_doi,
            limit=limit,
            skip_summary=skip_summary,
            on_event=_print_event,
        )
        if result.error and not result.candidates:
            raise SystemExit(1)
        if result.candidates and not select_doi:
            raise SystemExit(2)
